const HSK3_DATA = {"lessons":[{"id":1,"title_cn":"我们去机场接你们","title_pinyin":"Wǒmen qù jīchǎng jiē nǐmen","title_vn":"Chúng tôi đi đón các bạn ở sân bay","goals":["Có thể nghe hiểu và sử dụng định ngữ nhiều lớp để miêu tả đặc điểm của người hoặc sự vật.","Có thể nghe hiểu và giải quyết các vấn đề liên quan đến việc làm mất đồ vật.","Nắm vững cách dùng của đại từ nghi vấn, có thể diễn đạt thông tin về người, sự vật hoặc địa điểm không xác định."],"vocab":[{"hanzi":"以为","pinyin":"yǐwéi","pos":"dgt.","vn":"nghĩ rằng, cho rằng (nhưng thực tế không phải vậy)"},{"hanzi":"像","pinyin":"xiàng","pos":"dgt.","vn":"giống"},{"hanzi":"长","pinyin":"zhǎng","pos":"dgt.","vn":"lớn lên, phát triển"},{"hanzi":"身高","pinyin":"shēngāo","pos":"dt.","vn":"chiều cao"},{"hanzi":"米","pinyin":"mǐ","pos":"lượng.","vn":"mét"},{"hanzi":"瘦","pinyin":"shòu","pos":"tt.","vn":"gầy"},{"hanzi":"接","pinyin":"jiē","pos":"dgt.","vn":"đón"},{"hanzi":"行李","pinyin":"xíngli","pos":"dt.","vn":"hành lý"},{"hanzi":"丢","pinyin":"diū","pos":"dgt.","vn":"mất, làm mất"},{"hanzi":"箱子","pinyin":"xiāngzi","pos":"dt.","vn":"va li, hộp"},{"hanzi":"号码","pinyin":"hàomǎ","pos":"dt.","vn":"số (điện thoại, mã số)"},{"hanzi":"好像","pinyin":"hǎoxiàng","pos":"phó.","vn":"hình như, dường như"},{"hanzi":"重要","pinyin":"zhòngyào","pos":"tt.","vn":"quan trọng"},{"hanzi":"着急","pinyin":"zháojí","pos":"tt.","vn":"lo lắng, sốt ruột"},{"hanzi":"护照","pinyin":"hùzhào","pos":"dt.","vn":"hộ chiếu"},{"hanzi":"服务台","pinyin":"fúwùtái","pos":"dt.","vn":"quầy phục vụ, quầy lễ tân"},{"hanzi":"应该","pinyin":"yīnggāi","pos":"đtnn.","vn":"nên, phải"},{"hanzi":"站","pinyin":"zhàn","pos":"dgt.","vn":"đứng"},{"hanzi":"中间","pinyin":"zhōngjiān","pos":"dt.","vn":"ở giữa"},{"hanzi":"短","pinyin":"duǎn","pos":"tt.","vn":"ngắn"},{"hanzi":"头发","pinyin":"tóufa","pos":"dt.","vn":"tóc"},{"hanzi":"年轻","pinyin":"niánqīng","pos":"tt.","vn":"trẻ, trẻ tuổi"},{"hanzi":"发现","pinyin":"fāxiàn","pos":"dgt.","vn":"phát hiện"},{"hanzi":"不见","pinyin":"bújiàn","pos":"dgt.","vn":"biến mất, không thấy đâu"},{"hanzi":"带","pinyin":"dài","pos":"dgt.","vn":"mang theo, mang"},{"hanzi":"帮助","pinyin":"bāngzhù","pos":"dgt.","vn":"giúp đỡ"},{"hanzi":"照片","pinyin":"zhàopiàn","pos":"dt.","vn":"ảnh, hình chụp"}],"grammar":[{"title":"固定短语\"看上去/看起来\" - Cụm cố định \"看上去/看起来\"","explanation_vn":"Cụm từ cố định \"看上去\" và \"看起来\" được dùng để miêu tả vẻ ngoài hoặc trạng thái của một người hoặc một vật.","examples":[{"cn":"他们看上去有点儿像。","pinyin":"Tāmen kàn shàngqù yǒudiǎnr xiàng.","vn":""},{"cn":"这些菜看起来都很好吃。","pinyin":"Zhèxiē cài kàn qǐlái dōu hěn hǎochī.","vn":""},{"cn":"那个新来的老师看上去很年轻。","pinyin":"Nàge xīn lái de lǎoshī kàn shàngqù hěn niánqīng.","vn":""}]},{"title":"疑问代词的非疑问用法（1） - Cách dùng phi nghi vấn của đại từ nghi vấn (1)","explanation_vn":"Các đại từ nghi vấn như \"哪儿\", \"什么\", \"谁\", \"哪\" khi dùng trong câu trần thuật (không phải câu hỏi) biểu thị địa điểm, sự vật hoặc người không xác định hoặc không cần chỉ rõ cụ thể.","examples":[{"cn":"我好像在哪儿看到过这个箱子。","pinyin":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi.","vn":""},{"cn":"你吃点儿什么再走吧。","pinyin":"Nǐ chī diǎnr shénme zài zǒu ba.","vn":""},{"cn":"我们哪天一起去踢足球吧。","pinyin":"Wǒmen nǎ tiān yìqǐ qù tī zúqiú ba.","vn":""}]},{"title":"多项定语 - Định ngữ nhiều lớp (Multiple Attributives)","explanation_vn":"Trung tâm ngữ danh từ có thể đồng thời có nhiều định ngữ đứng trước. Các định ngữ này thường được sắp xếp theo thứ tự: thời gian/nơi chốn → động tác/trạng thái → đặc điểm. Cụm số lượng hoặc cụm chỉ định-lượng có vị trí tương đối linh hoạt, có thể đặt trước hoặc sau định ngữ biểu thị động tác hoặc trạng thái.","examples":[{"cn":"李文是那个穿着黑衣服的短头发的年轻人吗？","pinyin":"Lǐ Wén shì nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīng rén ma?","vn":""},{"cn":"昨天和家月一起看电影的两个人是我的朋友。","pinyin":"Zuótiān hé Jiāyuè yìqǐ kàn diànyǐng de liǎng ge rén shì wǒ de péngyou.","vn":""},{"cn":"我那件新买的白色的衣服在哪儿？","pinyin":"Wǒ nà jiàn xīn mǎi de báisè de yīfu zài nǎr?","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"这是杨同乐吗？他怎么跟白家月在一起？","pinyin":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?"},{"speaker":"王一雪","cn":"他不是杨同乐，他叫李文，是白家月的好朋友。","pinyin":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou."},{"speaker":"刘明","cn":"我还以为是同乐呢，他们看上去有点儿像。","pinyin":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kàn shàngqù yǒudiǎnr xiàng."},{"speaker":"王一雪","cn":"是长得有点儿像，但是他比同乐高，身高有一米八。","pinyin":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā."},{"speaker":"刘明","cn":"看起来也比同乐瘦一点儿。","pinyin":"Kàn qǐlái yě bǐ Tónglè shòu yìdiǎnr."},{"speaker":"王一雪","cn":"下个星期家月和李文要来北京，我去机场接他们。","pinyin":"Xià ge xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen."},{"speaker":"刘明","cn":"他们哪天到北京？我跟你一起去机场接他们吧。","pinyin":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba."}],"translation_vn":"Lưu Minh: Đây là Dương Đồng Nhạc à? Sao anh ấy lại ở cùng Bạch Gia Nguyệt vậy?\nVương Nhất Tuyết: Anh ấy không phải Dương Đồng Nhạc, anh ấy tên Lý Văn, là bạn thân của Bạch Gia Nguyệt.\nLưu Minh: Em còn tưởng là Đồng Nhạc chứ, nhìn họ hơi giống nhau.\nVương Nhất Tuyết: Đúng là trông hơi giống, nhưng anh ấy cao hơn Đồng Nhạc, cao một mét tám.\nLưu Minh: Nhìn cũng gầy hơn Đồng Nhạc một chút.\nVương Nhất Tuyết: Tuần sau Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh, em sẽ ra sân bay đón họ.\nLưu Minh: Hôm nào họ đến Bắc Kinh? Anh cùng em ra sân bay đón họ nhé.","audio_dialogue":"1-1.mp3","audio_vocab":"1-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"我的行李怎么还没出来？是不是丢了？","pinyin":"Wǒ de xíngli zěnme hái méi chūlái? Shì bú shì diū le?"},{"speaker":"李文","cn":"你的行李箱是什么样的？","pinyin":"Nǐ de xíngxiāng shì shénme yàng de?"},{"speaker":"白家月","cn":"是一个黑色的箱子，上面写着我的名字和电话号码。","pinyin":"Shì yí ge hēisè de xiāngzi, shàngmiàn xiězhe wǒ de míngzi hé diànhuà hàomǎ."},{"speaker":"李文","cn":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","pinyin":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi, shì bú shì yǒurén ná cuò le?"},{"speaker":"白家月","cn":"我们快找谁问一下吧，箱子里有不少重要的东西。","pinyin":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi li yǒu bùshǎo zhòngyào de dōngxi."},{"speaker":"李文","cn":"别着急，我们拿着护照和机票，去服务台问问吧。","pinyin":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba."}],"translation_vn":"Bạch Gia Nguyệt: Sao hành lý của mình vẫn chưa ra vậy? Có bị mất không nhỉ?\nLý Văn: Va li của cậu trông như thế nào?\nBạch Gia Nguyệt: Là một chiếc va li màu đen, trên đó có ghi tên và số điện thoại của mình.\nLý Văn: Hình như mình đã thấy chiếc va li này ở đâu đó rồi, hay là có ai lấy nhầm?\nBạch Gia Nguyệt: Chúng ta mau tìm ai đó hỏi thử đi, trong va li có không ít đồ quan trọng.\nLý Văn: Đừng lo lắng, chúng ta cầm theo hộ chiếu và vé máy bay, đến quầy phục vụ hỏi thử xem.","audio_dialogue":"1-3.mp3","audio_vocab":"1-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明","cn":"飞机早就到了，你看见白家月他们了吗？","pinyin":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?"},{"speaker":"王一雪","cn":"没有，他们应该快出来了。","pinyin":"Méiyǒu, tāmen yīnggāi kuài chūlái le."},{"speaker":"刘明","cn":"我们站到中间去吧，这样他们好找一些。","pinyin":"Wǒmen zhàn dào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē."},{"speaker":"王一雪","cn":"你看那个高个子的人是李文吗？","pinyin":"Nǐ kàn nàge gāo gèzi de rén shì Lǐ Wén ma?"},{"speaker":"刘明","cn":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","pinyin":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīng rén?"},{"speaker":"王一雪","cn":"对，那个人就是李文！你看，家月在他后面呢。","pinyin":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumiàn ne."}],"translation_vn":"Lưu Minh: Máy bay hạ cánh lâu rồi, em có thấy Bạch Gia Nguyệt họ chưa?\nVương Nhất Tuyết: Chưa, chắc họ sắp ra rồi.\nLưu Minh: Chúng ta đứng vào giữa đi, như vậy họ dễ tìm thấy hơn.\nVương Nhất Tuyết: Anh xem người cao cao kia có phải Lý Văn không?\nLưu Minh: Em nói người nào? Cái anh chàng trẻ tuổi tóc ngắn mặc áo đen đó à?\nVương Nhất Tuyết: Đúng rồi, người đó chính là Lý Văn! Anh xem kìa, Gia Nguyệt ở phía sau anh ấy đấy.","audio_dialogue":"1-5.mp3","audio_vocab":"1-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"昨天我到北京了。","pinyin":"Zuótiān wǒ dào Běijīng le."},{"speaker":"","cn":"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。","pinyin":"Suīrán lùshang huāle shí jǐ ge xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài."},{"speaker":"","cn":"到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。","pinyin":"Dào jīchǎng de shíhou, Jiāyuè fāxiàn xíngxiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodàole xíngxiāng."},{"speaker":"","cn":"走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。","pinyin":"Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlái jiù kànjiànle Wáng lǎoshī de jiějie, tā kàn qǐlái bǐ zhàopiàn shàng niánqīng."},{"speaker":"","cn":"晚上，一雪姐带我们去吃了一家很好吃的中国菜。","pinyin":"Wǎnshang, Yīxuě jiě dài wǒmen qù chīle yì jiā hěn hǎochī de Zhōngguó cài."}],"translation_vn":"Hôm qua mình đã đến Bắc Kinh. Tuy trên đường đi mất hơn mười mấy tiếng đồng hồ, nhưng vì ngồi cùng Gia Nguyệt nên mình cảm thấy thời gian trôi qua rất nhanh. Khi đến sân bay, Gia Nguyệt phát hiện va li bị mất, mình đưa cô ấy đến quầy phục vụ, giúp cô ấy tìm lại được va li. Khi ra khỏi sân bay, đã hơn tám giờ rồi, vừa ra ngoài chúng mình đã nhìn thấy chị gái của thầy Vương, chị ấy trông trẻ hơn trong ảnh. Buổi tối, chị Nhất Tuyết đưa chúng mình đi ăn một quán món Trung rất ngon.","audio_dialogue":"1-7.mp3","audio_vocab":"1-8.mp3"}]},{"id":2,"title_cn":"你们想吃什么就点什么","title_pinyin":"Nǐmen xiǎng chī shénme jiù diǎn shénme","title_vn":"Các bạn muốn ăn gì thì gọi món đó","goals":["Có thể nghe hiểu và nói về món ăn, dịch vụ của nhà hàng và thói quen ăn uống cá nhân.","Có thể nghe hiểu và sử dụng đại từ nghi vấn để chỉ bất kỳ đối tượng nào.","Hiểu biết về dụng cụ ăn uống mà người Trung Quốc sử dụng khi dùng bữa."],"vocab":[{"hanzi":"菜单","pinyin":"càidān","pos":"dt.","vn":"thực đơn"},{"hanzi":"又","pinyin":"yòu","pos":"phó.","vn":"vừa... vừa (dùng trong又...又...)"},{"hanzi":"饿","pinyin":"è","pos":"tt.","vn":"đói"},{"hanzi":"渴","pinyin":"kě","pos":"tt.","vn":"khát"},{"hanzi":"客气","pinyin":"kèqi","pos":"dgt./tt.","vn":"khách sáo; lịch sự"},{"hanzi":"饮料","pinyin":"yǐnliào","pos":"dt.","vn":"đồ uống"},{"hanzi":"好久","pinyin":"hǎojiǔ","pos":"tt.","vn":"đã lâu, lâu rồi"},{"hanzi":"服务","pinyin":"fúwù","pos":"dgt.","vn":"phục vụ"},{"hanzi":"员","pinyin":"yuán","pos":"htố.","vn":"(hậu tố thêm sau danh/động từ để chỉ người)"},{"hanzi":"双","pinyin":"shuāng","pos":"lượng.","vn":"đôi"},{"hanzi":"筷子","pinyin":"kuàizi","pos":"dt.","vn":"đũa"},{"hanzi":"勺子","pinyin":"sháozi","pos":"dt.","vn":"thìa, muỗng"},{"hanzi":"碗","pinyin":"wǎn","pos":"dt.","vn":"bát, chén"},{"hanzi":"马上","pinyin":"mǎshàng","pos":"phó.","vn":"ngay lập tức"},{"hanzi":"热情","pinyin":"rèqíng","pos":"tt.","vn":"nhiệt tình"},{"hanzi":"尝","pinyin":"cháng","pos":"dgt.","vn":"nếm, thử"},{"hanzi":"记","pinyin":"jì","pos":"dgt.","vn":"nhớ"},{"hanzi":"用","pinyin":"yòng","pos":"dgt.","vn":"ăn; uống; dùng"},{"hanzi":"鸡","pinyin":"jī","pos":"dt.","vn":"gà"},{"hanzi":"张","pinyin":"zhāng","pos":"lượng.","vn":"tờ, tấm (dùng cho giấy, tranh...)"},{"hanzi":"不用","pinyin":"búyòng","pos":"phó.","vn":"không cần"},{"hanzi":"选","pinyin":"xuǎn","pos":"dgt.","vn":"chọn"},{"hanzi":"外卖","pinyin":"wàimài","pos":"dt./dgt.","vn":"đồ ăn mang đi; giao đồ ăn"},{"hanzi":"方便","pinyin":"fāngbiàn","pos":"tt.","vn":"tiện lợi"},{"hanzi":"蛋糕","pinyin":"dàngāo","pos":"dt.","vn":"bánh kem"},{"hanzi":"只","pinyin":"zhǐ","pos":"phó.","vn":"chỉ"},{"hanzi":"方便面","pinyin":"fāngbiànmiàn","pos":"dt.","vn":"mì ăn liền"},{"hanzi":"简单","pinyin":"jiǎndān","pos":"tt.","vn":"đơn giản"}],"grammar":[{"title":"并列复句“又……又……” (Câu phức liên hợp “又……又……”)","explanation_vn":"Câu phức liên hợp \"又……又……\" được dùng kết hợp với tính từ, biểu thị người hoặc sự vật đồng thời có hai đặc điểm. Cấu trúc cơ bản: 又 + tính từ 1 + 又 + tính từ 2.","examples":[{"cn":"我现在还真是又饿又渴。","pinyin":"Wǒ xiànzài hái zhēnshi yòu è yòu kě.","vn":""},{"cn":"那个女孩儿又高又漂亮。","pinyin":"Nàge nǚháir yòu gāo yòu piàoliang.","vn":""},{"cn":"这个饭馆的菜又便宜又好吃。","pinyin":"Zhège fànguǎn de cài yòu piányi yòu hǎochī.","vn":""}]},{"title":"疑问代词的非疑问用法（2）(Cách dùng không nghi vấn của đại từ nghi vấn - phần 2)","explanation_vn":"Các đại từ nghi vấn như \"哪、哪儿、什么、谁、怎么\" còn có thể dùng để biểu thị ý phiếm chỉ (chỉ bất kỳ đối tượng nào), ví dụ \"谁\" chỉ bất kỳ người nào, \"什么\" chỉ bất kỳ vật gì; trong câu thường dùng phó từ \"都\" để hô ứng.","examples":[{"cn":"哪个菜都好吃。","pinyin":"Nǎge cài dōu hǎochī.","vn":""},{"cn":"这次旅游，我去哪儿都可以。","pinyin":"Zhè cì lǚyóu, wǒ qù nǎr dōu kěyǐ.","vn":""},{"cn":"我下午有时间，你想什么时候来都没问题。","pinyin":"Wǒ xiàwǔ yǒu shíjiān, nǐ xiǎng shénme shíhou lái dōu méi wèntí.","vn":""}]},{"title":"疑问代词的非疑问用法（3）(Cách dùng không nghi vấn của đại từ nghi vấn - phần 3)","explanation_vn":"Hai đại từ nghi vấn giống nhau có thể dùng để biểu thị ý phiếm chỉ, hô ứng với nhau, cùng chỉ một người, một việc, một cách thức, một thời điểm hoặc một địa điểm. Khi chủ ngữ của hai mệnh đề giống nhau, chủ ngữ của mệnh đề sau có thể lược bỏ; khi chủ ngữ của hai mệnh đề khác nhau, chủ ngữ thứ hai phải đặt trước \"就\".","examples":[{"cn":"你们想吃什么就点什么。","pinyin":"Nǐmen xiǎng chī shénme jiù diǎn shénme.","vn":""},{"cn":"你觉得哪个好看就买哪个。","pinyin":"Nǐ juéde nǎge hǎokàn jiù mǎi nǎge.","vn":""},{"cn":"你想去哪儿，我们就去哪儿。","pinyin":"Nǐ xiǎng qù nǎr, wǒmen jiù qù nǎr.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"家月、李文，你们看看菜单，想吃点儿什么？","pinyin":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?"},{"speaker":"李文","cn":"谢谢一雪姐，我都可以，你们点吧。","pinyin":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba."},{"speaker":"白家月","cn":"飞了这么远，现在还真是又饿又渴。","pinyin":"Fēile zhème yuǎn, xiànzài hái zhēnshi yòu è yòu kě."},{"speaker":"王一雪","cn":"那多点点儿，别客气。你们喝什么饮料？","pinyin":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?"},{"speaker":"白家月","cn":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","pinyin":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?"},{"speaker":"王一雪","cn":"没问题。你们看看还想吃什么。","pinyin":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme."}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, Lý Văn, hai em xem thực đơn đi, muốn ăn gì nào?\nLý Văn: Cảm ơn chị Nhất Tuyết, em ăn gì cũng được, các chị gọi đi ạ.\nBạch Gia Nguyệt: Bay xa như vậy, bây giờ đúng là vừa đói vừa khát.\nVương Nhất Tuyết: Vậy gọi nhiều một chút, đừng khách sáo. Các em uống đồ uống gì?\nBạch Gia Nguyệt: Đã lâu không uống trà Trung Quốc, cũng đã lâu không ăn sủi cảo rồi. Em muốn uống trà xanh, ăn sủi cảo, được không ạ?\nVương Nhất Tuyết: Không vấn đề gì. Các em xem còn muốn ăn gì nữa không.","audio_dialogue":"2-1.mp3","audio_vocab":"2-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","pinyin":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn."},{"speaker":"服务员","cn":"好的，请等一下，我马上去拿。","pinyin":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná."},{"speaker":"王一雪","cn":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","pinyin":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài."},{"speaker":"白家月","cn":"哪个菜都好吃。您点的这些菜真不错。","pinyin":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò."},{"speaker":"王一雪","cn":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","pinyin":"Zhèlǐ de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le."},{"speaker":"服务员","cn":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","pinyin":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng màn yòng."}],"translation_vn":"Vương Nhất Tuyết: Phục vụ ơi, cho chúng tôi thêm một đôi đũa, một cái thìa và một cái bát nữa.\nNhân viên phục vụ: Vâng ạ, xin chờ một chút, tôi đi lấy ngay.\nVương Nhất Tuyết: Dịch vụ của quán này rất nhiệt tình, món ăn cũng đều nấu rất ngon. Các em nếm thử xem có thích những món này không.\nBạch Gia Nguyệt: Món nào cũng ngon cả. Những món chị gọi thật tuyệt.\nVương Nhất Tuyết: Đồ ăn ở đây vừa rẻ vừa ngon, chúng tôi thường xuyên đến đây, nhân viên phục vụ đều nhớ những món chúng tôi thích ăn.\nNhân viên phục vụ: Chị Vương, chị thường xuyên đến ăn, hôm nay tặng chị ít hoa quả, mời chị dùng chậm rãi.","audio_dialogue":"2-3.mp3","audio_vocab":"2-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"这个鸡肉饭太好吃了，我要再来吃一次。","pinyin":"Zhège jīròu fàn tài hǎochī le, wǒ yào zài lái chī yí cì."},{"speaker":"李文","cn":"你可以拿走这张菜单，看看下次还吃点儿什么。","pinyin":"Nǐ kěyǐ ná zǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme."},{"speaker":"王一雪","cn":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","pinyin":"Búyòng ná càidān, zài shǒujī shang jiù néng kàndào, yě kěyǐ xuǎn hǎo le ràng tāmen gěi nǐ sòng."},{"speaker":"白家月","cn":"他们家还能送外卖？","pinyin":"Tāmen jiā hái néng sòng wàimài?"},{"speaker":"王一雪","cn":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","pinyin":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme."},{"speaker":"白家月","cn":"那真是太方便了！","pinyin":"Nà zhēnshi tài fāngbiàn le!"}],"translation_vn":"Bạch Gia Nguyệt: Món cơm gà này ngon quá, em phải đến ăn lại lần nữa mới được.\nLý Văn: Chị có thể mang tờ thực đơn này về, xem lần sau còn muốn ăn gì.\nVương Nhất Tuyết: Không cần mang thực đơn đâu, trên điện thoại là xem được rồi, cũng có thể chọn xong rồi để họ giao đến cho em.\nBạch Gia Nguyệt: Quán này còn giao đồ ăn nữa à?\nVương Nhất Tuyết: Đúng vậy, bây giờ rất nhiều nhà hàng đều có thể giao đồ ăn, muốn ăn gì thì gọi món đó.\nBạch Gia Nguyệt: Vậy thì tiện quá đi mất!","audio_dialogue":"2-5 @xitoytili_luoluodafang.mp3","audio_vocab":"2-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这些年在国外，我很少自己做饭。","pinyin":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuò fàn."},{"speaker":"","cn":"早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。","pinyin":"Zǎofàn wǒ chī yí ge miànbāo, yǒu shíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi."},{"speaker":"","cn":"午饭和晚饭也都在外面吃。","pinyin":"Wǔfàn hé wǎnfàn yě dōu zài wàimian chī."},{"speaker":"","cn":"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。","pinyin":"Kuài yào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqù chīfàn, jiā li yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎojǐ tiān zhǐ chī fāngbiànmiàn."},{"speaker":"","cn":"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！","pinyin":"Xiànzài huídào Zhōngguó le, měi tiān néng chīdào māma zuò de fàn, wǒ zhēnshi tài gāoxìng le!"},{"speaker":"","cn":"有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","pinyin":"Yǒu shíhou māma zhǐ zuò jǐ ge jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī."}],"translation_vn":"Những năm nay ở nước ngoài, tôi rất ít khi tự nấu ăn. Bữa sáng tôi ăn một chiếc bánh mì, có lúc ăn một miếng bánh kem, rồi uống thêm một ly cà phê. Bữa trưa và bữa tối cũng đều ăn ở ngoài. Vào lúc gần thi vừa bận vừa mệt, không có thời gian ra ngoài ăn, trong nhà lại chẳng có gì để ăn, có lẽ mấy ngày liền tôi chỉ ăn mì ăn liền. Bây giờ đã về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thực sự rất vui! Có lúc mẹ chỉ làm vài món đơn giản, tôi cũng rất thích ăn, vì chẳng có gì ngon bằng cơm mẹ nấu.","audio_dialogue":"2-7 @xitoytili_luoluodafang.mp3","audio_vocab":"2-8 @xitoytili_luoluodafang.mp3"}]},{"id":3,"title_cn":"这个小区挺好的","title_pinyin":"Zhège xiǎoqū tǐng hǎo de","title_vn":"Khu dân cư này khá tốt","goals":["Có thể nghe hiểu và trò chuyện về môi trường sống và tình hình nhà cửa.","Có thể nghe hiểu và sử dụng \"挺\" (tǐng), \"坏了\" (huài le) để biểu thị mức độ.","Nắm vững cách dùng \"就\" (jiù) và \"才\" (cái), có thể diễn đạt thông tin về thời điểm sớm/muộn, nhanh/chậm của hành động."],"vocab":[{"hanzi":"初中","pinyin":"chūzhōng","pos":"dt.","vn":"trường trung học cơ sở (cấp 2)"},{"hanzi":"咱们","pinyin":"zánmen","pos":"đt.","vn":"chúng ta"},{"hanzi":"换","pinyin":"huàn","pos":"dgt.","vn":"đổi, thay"},{"hanzi":"房子","pinyin":"fángzi","pos":"dt.","vn":"nhà, căn nhà"},{"hanzi":"小区","pinyin":"xiǎoqū","pos":"dt.","vn":"khu dân cư, khu chung cư"},{"hanzi":"环境","pinyin":"huánjìng","pos":"dt.","vn":"môi trường, hoàn cảnh xung quanh"},{"hanzi":"挺","pinyin":"tǐng","pos":"phó.","vn":"khá, rất"},{"hanzi":"空调","pinyin":"kōngtiáo","pos":"dt.","vn":"điều hòa, máy lạnh"},{"hanzi":"洗衣机","pinyin":"xǐyījī","pos":"dt.","vn":"máy giặt"},{"hanzi":"层","pinyin":"céng","pos":"lượng.","vn":"tầng"},{"hanzi":"花园","pinyin":"huāyuán","pos":"dt.","vn":"vườn hoa"},{"hanzi":"灯","pinyin":"dēng","pos":"dt.","vn":"đèn"},{"hanzi":"关","pinyin":"guān","pos":"dgt.","vn":"tắt, đóng"},{"hanzi":"冰箱","pinyin":"bīngxiāng","pos":"dt.","vn":"tủ lạnh"},{"hanzi":"卫生间","pinyin":"wèishēngjiān","pos":"dt.","vn":"nhà vệ sinh"},{"hanzi":"打扫","pinyin":"dǎsǎo","pos":"dgt.","vn":"dọn dẹp, quét dọn"},{"hanzi":"搬家","pinyin":"bānjiā","pos":"dgt.","vn":"chuyển nhà, dọn nhà"},{"hanzi":"办","pinyin":"bàn","pos":"dgt.","vn":"làm, xử lý (thủ tục)"},{"hanzi":"信用卡","pinyin":"xìnyòngkǎ","pos":"dt.","vn":"thẻ tín dụng"},{"hanzi":"还","pinyin":"huán","pos":"dgt.","vn":"trả (nợ, tiền)"},{"hanzi":"听说","pinyin":"tīngshuō","pos":"dgt.","vn":"nghe nói"},{"hanzi":"银行","pinyin":"yínháng","pos":"dt.","vn":"ngân hàng"},{"hanzi":"才","pinyin":"cái","pos":"phó.","vn":"mới (lúc đó mới...)"},{"hanzi":"纸","pinyin":"zhǐ","pos":"dt.","vn":"giấy"},{"hanzi":"搬","pinyin":"bān","pos":"dgt.","vn":"chuyển, dọn, khiêng"},{"hanzi":"需要","pinyin":"xūyào","pos":"dgt.","vn":"cần, nhu cầu"}],"grammar":[{"title":"程度副词\"挺\" (tǐng) - Phó từ chỉ mức độ \"挺\"","explanation_vn":"Phó từ chỉ mức độ \"挺\" dùng trước tính từ hoặc động từ tâm lý, biểu thị mức độ khá cao, thường dùng trong khẩu ngữ. Cấu trúc cơ bản: 挺 + tính từ/động từ tâm lý + 的.","examples":[{"cn":"这个小区环境挺好的。","pinyin":"Zhège xiǎoqū huánjìng tǐng hǎo de.","vn":""},{"cn":"这家饭馆的菜挺好吃的。","pinyin":"Zhè jiā fànguǎn de cài tǐng hǎochī de.","vn":""},{"cn":"买这个吧，我挺喜欢这个颜色的。","pinyin":"Mǎi zhège ba, wǒ tǐng xǐhuan zhège yánsè de.","vn":""}]},{"title":"程度补语（1）\"坏了\" (huài le) - Bổ ngữ chỉ mức độ (1)","explanation_vn":"Bổ ngữ chỉ mức độ \"坏了\" đặt sau tính từ, biểu thị mức độ cực cao, mang giọng điệu phóng đại, thường dùng trong tình huống mang nghĩa tiêu cực.","examples":[{"cn":"我这几天忙坏了。","pinyin":"Wǒ zhè jǐ tiān máng huài le.","vn":""},{"cn":"我渴坏了，哪里能买水？","pinyin":"Wǒ kě huài le, nǎlǐ néng mǎi shuǐ?","vn":""},{"cn":"这几天非常忙，大家都累坏了。","pinyin":"Zhè jǐ tiān fēicháng máng, dàjiā dōu lèi huài le.","vn":""}]},{"title":"\"就\"和\"才\" (jiù/cái) - So sánh \"就\" và \"才\"","explanation_vn":"Phó từ \"就\" và \"才\" dùng trước động từ làm trạng ngữ. \"就\" biểu thị người nói cho rằng động tác xảy ra sớm, diễn ra nhanh và thuận lợi; \"才\" biểu thị người nói cho rằng động tác xảy ra muộn, diễn ra chậm và không thuận lợi.","examples":[{"cn":"中国银行很近，走路几分钟就能到。","pinyin":"Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào.","vn":""},{"cn":"我下午要去医院，很晚才能回来。","pinyin":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","vn":""},{"cn":"我早上五点就起床了。","pinyin":"Wǒ zǎoshang wǔ diǎn jiù qǐchuáng le.","vn":""},{"cn":"坐火车去北京，五个小时才能到。","pinyin":"Zuò huǒchē qù Běijīng, wǔ gè xiǎoshí cái néng dào.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","pinyin":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí gè jìn diǎnr de fángzi ba."},{"speaker":"刘明","cn":"好啊，我上网看看。你觉得这个小区怎么样？","pinyin":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?"},{"speaker":"王一雪","cn":"环境挺好的，离地铁站还不远。","pinyin":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn."},{"speaker":"刘明","cn":"房子里面也不错，空调和洗衣机都是新的。","pinyin":"Fángzi lǐmiàn yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de."},{"speaker":"王一雪","cn":"是不错，但是我不喜欢住一层。","pinyin":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yì céng."},{"speaker":"刘明","cn":"这个一层带一个小花园，我觉得咱们可以去看看。","pinyin":"Zhège yì céng dài yí gè xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan."}],"translation_vn":"Vương Nhất Tuyết: Trường cấp 2 của Tiểu Tuyết cách nhà hơi xa, chúng ta đổi một căn nhà gần hơn một chút đi.\nLưu Minh: Được đấy, để anh lên mạng xem thử. Em thấy khu dân cư này thế nào?\nVương Nhất Tuyết: Môi trường khá tốt, cách ga tàu điện ngầm cũng không xa.\nLưu Minh: Bên trong nhà cũng không tệ, điều hòa và máy giặt đều là đồ mới.\nVương Nhất Tuyết: Đúng là không tệ, nhưng em không thích ở tầng một.\nLưu Minh: Tầng một này có kèm một khu vườn nhỏ, anh thấy chúng ta có thể đi xem thử.","audio_dialogue":"3-1 @xitoytili_luoluodafang.mp3","audio_vocab":"3-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"我今天早上来的时候，灯还开着。","pinyin":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe."},{"speaker":"刘明","cn":"我这几天忙坏了，可能走的时候忘关了。","pinyin":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le."},{"speaker":"王一雪","cn":"冰箱不能用，这些吃的东西放在哪儿？","pinyin":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?"},{"speaker":"刘明","cn":"不可能吧？冰箱是新买的，我来看看。","pinyin":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan."},{"speaker":"王一雪","cn":"洗衣机也坏了吗？","pinyin":"Xǐyījī yě huài le ma?"},{"speaker":"刘明","cn":"没坏，但是卫生间没打扫好，还不能洗衣服。","pinyin":"Méi huài, dànshì wèishēngjiān méi dǎsǎo hǎo, hái bù néng xǐ yīfu."},{"speaker":"王一雪","cn":"星期天我们真的能搬家吗？","pinyin":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?"}],"translation_vn":"Vương Nhất Tuyết: Sáng nay lúc em đến, đèn vẫn còn bật.\nLưu Minh: Mấy hôm nay anh bận muốn chết, có thể lúc đi quên tắt rồi.\nVương Nhất Tuyết: Tủ lạnh không dùng được, mấy thứ đồ ăn này để ở đâu đây?\nLưu Minh: Không thể nào? Tủ lạnh mới mua mà, để anh xem thử.\nVương Nhất Tuyết: Máy giặt cũng hỏng rồi à?\nLưu Minh: Không hỏng, nhưng nhà vệ sinh chưa dọn xong, vẫn chưa giặt quần áo được.\nVương Nhất Tuyết: Chủ nhật chúng ta có thật sự chuyển nhà được không?","audio_dialogue":"3-3 @xitoytili_luoluodafang.mp3","audio_vocab":"3-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"这个月花了不少钱。","pinyin":"Zhège yuè huā le bù shǎo qián."},{"speaker":"刘明","cn":"是的，我们买了很多搬家时要用的东西。","pinyin":"Shì de, wǒmen mǎi le hěn duō bānjiā shí yào yòng de dōngxi."},{"speaker":"王一雪","cn":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","pinyin":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànmàn huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bàn le xìnyòngkǎ mǎi dōngxi hái néng piányi."},{"speaker":"刘明","cn":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","pinyin":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?"},{"speaker":"王一雪","cn":"今天下午？","pinyin":"Jīntiān xiàwǔ?"},{"speaker":"刘明","cn":"我下午要去医院，很晚才能回来。","pinyin":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái."},{"speaker":"王一雪","cn":"那我下午自己去吧。","pinyin":"Nà wǒ xiàwǔ zìjǐ qù ba."}],"translation_vn":"Vương Nhất Tuyết: Tháng này tiêu không ít tiền nhỉ.\nLưu Minh: Đúng vậy, chúng ta đã mua rất nhiều đồ cần dùng khi chuyển nhà.\nVương Nhất Tuyết: Chúng ta làm một thẻ tín dụng đi, tiền tiêu có thể trả dần dần. Nghe nói dịch vụ của Ngân hàng Trung Quốc khá tốt, làm thẻ tín dụng rồi mua đồ còn được rẻ hơn.\nLưu Minh: Được đấy! Ngân hàng Trung Quốc rất gần, đi bộ vài phút là đến. Chúng ta đi khi nào?\nVương Nhất Tuyết: Chiều nay nhé?\nLưu Minh: Chiều nay anh phải đi bệnh viện, rất muộn mới về được.\nVương Nhất Tuyết: Vậy chiều nay em tự đi vậy.","audio_dialogue":"3-5 @xitoytili_luoluodafang.mp3","audio_vocab":"3-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"dialogue","lines":[{"speaker":"刘明","cn":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","pinyin":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuìduō yì tiān jiù néng bān wán."},{"speaker":"王一雪","cn":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","pinyin":"Wǒ juéde xià gè yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xiàzhōu qù dǎsǎo xīnjiā, zhème duō shìqing zuìshǎo xūyào liǎng gè xīngqī cái néng zuò wán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī."}],"translation_vn":"Lưu Minh: Anh thấy tuần này là có thể chuyển nhà được rồi. Ngày mai anh đi mua mấy cái thùng giấy, rất nhanh là chuẩn bị xong thôi. Hôm chuyển nhà, anh muốn mời vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong.\nVương Nhất Tuyết: Em thấy tháng sau mới chuyển nhà được. Tuần này bắt đầu chuẩn bị, tuần sau đi dọn dẹp nhà mới, nhiều việc như vậy ít nhất cần hai tuần mới làm xong. Hôm chuyển nhà, chúng ta nên tìm một công ty chuyển nhà.","audio_dialogue":"3-7 @xitoytili_luoluodafang.mp3","audio_vocab":"3-8 @xitoytili_luoluodafang.mp3"}]},{"id":4,"title_cn":"这家宾馆跟别的都不一样","title_pinyin":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng","title_vn":"Khách sạn này khác hẳn những nơi khác","goals":["Có thể nghe hiểu và trao đổi về kế hoạch kỳ nghỉ, diễn đạt cảm nhận trong quá trình du lịch.","Có thể nghe hiểu và diễn đạt ý nghĩa phủ định hoàn toàn.","Nắm được cách dùng của \"除了\", có thể diễn đạt ý loại trừ hoặc bổ sung."],"vocab":[{"hanzi":"假期","pinyin":"jiàqī","pos":"dt.","vn":"kỳ nghỉ"},{"hanzi":"海","pinyin":"hǎi","pos":"dt.","vn":"biển"},{"hanzi":"草原","pinyin":"cǎoyuán","pos":"dt.","vn":"thảo nguyên"},{"hanzi":"主意","pinyin":"zhǔyi","pos":"dt.","vn":"ý kiến, chủ ý"},{"hanzi":"骑","pinyin":"qí","pos":"dgt.","vn":"cưỡi"},{"hanzi":"马","pinyin":"mǎ","pos":"dt.","vn":"ngựa"},{"hanzi":"羊","pinyin":"yáng","pos":"dt.","vn":"cừu, dê"},{"hanzi":"月亮","pinyin":"yuèliang","pos":"dt.","vn":"mặt trăng"},{"hanzi":"一定","pinyin":"yídìng","pos":"phó.","vn":"nhất định"},{"hanzi":"刻","pinyin":"kè","pos":"lượng.","vn":"khắc (15 phút)"},{"hanzi":"起飞","pinyin":"qǐfēi","pos":"dgt.","vn":"cất cánh"},{"hanzi":"宾馆","pinyin":"bīnguǎn","pos":"dt.","vn":"khách sạn"},{"hanzi":"特别","pinyin":"tèbié","pos":"tt./phó.","vn":"đặc biệt"},{"hanzi":"别的","pinyin":"biéde","pos":"đt.","vn":"cái khác"},{"hanzi":"一样","pinyin":"yíyàng","pos":"tt.","vn":"giống nhau"},{"hanzi":"牛","pinyin":"niú","pos":"dt.","vn":"bò"},{"hanzi":"相机","pinyin":"xiàngjī","pos":"dt.","vn":"máy ảnh"},{"hanzi":"欢迎","pinyin":"huānyíng","pos":"dgt.","vn":"hoan nghênh, chào đón"},{"hanzi":"司机","pinyin":"sījī","pos":"dt.","vn":"tài xế"},{"hanzi":"晚点","pinyin":"wǎndiǎn","pos":"dgt.","vn":"trễ giờ (tàu xe)"},{"hanzi":"久","pinyin":"jiǔ","pos":"tt.","vn":"lâu"},{"hanzi":"除了","pinyin":"chúle","pos":"giới.","vn":"ngoài, trừ"},{"hanzi":"以外","pinyin":"yǐwài","pos":"dt.","vn":"ngoài ra"},{"hanzi":"先","pinyin":"xiān","pos":"phó.","vn":"trước"},{"hanzi":"一直","pinyin":"yìzhí","pos":"phó.","vn":"luôn, mãi"},{"hanzi":"干净","pinyin":"gānjìng","pos":"tt.","vn":"sạch sẽ"},{"hanzi":"满意","pinyin":"mǎnyì","pos":"dgt.","vn":"hài lòng"}],"grammar":[{"title":"固定格式\"一……也/都+不/没……\" - Cụm cố định \"一……也/都+不/没……\"","explanation_vn":"Cụm cố định \"一……也/都+不/没……\" biểu thị ý phủ định hoàn toàn. Đôi khi \"一+lượng từ\" phía trước có thể thay bằng \"一点儿\". Khi vị ngữ là tính từ, thường dùng mẫu \"一点儿也/都+不/没+tính từ\" để biểu thị phủ định hoàn toàn.","examples":[{"cn":"她一件衣服都不想买。","pinyin":"Tā yí jiàn yīfu dōu bù xiǎng mǎi.","vn":""},{"cn":"我一个中国电影也没看过。","pinyin":"Wǒ yí ge Zhōngguó diànyǐng yě méi kànguò.","vn":""},{"cn":"我一点儿东西也不想吃。","pinyin":"Wǒ yìdiǎnr dōngxi yě bù xiǎng chī.","vn":""},{"cn":"他对打球一点儿兴趣都没有。","pinyin":"Tā duì dǎqiú yìdiǎnr xìngqù dōu méiyǒu.","vn":""},{"cn":"草原一点儿也不冷。","pinyin":"Cǎoyuán yìdiǎnr yě bù lěng.","vn":""},{"cn":"他们一点儿也没着急。","pinyin":"Tāmen yìdiǎnr yě méi zháojí.","vn":""}]},{"title":"比较句（9） - Câu so sánh (9)","explanation_vn":"Câu so sánh \"A跟B一样\" biểu thị A và B sau khi so sánh có kết quả giống nhau. Phía sau \"一样\" có thể dùng tính từ để chỉ rõ phương diện so sánh, cấu trúc cơ bản: A跟B一样+tính từ. Dạng phủ định thì thêm \"不\" trước \"一样\".","examples":[{"cn":"这家宾馆跟别的都不一样。","pinyin":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng.","vn":""},{"cn":"他买的新手机跟我的一样。","pinyin":"Tā mǎi de xīn shǒujī gēn wǒ de yíyàng.","vn":""},{"cn":"这个房间跟那个房间一样大。","pinyin":"Zhège fángjiān gēn nàge fángjiān yíyàng dà.","vn":""}]},{"title":"固定格式\"除了……（以外），……都/还/也……\" - Cụm cố định \"除了……（以外），……都/还/也……\"","explanation_vn":"\"除了……（以外），……都……\" biểu thị trong một phạm vi nào đó, loại trừ một bộ phận, các phần còn lại đều ở cùng một tình huống; \"以外\" có thể lược bỏ. \"除了……（以外），……还/也……\" biểu thị loại trừ một bộ phận, đồng thời bổ sung thêm cái khác. Chủ ngữ của câu đặt ở đầu câu, hoặc đặt trước \"还/也\".","examples":[{"cn":"除了我以外，大家都在玩手机。","pinyin":"Chúle wǒ yǐwài, dàjiā dōu zài wán shǒujī.","vn":""},{"cn":"除了这个汉字，别的汉字我都会写。","pinyin":"Chúle zhège Hànzì, biéde Hànzì wǒ dōu huì xiě.","vn":""},{"cn":"除了这个行李箱以外，还有别的东西吗？","pinyin":"Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vn":""},{"cn":"除了唱歌以外，他也喜欢跳舞。","pinyin":"Chúle chànggē yǐwài, tā yě xǐhuan tiàowǔ.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"这个假期咱们去哪儿玩玩吧。","pinyin":"Zhège jiàqī zánmen qù nǎr wánwan ba."},{"speaker":"王一飞","cn":"好啊，你想去哪儿，咱们就去哪儿。","pinyin":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr."},{"speaker":"杨同乐","cn":"你喜欢海，找个海边住几天，怎么样？","pinyin":"Nǐ xǐhuan hǎi, zhǎo ge hǎibiān zhù jǐ tiān, zěnmeyàng?"},{"speaker":"王一飞","cn":"现在去海边有点儿冷。","pinyin":"Xiànzài qù hǎibiān yǒudiǎnr lěng."},{"speaker":"杨同乐","cn":"那去草原吧？草原一点儿也不冷。","pinyin":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng."},{"speaker":"王一飞","cn":"这个主意好！我好久没骑马了。","pinyin":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qí mǎ le."},{"speaker":"杨同乐","cn":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","pinyin":"Duì, zài cǎoyuán shàng qí mǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒuyìsi."}],"translation_vn":"Dương Đồng Nhạc: Kỳ nghỉ này chúng ta đi đâu chơi đi.\nVương Nhất Phi: Được đấy, cậu muốn đi đâu, chúng ta đi đó.\nDương Đồng Nhạc: Cậu thích biển, tìm một vùng biển ở vài ngày, thế nào?\nVương Nhất Phi: Bây giờ đi biển hơi lạnh.\nDương Đồng Nhạc: Vậy đi thảo nguyên nhé? Thảo nguyên chẳng lạnh chút nào.\nVương Nhất Phi: Ý này hay đấy! Mình lâu rồi không cưỡi ngựa.\nDương Đồng Nhạc: Đúng vậy, ở thảo nguyên cưỡi ngựa, ăn thịt cừu, ngắm trăng, chắc chắn rất thú vị.","audio_dialogue":"4-1 @xitoytili_luoluodafang.mp3","audio_vocab":"4-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"出去玩的机票买好了吗？","pinyin":"Chūqù wán de jīpiào mǎihǎo le ma?"},{"speaker":"王一飞","cn":"买好了。星期六上午十点一刻起飞。","pinyin":"Mǎihǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi."},{"speaker":"杨同乐","cn":"宾馆也选好了吗？","pinyin":"Bīnguǎn yě xuǎnhǎo le ma?"},{"speaker":"王一飞","cn":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","pinyin":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!"},{"speaker":"杨同乐","cn":"太好了！你看看要带什么东西？","pinyin":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?"},{"speaker":"王一飞","cn":"我们不用带太多东西，别忘了拿上新买的相机。","pinyin":"Wǒmen búyòng dài tài duō dōngxi, bié wàng le ná shàng xīn mǎi de xiàngjī."},{"speaker":"杨同乐","cn":"一定不会忘带的。我现在就去准备行李。","pinyin":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli."}],"translation_vn":"Dương Đồng Nhạc: Vé máy bay đi chơi mua xong chưa?\nVương Nhất Phi: Mua xong rồi. Sáng thứ Bảy mười giờ mười lăm cất cánh.\nDương Đồng Nhạc: Khách sạn cũng chọn xong rồi chứ?\nVương Nhất Phi: Rồi, khách sạn này rất đặc biệt, khác hẳn những nơi khác, vừa ra cửa là thấy bò với cừu!\nDương Đồng Nhạc: Tuyệt quá! Cậu xem cần mang gì không?\nVương Nhất Phi: Chúng ta không cần mang quá nhiều đồ, đừng quên mang theo máy ảnh mới mua.\nDương Đồng Nhạc: Chắc chắn sẽ không quên mang đâu. Mình đi chuẩn bị hành lý ngay đây.","audio_dialogue":"4-3 @xitoytili_luoluodafang.mp3","audio_vocab":"4-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"小李","cn":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","pinyin":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ."},{"speaker":"杨同乐","cn":"您好！不好意思，飞机晚点了，让您久等了。","pinyin":"Nín hǎo! Bù hǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le."},{"speaker":"小李","cn":"没关系。除了这个行李箱以外，还有别的东西吗？","pinyin":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?"},{"speaker":"杨同乐","cn":"还有一个包，我自己拿就可以。","pinyin":"Hái yǒu yí ge bāo, wǒ zìjǐ ná jiù kěyǐ."},{"speaker":"小李","cn":"车在一层，请跟我来。","pinyin":"Chē zài yī céng, qǐng gēn wǒ lái."},{"speaker":"杨同乐","cn":"我们住的宾馆离机场远吗？","pinyin":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?"},{"speaker":"小李","cn":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","pinyin":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dào le kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen."}],"translation_vn":"Tiểu Lý: Chào mừng hai vị! Tôi là tài xế của hai vị, tôi họ Lý, gọi tôi là Tiểu Lý là được.\nDương Đồng Nhạc: Chào anh! Xin lỗi, máy bay trễ giờ, để anh chờ lâu rồi.\nTiểu Lý: Không sao. Ngoài chiếc vali này ra, còn đồ gì khác không?\nDương Đồng Nhạc: Còn một cái túi nữa, tôi tự cầm được.\nTiểu Lý: Xe đỗ ở tầng một, mời đi theo tôi.\nDương Đồng Nhạc: Khách sạn chúng tôi ở có xa sân bay không?\nTiểu Lý: Không xa, ba mươi phút là tới. Hai vị đến nơi có thể nghỉ ngơi một chút, đến giờ ăn tối tôi sẽ gọi hai vị.","audio_dialogue":"4-5.mp3","audio_vocab":"4-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天是我们旅游的第一天。我们很早就起床去机场了，没想到飞机晚点了。我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。他特别热情，路上给我们介绍了很多东西，还准备了水果。宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","pinyin":"Jīntiān shì wǒmen lǚyóu de dì-yī tiān. Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le. Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí. Tā tèbié rèqíng, lùshang gěi wǒmen jièshào le hěn duō dōngxi, hái zhǔnbèi le shuǐguǒ. Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì."}],"translation_vn":"Hôm nay là ngày đầu tiên của chuyến du lịch chúng tôi. Chúng tôi dậy rất sớm để ra sân bay, không ngờ máy bay bị trễ giờ. Khi chúng tôi đến nơi, trời đã tối rồi, nhưng tài xế Tiểu Lý vẫn luôn chờ chúng tôi ở sân bay, không hề sốt ruột chút nào. Anh ấy rất nhiệt tình, trên đường giới thiệu cho chúng tôi rất nhiều thứ, còn chuẩn bị sẵn hoa quả. Phòng khách sạn đẹp đúng như tôi tưởng tượng, vừa rộng vừa sạch sẽ, tôi rất hài lòng.","audio_dialogue":"4-7.mp3","audio_vocab":"4-8.mp3"}]},{"id":5,"title_cn":"这样的照片才好看","title_pinyin":"Zhèyàng de zhàopiàn cái hǎokàn","title_vn":"Ảnh như thế này mới đẹp","goals":["Có thể nghe hiểu và giới thiệu về cuộc sống giải trí yêu thích của bản thân.","Có thể nghe hiểu và diễn đạt hai hành động xảy ra kế tiếp nhau.","Nắm được cách dùng của câu tồn hiện (3), có thể diễn đạt sự xuất hiện hoặc biến mất của người hay sự vật."],"vocab":[{"hanzi":"总是","pinyin":"zǒngshì","pos":"phó.","vn":"luôn luôn"},{"hanzi":"终于","pinyin":"zhōngyú","pos":"phó.","vn":"cuối cùng"},{"hanzi":"爬","pinyin":"pá","pos":"dgt.","vn":"leo, trèo"},{"hanzi":"山","pinyin":"shān","pos":"dt.","vn":"núi"},{"hanzi":"锻炼","pinyin":"duànliàn","pos":"dgt.","vn":"rèn luyện, tập luyện"},{"hanzi":"照","pinyin":"zhào","pos":"dgt.","vn":"chụp (ảnh)"},{"hanzi":"鞋","pinyin":"xié","pos":"dt.","vn":"giày"},{"hanzi":"大衣","pinyin":"dàyī","pos":"dt.","vn":"áo khoác dài"},{"hanzi":"拍照","pinyin":"pāizhào","pos":"dgt.","vn":"chụp ảnh"},{"hanzi":"感兴趣","pinyin":"gǎn xìngqù","pos":"dgt.","vn":"hứng thú, quan tâm"},{"hanzi":"照相","pinyin":"zhàoxiàng","pos":"dgt.","vn":"chụp ảnh"},{"hanzi":"难看","pinyin":"nánkàn","pos":"tt.","vn":"xấu, khó coi"},{"hanzi":"比较","pinyin":"bǐjiào","pos":"dgt./phó.","vn":"so sánh; tương đối"},{"hanzi":"水平","pinyin":"shuǐpíng","pos":"dt.","vn":"trình độ"},{"hanzi":"太阳","pinyin":"tàiyáng","pos":"dt.","vn":"mặt trời"},{"hanzi":"树","pinyin":"shù","pos":"dt.","vn":"cây"},{"hanzi":"干","pinyin":"gàn","pos":"dgt.","vn":"làm"},{"hanzi":"电","pinyin":"diàn","pos":"dt.","vn":"điện"},{"hanzi":"收到","pinyin":"shōudào","pos":"dgt.","vn":"nhận được"},{"hanzi":"封","pinyin":"fēng","pos":"lượng.","vn":"bức, phong (thư)"},{"hanzi":"邮件","pinyin":"yóujiàn","pos":"dt.","vn":"thư điện tử, bưu kiện"},{"hanzi":"难过","pinyin":"nánguò","pos":"tt.","vn":"buồn"},{"hanzi":"哈哈","pinyin":"hāhā","pos":"ct.","vn":"haha (tiếng cười)"},{"hanzi":"音乐","pinyin":"yīnyuè","pos":"dt.","vn":"âm nhạc"},{"hanzi":"兴趣","pinyin":"xìngqù","pos":"dt.","vn":"hứng thú, sở thích"},{"hanzi":"会","pinyin":"huì","pos":"dt.","vn":"buổi (hòa nhạc...), hội"},{"hanzi":"结束","pinyin":"jiéshù","pos":"dgt.","vn":"kết thúc"}],"grammar":[{"title":"程度补语（2） - Bổ ngữ trình độ (2)","explanation_vn":"Bổ ngữ trình độ \"得很\" dùng sau tính từ, biểu thị mức độ cao, thường dùng trong khẩu ngữ.","examples":[{"cn":"现在天气好得很。","pinyin":"Xiànzài tiānqì hǎo de hěn.","vn":""},{"cn":"房间里面热得很。","pinyin":"Fángjiān lǐmiàn rè de hěn.","vn":""},{"cn":"我觉得爬山累得很。","pinyin":"Wǒ juéde pá shān lèi de hěn.","vn":""}]},{"title":"量词重叠 - Láy lượng từ","explanation_vn":"Trong tiếng Hán, rất nhiều lượng từ có thể láy lại để nhấn mạnh mỗi thành viên trong một phạm vi nào đó đều có một đặc điểm nhất định, phía sau thường dùng \"都\".","examples":[{"cn":"这些照片张张都非常好看。（=每张照片都非常好看。）","pinyin":"Zhèxiē zhàopiàn zhāng zhāng dōu fēicháng hǎokàn. (= Měi zhāng zhàopiàn dōu fēicháng hǎokàn.)","vn":""},{"cn":"这些苹果个个都很大。（=每个苹果都很大。）","pinyin":"Zhèxiē píngguǒ gè gè dōu hěn dà. (= Měi ge píngguǒ dōu hěn dà.)","vn":""},{"cn":"我想出去拍照，但是天天下雨。（=每天都下雨。）","pinyin":"Wǒ xiǎng chūqù pāizhào, dànshì tiān tiān xiàyǔ. (= Měi tiān dōu xiàyǔ.)","vn":""}]},{"title":"存现句（3） - Câu tồn hiện (3)","explanation_vn":"Trong tiếng Hán, để trần thuật việc người hay sự vật xuất hiện hoặc biến mất ở một nơi nào đó, có thể dùng câu tồn hiện. Cấu trúc cơ bản: từ/cụm từ chỉ nơi chốn + động từ + bổ ngữ xu hướng/bổ ngữ kết quả + (trợ từ động thái) + cụm số lượng + người/vật.","examples":[{"cn":"后边走过去两个人。","pinyin":"Hòubian zǒu guòqù liǎng ge rén.","vn":""},{"cn":"前面开过来很多车。","pinyin":"Qiánmiàn kāi guòlái hěn duō chē.","vn":""},{"cn":"楼上下来了几个人。","pinyin":"Lóushàng xiàlái le jǐ ge rén.","vn":""}]},{"title":"紧缩复句\"……了……就……\" - Câu phức rút gọn \"……了……就……\"","explanation_vn":"Câu phức rút gọn \"……了……就……\" biểu thị hai hành động xảy ra kế tiếp ngay sau nhau. Nếu hành động thứ hai cũng đã hoàn thành thì cần thêm một \"了\" ở cuối câu. Cấu trúc cơ bản: Động từ1+了……就+Động từ2……","examples":[{"cn":"你听完了音乐会就来我家吃饭。","pinyin":"Nǐ tīngwán le yīnyuèhuì jiù lái wǒ jiā chīfàn.","vn":""},{"cn":"我吃了早饭就去学校了。","pinyin":"Wǒ chī le zǎofàn jiù qù xuéxiào le.","vn":""},{"cn":"昨天我们下了课就回家了。","pinyin":"Zuótiān wǒmen xià le kè jiù huíjiā le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"这个星期总是阴天，今天终于晴了。","pinyin":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le."},{"speaker":"李文","cn":"现在天气好得很！我们去爬山怎么样？","pinyin":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù pá shān zěnmeyàng?"},{"speaker":"白家月","cn":"好啊！又能锻炼身体，又能照好看的照片。","pinyin":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn."},{"speaker":"李文","cn":"那我带点儿水和吃的，咱们现在就去？","pinyin":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?"},{"speaker":"白家月","cn":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","pinyin":"Wǒ huíqù chuānshàng yùndòngxié, náshàng dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?"},{"speaker":"李文","cn":"好主意。给她打个电话吧。","pinyin":"Hǎo zhǔyi. Gěi tā dǎ ge diànhuà ba."}],"translation_vn":"Bạch Gia Nguyệt: Tuần này cứ toàn trời âm u, hôm nay cuối cùng cũng nắng rồi.\nLý Văn: Thời tiết hôm nay đẹp lắm! Chúng ta đi leo núi thế nào?\nBạch Gia Nguyệt: Được đấy! Vừa rèn luyện sức khỏe, vừa chụp được ảnh đẹp.\nLý Văn: Vậy mình mang ít nước và đồ ăn, chúng ta đi luôn bây giờ nhé?\nBạch Gia Nguyệt: Mình về mặc giày thể thao, lấy áo khoác. Có nên gọi chị Nhất Tuyết đi cùng không?\nLý Văn: Ý hay đấy. Gọi điện cho chị ấy đi.","audio_dialogue":"5-1.mp3","audio_vocab":"5-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"这些照片是谁给您照的？张张都非常好看。","pinyin":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāng zhāng dōu fēicháng hǎokàn."},{"speaker":"王一雪","cn":"一飞。她对拍照一直很感兴趣，经常给我照相。","pinyin":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng."},{"speaker":"白家月","cn":"我喜欢您大笑的这张，看起来很漂亮。","pinyin":"Wǒ xǐhuan nín dàxiào de zhè zhāng, kànqǐlai hěn piàoliang."},{"speaker":"王一雪","cn":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","pinyin":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng."},{"speaker":"白家月","cn":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","pinyin":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, pá shān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba."},{"speaker":"王一雪","cn":"好，我可以比较一下你们两个谁的水平高。","pinyin":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng ge shéi de shuǐpíng gāo."}],"translation_vn":"Bạch Gia Nguyệt: Mấy tấm ảnh này ai chụp cho chị vậy? Tấm nào cũng đẹp cả.\nVương Nhất Tuyết: Nhất Phi đấy. Nó luôn rất hứng thú với việc chụp ảnh, thường xuyên chụp cho chị.\nBạch Gia Nguyệt: Em thích tấm chị cười lớn này, trông rất đẹp.\nVương Nhất Tuyết: Chị thấy tấm này hơi xấu, lúc đó chị không biết nó đang chụp mình.\nBạch Gia Nguyệt: Ảnh như vậy mới đẹp chứ. Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị vài tấm nhé.\nVương Nhất Tuyết: Được, chị có thể so sánh xem ai trong hai đứa có trình độ cao hơn.","audio_dialogue":"5-3.mp3","audio_vocab":"5-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"家月，这里挺漂亮的，咱们在这里拍照吧。","pinyin":"Jiāyuè, zhèlǐ tǐng piàoliang de, zánmen zài zhèlǐ pāizhào ba."},{"speaker":"白家月","cn":"这边没有太阳，咱们去那边吧。","pinyin":"Zhè biān méiyǒu tàiyáng, zánmen qù nà biān ba."},{"speaker":"王一雪","cn":"好。你觉得我站在这些树中间怎么样？","pinyin":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?"},{"speaker":"白家月","cn":"挺好的。等一下，后边走过去两个人。","pinyin":"Tǐng hǎo de. Děng yíxià, hòubian zǒu guòqù liǎng ge rén."},{"speaker":"王一雪","cn":"我准备好了，你照的时候告诉我。","pinyin":"Wǒ zhǔnbèi hǎo le, nǐ zhào de shíhou gàosu wǒ."},{"speaker":"白家月","cn":"你不用看着我，想干什么都可以。","pinyin":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ."},{"speaker":"王一雪","cn":"树上飞来了几只鸟，我就看它们吧。","pinyin":"Shù shàng fēilái le jǐ zhī niǎo, wǒ jiù kàn tāmen ba."},{"speaker":"白家月","cn":"啊，手机没电了。","pinyin":"À, shǒujī méi diàn le."}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, chỗ này khá đẹp, chúng ta chụp ảnh ở đây đi.\nBạch Gia Nguyệt: Bên này không có nắng, chúng ta sang bên kia đi.\nVương Nhất Tuyết: Được. Em thấy chị đứng giữa mấy cây này thế nào?\nBạch Gia Nguyệt: Đẹp đấy. Đợi một chút, phía sau có hai người đi qua.\nVương Nhất Tuyết: Chị chuẩn bị xong rồi, lúc nào chụp thì nói chị nhé.\nBạch Gia Nguyệt: Chị không cần nhìn vào em, muốn làm gì cũng được.\nVương Nhất Tuyết: Trên cây có mấy con chim bay tới, chị ngắm chúng vậy.\nBạch Gia Nguyệt: A, điện thoại hết pin rồi.","audio_dialogue":"5-5.mp3","audio_vocab":"5-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。不知道你对中国的音乐有没有兴趣？我送你一张明天下午音乐会的门票。音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。你觉得怎么样？","pinyin":"Jiāyuè, wǒ shōudào le nǐ de nà fēng yóujiàn, yě kàndào le nǐ gěi wǒ zhào de zhàopiàn, zhāng zhāng dōu hěn piàoliang. Wǒ yǐjīng gàosu le Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā. Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù? Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào. Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwán le yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguó cài. Nǐ juéde zěnmeyàng?"}],"translation_vn":"Gia Nguyệt ơi, chị đã nhận được bức thư điện tử đó của em rồi, cũng xem những tấm ảnh em chụp cho chị, tấm nào cũng đẹp. Chị đã nói cho Nhất Phi biết rồi, trình độ chụp ảnh của em cao hơn nó đấy, nó buồn lắm, haha. Không biết em có hứng thú với âm nhạc Trung Quốc không? Chị tặng em một vé buổi hòa nhạc chiều mai. Buổi hòa nhạc kết thúc hơn bảy giờ, em nghe xong hòa nhạc thì đến nhà chị ăn cơm, nếm thử món Trung Quốc chị nấu nhé. Em thấy thế nào?","audio_dialogue":"5-7.mp3","audio_vocab":"5-8.mp3"}]},{"id":6,"title_cn":"高铁上还可以点外卖","title_pinyin":"Gāotiě shàng hái kěyǐ diǎn wàimài","title_vn":"Trên tàu cao tốc còn có thể gọi đồ ăn mang tới","goals":["Có thể nghe hiểu và giới thiệu về đặc điểm các phương tiện giao thông cũng như trải nghiệm đi lại.","Có thể nghe hiểu và sử dụng \"如果\" để diễn đạt tình huống giả thiết và kết quả.","Nắm được cụm từ \"越来越\", có thể miêu tả xu hướng biến đổi của sự vật.","Tìm hiểu phương thức giao thông hiện đại của Trung Quốc — tàu cao tốc."],"vocab":[{"hanzi":"该","pinyin":"gāi","pos":"đtnn.","vn":"nên, phải"},{"hanzi":"打算","pinyin":"dǎsuàn","pos":"dgt./dt.","vn":"dự định, kế hoạch"},{"hanzi":"高铁","pinyin":"gāotiě","pos":"dt.","vn":"tàu cao tốc"},{"hanzi":"行","pinyin":"xíng","pos":"dgt./tt.","vn":"được, ổn"},{"hanzi":"路口","pinyin":"lùkǒu","pos":"dt.","vn":"ngã tư, giao lộ"},{"hanzi":"小心","pinyin":"xiǎoxīn","pos":"dgt./tt.","vn":"cẩn thận"},{"hanzi":"迟到","pinyin":"chídào","pos":"dgt.","vn":"đến muộn"},{"hanzi":"红绿灯","pinyin":"hóng-lǜdēng","pos":"dt.","vn":"đèn giao thông"},{"hanzi":"后来","pinyin":"hòulái","pos":"dt.","vn":"sau đó"},{"hanzi":"急","pinyin":"jí","pos":"tt./dgt.","vn":"gấp, nóng vội, sốt ruột"},{"hanzi":"如果","pinyin":"rúguǒ","pos":"liên.","vn":"nếu"},{"hanzi":"以前","pinyin":"yǐqián","pos":"dt.","vn":"trước đây"},{"hanzi":"耳机","pinyin":"ěrjī","pos":"dt.","vn":"tai nghe"},{"hanzi":"充电宝","pinyin":"chōngdiànbǎo","pos":"dt.","vn":"sạc dự phòng"},{"hanzi":"常用","pinyin":"chángyòng","pos":"tt.","vn":"thường dùng"},{"hanzi":"越","pinyin":"yuè","pos":"phó.","vn":"càng"},{"hanzi":"分开","pinyin":"fēnkāi","pos":"dgt.","vn":"tách ra, chia tay"},{"hanzi":"检查","pinyin":"jiǎnchá","pos":"dgt.","vn":"kiểm tra"},{"hanzi":"刷","pinyin":"shuā","pos":"dgt.","vn":"quẹt (thẻ)"},{"hanzi":"检票","pinyin":"jiǎnpiào","pos":"dgt.","vn":"soát vé"},{"hanzi":"电梯","pinyin":"diàntī","pos":"dt.","vn":"thang máy, thang cuốn"},{"hanzi":"放假","pinyin":"fàngjià","pos":"dgt.","vn":"nghỉ (lễ, học)"},{"hanzi":"沙发","pinyin":"shāfā","pos":"dt.","vn":"ghế sofa"},{"hanzi":"安静","pinyin":"ānjìng","pos":"tt.","vn":"yên tĩnh"},{"hanzi":"选择","pinyin":"xuǎnzé","pos":"dgt.","vn":"lựa chọn"},{"hanzi":"必须","pinyin":"bìxū","pos":"phó.","vn":"phải, bắt buộc"},{"hanzi":"北京南站","pinyin":"Běijīng Nán Zhàn","pos":"danh từ riêng","vn":"Ga Nam Bắc Kinh"}],"grammar":[{"title":"固定格式\"该……了\" - Cụm cố định \"该……了\"","explanation_vn":"Cụm cố định \"该……了\" biểu thị đã đến lúc cần phải làm việc gì đó, thường dùng trong khẩu ngữ.","examples":[{"cn":"咱们该买去上海的票了。","pinyin":"Zánmen gāi mǎi qù Shànghǎi de piào le.","vn":""},{"cn":"八点了，该上课了。","pinyin":"Bā diǎn le, gāi shàngkè le.","vn":""},{"cn":"已经很晚了，我该睡觉了。","pinyin":"Yǐjīng hěn wǎn le, wǒ gāi shuìjiào le.","vn":""}]},{"title":"假设复句\"如果……，就……\" - Câu phức giả thiết \"如果……，就……\"","explanation_vn":"Trong câu phức giả thiết \"如果……，就……\", mệnh đề theo sau \"如果\" là một giả thiết, mệnh đề theo sau \"就\" là kết quả xảy ra trong tình huống giả thiết đó. Lưu ý, chủ ngữ của mệnh đề thứ hai đặt trước \"就\".","examples":[{"cn":"如果没走错，二十分钟以前就到了。","pinyin":"Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","vn":""},{"cn":"如果你需要帮忙，就给我打电话。","pinyin":"Rúguǒ nǐ xūyào bāngmáng, jiù gěi wǒ dǎ diànhuà.","vn":""},{"cn":"如果有时间，我就去上海玩几天。","pinyin":"Rúguǒ yǒu shíjiān, wǒ jiù qù Shànghǎi wán jǐ tiān.","vn":""}]},{"title":"固定短语\"越来越\" - Cụm cố định \"越来越\"","explanation_vn":"Cụm cố định \"越来越\" phía sau theo sau một tính từ hoặc động từ tâm lý, biểu thị theo thời gian trôi qua, mức độ có sự biến đổi. Trước tính từ hoặc động từ tâm lý không được thêm phó từ chỉ mức độ.","examples":[{"cn":"前面的人越来越多。","pinyin":"Qiánmiàn de rén yuè lái yuè duō.","vn":""},{"cn":"我越来越喜欢这里的生活了。","pinyin":"Wǒ yuè lái yuè xǐhuan zhèlǐ de shēnghuó le.","vn":""},{"cn":"她越来越高，也越来越漂亮了。","pinyin":"Tā yuè lái yuè gāo, yě yuè lái yuè piàoliang le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，咱们该买去上海的票了。你打算怎么去上海？","pinyin":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?"},{"speaker":"白家月","cn":"我还没坐过高铁，咱们坐高铁去，怎么样？","pinyin":"Wǒ hái méi zuòguò gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?"},{"speaker":"李文","cn":"没问题，从北京到上海的高铁很多，非常方便。","pinyin":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn."},{"speaker":"白家月","cn":"行！怎么买高铁票？","pinyin":"Xíng! Zěnme mǎi gāotiě piào?"},{"speaker":"李文","cn":"用手机App就能买。给我你的护照，我帮你买。","pinyin":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi."},{"speaker":"白家月","cn":"早就听说过高铁，终于可以坐上了。","pinyin":"Zǎo jiù tīngshuōguò gāotiě, zhōngyú kěyǐ zuòshàng le."},{"speaker":"李文","cn":"高铁又快又舒服，你一定会喜欢的。","pinyin":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de."}],"translation_vn":"Lý Văn: Gia Nguyệt à, chúng ta nên mua vé đi Thượng Hải rồi. Cậu định đi Thượng Hải bằng cách nào?\nBạch Gia Nguyệt: Mình chưa đi tàu cao tốc bao giờ, chúng ta đi tàu cao tốc nhé?\nLý Văn: Không vấn đề gì, tàu cao tốc từ Bắc Kinh đến Thượng Hải rất nhiều, rất tiện lợi.\nBạch Gia Nguyệt: Được! Mua vé tàu cao tốc thế nào?\nLý Văn: Dùng App trên điện thoại là mua được. Đưa hộ chiếu cho mình, mình mua giúp cho.\nBạch Gia Nguyệt: Sớm đã nghe nói về tàu cao tốc rồi, cuối cùng cũng được đi rồi.\nLý Văn: Tàu cao tốc vừa nhanh vừa thoải mái, cậu chắc chắn sẽ thích đấy.","audio_dialogue":"6-1.mp3","audio_vocab":"6-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘明","cn":"过了前面的路口就到高铁站了。","pinyin":"Guò le qiánmiàn de lùkǒu jiù dào gāotiězhàn le."},{"speaker":"白家月","cn":"我看见了。马上就到了，这条路车很多，您小心点儿。","pinyin":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr."},{"speaker":"刘明","cn":"好，你们还有一个小时，应该不会迟到的。","pinyin":"Hǎo, nǐmen hái yǒu yí ge xiǎoshí, yīnggāi bú huì chídào de."},{"speaker":"白家月","cn":"我发现这条路车多，红绿灯也多。","pinyin":"Wǒ fāxiàn zhè tiáo lù chē duō, hóng-lǜdēng yě duō."},{"speaker":"刘明","cn":"是啊，这条路我走过一次，后来再也不走了。","pinyin":"Shì a, zhè tiáo lù wǒ zǒuguò yí cì, hòulái zài yě bù zǒu le."},{"speaker":"白家月","cn":"那您今天为什么走了这条路？","pinyin":"Nà nín jīntiān wèishénme zǒu le zhè tiáo lù?"},{"speaker":"刘明","cn":"我一急就走错了。如果没走错，二十分钟以前就到了。","pinyin":"Wǒ yì jí jiù zǒucuò le. Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le."}],"translation_vn":"Lưu Minh: Qua ngã tư phía trước là đến ga tàu cao tốc rồi.\nBạch Gia Nguyệt: Em thấy rồi. Sắp đến nơi rồi, con đường này nhiều xe lắm, anh cẩn thận chút nhé.\nLưu Minh: Được, các em vẫn còn một tiếng nữa, chắc sẽ không muộn đâu.\nBạch Gia Nguyệt: Em thấy con đường này xe nhiều, đèn giao thông cũng nhiều.\nLưu Minh: Đúng vậy, con đường này anh từng đi một lần, sau đó không bao giờ đi nữa.\nBạch Gia Nguyệt: Vậy sao hôm nay anh lại đi đường này?\nLưu Minh: Anh vội quá nên đi nhầm đường. Nếu không đi nhầm thì hai mươi phút trước đã đến rồi.","audio_dialogue":"6-3.mp3","audio_vocab":"6-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"李文，我的耳机没电了，你有充电宝吗？","pinyin":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?"},{"speaker":"李文","cn":"有，这些常用的东西我都放在包里了，我给你拿。","pinyin":"Yǒu, zhèxiē chángyòng de dōngxi wǒ dōu fàng zài bāo lǐ le, wǒ gěi nǐ ná."},{"speaker":"白家月","cn":"前面的人越来越多。","pinyin":"Qiánmiàn de rén yuè lái yuè duō."},{"speaker":"李文","cn":"对，马上就进高铁站了。咱们一起走，别分开。","pinyin":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi."},{"speaker":"白家月","cn":"好，你检查一下，高铁票都拿好了吗？","pinyin":"Hǎo, nǐ jiǎnchá yíxià, gāotiě piào dōu ná hǎo le ma?"},{"speaker":"李文","cn":"不用拿票，刷护照就能检票进站。","pinyin":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn."},{"speaker":"白家月","cn":"去哪里检票？","pinyin":"Qù nǎlǐ jiǎnpiào?"},{"speaker":"李文","cn":"检票口在二层，我们一会儿坐电梯上去。","pinyin":"Jiǎnpiàokǒu zài èr céng, wǒmen yíhuìr zuò diàntī shàngqù."}],"translation_vn":"Bạch Gia Nguyệt: Lý Văn ơi, tai nghe của mình hết pin rồi, cậu có sạc dự phòng không?\nLý Văn: Có, mấy món đồ hay dùng này mình đều để trong túi rồi, để mình lấy cho cậu.\nBạch Gia Nguyệt: Người phía trước ngày càng đông.\nLý Văn: Đúng vậy, sắp vào ga cao tốc rồi. Chúng ta đi cùng nhau, đừng tách ra.\nBạch Gia Nguyệt: Được, cậu kiểm tra xem, vé tàu cao tốc đã cầm sẵn chưa?\nLý Văn: Không cần cầm vé, quẹt hộ chiếu là soát vé vào ga được rồi.\nBạch Gia Nguyệt: Soát vé ở đâu vậy?\nLý Văn: Cửa soát vé ở tầng hai, lát nữa chúng ta đi thang máy lên.","audio_dialogue":"6-5.mp3","audio_vocab":"6-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这次放假，我去了北京，还去了上海。我是从北京南站坐高铁去的上海。我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。坐累了就站一会儿，饿了就点外卖。对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。现在喜欢坐高铁的人越来越多。我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","pinyin":"Zhè cì fàngjià, wǒ qù le Běijīng, hái qù le Shànghǎi. Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi. Wǒ juéde zuò zài gāotiě shàng gēn zuò zài jiā lǐ de shāfā shàng yíyàng, yòu ānjìng yòu shūfu. Zuòlèi le jiù zhàn yíhuìr, è le jiù diǎn wàimài. Duì, nǐ méi tīngcuò, gāotiě shàng kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xià chē, fúwùyuán jiù huì gěi nǐ ná guòlái. Xiànzài xǐhuan zuò gāotiě de rén yuè lái yuè duō. Wǒ bà mā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě."}],"translation_vn":"Kỳ nghỉ lần này, mình đã đi Bắc Kinh, rồi còn đi Thượng Hải nữa. Mình đi tàu cao tốc từ Ga Nam Bắc Kinh đến Thượng Hải. Mình thấy ngồi trên tàu cao tốc cũng giống như ngồi trên ghế sofa ở nhà vậy, vừa yên tĩnh vừa thoải mái. Ngồi mỏi thì đứng dậy một lát, đói thì gọi đồ ăn mang tới. Đúng vậy, bạn không nghe nhầm đâu, trên tàu cao tốc có thể đặt đồ ăn, chỉ cần chọn đúng ga và món muốn ăn, đến ga không cần xuống tàu, nhân viên sẽ mang đến tận nơi cho bạn. Hiện nay người thích đi tàu cao tốc ngày càng nhiều. Khi bố mẹ mình sang Trung Quốc du lịch, nhất định phải cho họ đi tàu cao tốc một lần.","audio_dialogue":"6-7.mp3","audio_vocab":"6-8.mp3"}]},{"id":7,"title_cn":"那条裙子比短裤更好看","title_pinyin":"Nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn","title_vn":"Chiếc váy đó đẹp hơn cái quần short","goals":["Có thể nghe hiểu và giới thiệu về trải nghiệm mua sắm.","Có thể nghe hiểu và đánh giá đặc điểm của sản phẩm.","Nắm vững cách dùng câu so sánh (10), có thể so sánh các sản phẩm.","Hiểu được phương thức mua sắm của người Trung Quốc."],"vocab":[{"hanzi":"辆","pinyin":"liàng","pos":"lượng.","vn":"lượng từ dùng cho xe cộ"},{"hanzi":"自行车","pinyin":"zìxíngchē","pos":"dt.","vn":"xe đạp"},{"hanzi":"旧","pinyin":"jiù","pos":"tt.","vn":"cũ"},{"hanzi":"矮","pinyin":"ǎi","pos":"tt.","vn":"thấp (chiều cao)"},{"hanzi":"试","pinyin":"shì","pos":"dgt.","vn":"thử"},{"hanzi":"黄色","pinyin":"huángsè","pos":"dt.","vn":"màu vàng"},{"hanzi":"短裤","pinyin":"duǎnkù","pos":"dt.","vn":"quần short"},{"hanzi":"大小","pinyin":"dàxiǎo","pos":"dt.","vn":"kích cỡ, kích thước"},{"hanzi":"合适","pinyin":"héshì","pos":"tt.","vn":"phù hợp, vừa vặn"},{"hanzi":"裙子","pinyin":"qúnzi","pos":"dt.","vn":"váy"},{"hanzi":"更","pinyin":"gèng","pos":"phó.","vn":"hơn, càng"},{"hanzi":"决定","pinyin":"juédìng","pos":"dgt.","vn":"quyết định"},{"hanzi":"西瓜","pinyin":"xīguā","pos":"dt.","vn":"dưa hấu"},{"hanzi":"新鲜","pinyin":"xīnxiān","pos":"tt.","vn":"tươi"},{"hanzi":"甜","pinyin":"tián","pos":"tt.","vn":"ngọt"},{"hanzi":"公斤","pinyin":"gōngjīn","pos":"lượng.","vn":"kilôgam"},{"hanzi":"冰","pinyin":"bīng","pos":"dgt.","vn":"ướp lạnh; nước đá"},{"hanzi":"极","pinyin":"jí","pos":"phó.","vn":"cực kỳ"},{"hanzi":"斤","pinyin":"jīn","pos":"lượng.","vn":"cân (đơn vị đo lường của Trung Quốc, bằng 0,5kg)"},{"hanzi":"香蕉","pinyin":"xiāngjiāo","pos":"dt.","vn":"chuối"},{"hanzi":"一共","pinyin":"yígòng","pos":"phó.","vn":"tổng cộng"},{"hanzi":"毛","pinyin":"máo","pos":"lượng.","vn":"hào (đơn vị tiền tệ)"},{"hanzi":"结婚","pinyin":"jiéhūn","pos":"dgt.","vn":"kết hôn"},{"hanzi":"不但","pinyin":"búdàn","pos":"liên.","vn":"không những"},{"hanzi":"而且","pinyin":"érqiě","pos":"liên.","vn":"mà còn"},{"hanzi":"声","pinyin":"shēng","pos":"lượng.","vn":"tiếng (đơn vị chỉ âm thanh)"},{"hanzi":"开机","pinyin":"kāijī","pos":"dgt.","vn":"khởi động, bật máy"}],"grammar":[{"title":"连动句（2）- Câu liên động (2)","explanation_vn":"Trợ từ động thái \"着\" dùng sau động từ thứ nhất trong câu liên động, biểu thị trạng thái hoặc cách thức khi thực hiện động tác thứ hai. Cấu trúc cơ bản: Động từ 1 + 着 + (Tân ngữ 1) + Động từ 2 + (Tân ngữ 2).","examples":[{"cn":"咱们可以走着去。","pinyin":"Zánmen kěyǐ zǒuzhe qù.","vn":""},{"cn":"弟弟吃着苹果写作业。","pinyin":"Dìdi chīzhe píngguǒ xiě zuòyè.","vn":""},{"cn":"他们坐着看电视。","pinyin":"Tāmen zuòzhe kàn diànshì.","vn":""}]},{"title":"比较句（10）- Câu so sánh (10)","explanation_vn":"Cấu trúc \"A不比B+形容词\" có nghĩa là A và B gần như tương đương nhau, không chênh lệch nhiều. Cấu trúc này thường dùng để nhấn mạnh tình trạng của hai đối tượng là gần giống nhau, hoặc dùng để phản bác lại ý kiến của người khác.","examples":[{"cn":"裙子不比短裤贵多少。","pinyin":"Qúnzi bù bǐ duǎnkù guì duōshao.","vn":""},{"cn":"他的中文不比你好。","pinyin":"Tā de Zhōngwén bù bǐ nǐ hǎo.","vn":""},{"cn":"他跑得不比我快多少。","pinyin":"Tā pǎo de bù bǐ wǒ kuài duōshao.","vn":""}]},{"title":"程度补语（3）- Bổ ngữ mức độ (3)","explanation_vn":"Bổ ngữ mức độ \"极了\" dùng sau tính từ hoặc động từ tâm lý, biểu thị tính chất, trạng thái của người/vật, hoặc cảm xúc tâm lý của người đạt đến mức độ rất cao.","examples":[{"cn":"这块冰西瓜甜极了。","pinyin":"Zhè kuài bīng xīguā tián jí le.","vn":""},{"cn":"今年夏天热极了。","pinyin":"Jīnnián xiàtiān rè jí le.","vn":""},{"cn":"这本书我喜欢极了。","pinyin":"Zhè běn shū wǒ xǐhuan jí le.","vn":""}]},{"title":"递进复句\"不但……，而且……\" - Câu phức tiến triển \"不但……，而且……\"","explanation_vn":"Câu phức tiến triển \"不但……，而且……\" nối hai vế câu, biểu thị quan hệ tăng tiến. Nếu chủ ngữ của hai vế giống nhau thì \"不但\" đặt sau chủ ngữ thứ nhất; nếu chủ ngữ của hai vế khác nhau thì \"不但\" đặt trước chủ ngữ thứ nhất.","examples":[{"cn":"现在的电视不但便宜，而且用着非常方便。","pinyin":"Xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn.","vn":""},{"cn":"家月不但喜欢唱歌，而且唱得很好听。","pinyin":"Jiāyuè búdàn xǐhuan chànggē, érqiě chàng de hěn hǎotīng.","vn":""},{"cn":"不但家月会说汉语，而且天中也会说汉语。","pinyin":"Búdàn Jiāyuè huì shuō Hànyǔ, érqiě Tiānzhōng yě huì shuō Hànyǔ.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","pinyin":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlai yǒudiǎnr jiù le."},{"speaker":"刘明","cn":"是啊，她现在长高了，这辆车已经太矮了。","pinyin":"Shì a, tā xiànzài zhǎnggāo le, zhè liàng chē yǐjīng tài ǎi le."},{"speaker":"王一雪","cn":"商场里开了一家自行车店，咱们给她买辆新的吧。","pinyin":"Shāngchǎng lǐ kāile yì jiā zìxíngchē diàn, zánmen gěi tā mǎi liàng xīn de ba."},{"speaker":"刘明","cn":"好，咱们带小雪一起去，让她试一下。","pinyin":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià."},{"speaker":"王一雪","cn":"那今天就去吧！我也想再看看衣服。咱们怎么去？","pinyin":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?"},{"speaker":"刘明","cn":"商场不远，咱们可以走着去。","pinyin":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù."}],"translation_vn":"Vương Nhất Tuyết: Chiếc xe đạp này là mua lúc Tiểu Tuyết tám tuổi, trông có vẻ hơi cũ rồi.\nLưu Minh: Đúng vậy, bây giờ con bé cao lên rồi, chiếc xe này đã quá thấp rồi.\nVương Nhất Tuyết: Trong trung tâm thương mại có mở một cửa hàng xe đạp, chúng ta mua cho con bé một chiếc mới đi.\nLưu Minh: Được, chúng ta đưa Tiểu Tuyết đi cùng, để con bé thử xem sao.\nVương Nhất Tuyết: Vậy hôm nay đi luôn đi! Em cũng muốn xem thêm quần áo nữa. Chúng ta đi bằng gì?\nLưu Minh: Trung tâm thương mại không xa, chúng ta có thể đi bộ.","audio_dialogue":"7-1.mp3","audio_vocab":"7-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"你看我穿这条黄色的短裤好看吗？","pinyin":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?"},{"speaker":"刘明","cn":"大小合适，但我觉得那条裙子比短裤更好看。","pinyin":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn."},{"speaker":"王一雪","cn":"裙子比短裤贵一点儿。","pinyin":"Qúnzi bǐ duǎnkù guì yìdiǎnr."},{"speaker":"刘明","cn":"贵多少？","pinyin":"Guì duōshao?"},{"speaker":"王一雪","cn":"裙子480，短裤400。","pinyin":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi."},{"speaker":"刘明","cn":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","pinyin":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn."},{"speaker":"王一雪","cn":"我多看看再决定。你看，那边有买二送一！","pinyin":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbiān yǒu mǎi èr sòng yī!"}],"translation_vn":"Vương Nhất Tuyết: Anh xem em mặc cái quần short màu vàng này có đẹp không?\nLưu Minh: Kích cỡ vừa vặn, nhưng anh thấy chiếc váy kia đẹp hơn quần short.\nVương Nhất Tuyết: Váy đắt hơn quần short một chút.\nLưu Minh: Đắt hơn bao nhiêu?\nVương Nhất Tuyết: Váy 480, quần short 400.\nLưu Minh: Váy không đắt hơn quần short bao nhiêu đâu, cứ mua váy đi, em mặc váy đẹp hơn.\nVương Nhất Tuyết: Để em xem thêm rồi quyết định. Anh xem kìa, đằng kia có chương trình mua hai tặng một!","audio_dialogue":"7-3.mp3","audio_vocab":"7-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"店员","cn":"西瓜又大又新鲜，不甜不要钱！","pinyin":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!"},{"speaker":"王一雪","cn":"西瓜看起来不错，怎么卖？","pinyin":"Xīguā kàn qǐlai búcuò, zěnme mài?"},{"speaker":"店员","cn":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","pinyin":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jí le!"},{"speaker":"王一雪","cn":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","pinyin":"Shì tǐng tián de! Bāng wǒ xuǎn ge dà diǎnr de, zài lái liǎng jīn xiāngjiāo."},{"speaker":"店员","cn":"一共五十八块五毛。","pinyin":"Yígòng wǔshíbā kuài wǔ máo."},{"speaker":"王一雪","cn":"我买了这么多，便宜点儿吧。","pinyin":"Wǒ mǎile zhème duō, piányi diǎnr ba."},{"speaker":"店员","cn":"您给我五十五吧，不能再便宜了。","pinyin":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le."}],"translation_vn":"Nhân viên bán hàng: Dưa hấu vừa to vừa tươi, không ngọt không lấy tiền!\nVương Nhất Tuyết: Dưa hấu trông ngon đấy, bán thế nào?\nNhân viên bán hàng: Năm đồng một ký. Nào, chị nếm thử miếng dưa hấu ướp lạnh này xem, ngọt lắm đấy!\nVương Nhất Tuyết: Đúng là khá ngọt! Giúp tôi chọn một quả to hơn một chút, với lại lấy thêm hai cân chuối.\nNhân viên bán hàng: Tổng cộng năm mươi tám đồng năm hào.\nVương Nhất Tuyết: Tôi mua nhiều như vậy, bớt cho tôi một chút đi.\nNhân viên bán hàng: Chị đưa tôi năm mươi lăm đồng thôi, không thể bớt thêm được nữa.","audio_dialogue":"7-5.mp3","audio_vocab":"7-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这几天我们在新家坐着看电视的时候，又发现了新问题。","pinyin":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiànle xīn wèntí."},{"speaker":"","cn":"房子大了，电视看起来就有点儿小。","pinyin":"Fángzi dà le, diànshì kàn qǐlai jiù yǒudiǎnr xiǎo."},{"speaker":"","cn":"这个电视是我们结婚时买的，是时候换个新电视了。","pinyin":"Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn ge xīn diànshì le."},{"speaker":"","cn":"今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便。","pinyin":"Jīntiān wǒ yìzhí zài wǎngshàng xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn."},{"speaker":"","cn":"有的电视叫它一声就能开机。","pinyin":"Yǒude diànshì jiào tā yì shēng jiù néng kāijī."},{"speaker":"","cn":"我看了好几个，都很满意，晚上让一雪来决定吧。","pinyin":"Wǒ kànle hǎojǐ ge, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba."}],"translation_vn":"Mấy ngày nay, khi chúng tôi ngồi xem ti vi trong nhà mới, lại phát hiện ra vấn đề mới. Nhà rộng hơn nên chiếc ti vi trông có vẻ hơi nhỏ. Chiếc ti vi này là mua từ lúc chúng tôi kết hôn, đã đến lúc đổi một cái ti vi mới rồi. Hôm nay tôi cứ lên mạng chọn ti vi mãi, không ngờ ti vi bây giờ không những rẻ mà dùng còn rất tiện lợi. Có loại ti vi chỉ cần gọi một tiếng là có thể bật lên được. Tôi đã xem mấy cái, đều thấy rất ưng ý, tối nay để Nhất Tuyết quyết định vậy.","audio_dialogue":"7-7.mp3","audio_vocab":"7-8.mp3"}]},{"id":8,"title_cn":"今天我出院了","title_pinyin":"Jīntiān wǒ chūyuàn le","title_vn":"Hôm nay tôi đã xuất viện","goals":["Có thể nghe hiểu và miêu tả trải nghiệm khám bệnh cùng cách dùng thuốc.","Có thể nghe hiểu và trao đổi về tình trạng sức khỏe và thói quen sống lành mạnh.","Nắm vững cách dùng bổ ngữ thời lượng (2), có thể diễn đạt khoảng thời gian kéo dài từ khi động tác kết thúc đến hiện tại."],"vocab":[{"hanzi":"最近","pinyin":"zuìjìn","pos":"dt.","vn":"gần đây, dạo này"},{"hanzi":"常","pinyin":"cháng","pos":"phó.","vn":"thường, hay"},{"hanzi":"体育馆","pinyin":"tǐyùguǎn","pos":"dt.","vn":"nhà thi đấu, phòng tập thể thao"},{"hanzi":"习惯","pinyin":"xíguàn","pos":"dt./dgt.","vn":"thói quen; quen với"},{"hanzi":"胖","pinyin":"pàng","pos":"tt.","vn":"béo, mập"},{"hanzi":"健康","pinyin":"jiànkāng","pos":"tt.","vn":"khỏe mạnh"},{"hanzi":"以后","pinyin":"yǐhòu","pos":"dt.","vn":"sau đó, về sau"},{"hanzi":"羽毛球","pinyin":"yǔmáoqiú","pos":"dt.","vn":"cầu lông"},{"hanzi":"耳朵","pinyin":"ěrduo","pos":"dt.","vn":"tai"},{"hanzi":"感冒","pinyin":"gǎnmào","pos":"dgt./dt.","vn":"bị cảm; bệnh cảm cúm"},{"hanzi":"发烧","pinyin":"fāshāo","pos":"dgt.","vn":"sốt"},{"hanzi":"低","pinyin":"dī","pos":"tt.","vn":"thấp"},{"hanzi":"关心","pinyin":"guānxīn","pos":"dgt.","vn":"quan tâm"},{"hanzi":"注意","pinyin":"zhùyì","pos":"dgt.","vn":"chú ý, để ý"},{"hanzi":"突然","pinyin":"tūrán","pos":"tt.","vn":"đột ngột, bất ngờ"},{"hanzi":"住院","pinyin":"zhùyuàn","pos":"dgt.","vn":"nhập viện"},{"hanzi":"担心","pinyin":"dānxīn","pos":"dgt.","vn":"lo lắng"},{"hanzi":"腿","pinyin":"tuǐ","pos":"dt.","vn":"chân (đùi)"},{"hanzi":"病人","pinyin":"bìngrén","pos":"dt.","vn":"bệnh nhân"},{"hanzi":"差不多","pinyin":"chàbuduō","pos":"phó./tt.","vn":"gần như, xấp xỉ"},{"hanzi":"得","pinyin":"děi","pos":"đtnn.","vn":"phải, cần"},{"hanzi":"开心","pinyin":"kāixīn","pos":"tt.","vn":"vui vẻ"},{"hanzi":"出院","pinyin":"chūyuàn","pos":"dgt.","vn":"xuất viện"},{"hanzi":"开","pinyin":"kāi","pos":"dgt.","vn":"kê (đơn thuốc)"},{"hanzi":"种","pinyin":"zhǒng","pos":"lượng.","vn":"loại"},{"hanzi":"方法","pinyin":"fāngfǎ","pos":"dt.","vn":"phương pháp, cách"},{"hanzi":"其他","pinyin":"qítā","pos":"đt.","vn":"khác, cái khác"},{"hanzi":"心里","pinyin":"xīnlǐ","pos":"dt.","vn":"trong lòng, trong tâm trí"}],"grammar":[{"title":"趋向补语的引申用法（1）\"下去\" - Cách dùng mở rộng của bổ ngữ xu hướng (1)","explanation_vn":"Bổ ngữ xu hướng \"下去\" đặt sau động từ hoặc tính từ, biểu thị một động tác hoặc trạng thái đã bắt đầu sẽ tiếp tục diễn ra.","examples":[{"cn":"我今年胖了十多斤，不能再胖下去了。","pinyin":"Wǒ jīnnián pàng le shí duō jīn, bù néng zài pàng xiàqù le.","vn":""},{"cn":"她读完了第一个问题，后面的你读下去。","pinyin":"Tā dú wán le dì yī ge wèntí, hòumiàn de nǐ dú xiàqù.","vn":""},{"cn":"这几天太热了，如果再热下去就不能出门了。","pinyin":"Zhè jǐ tiān tài rè le, rúguǒ zài rè xiàqù jiù bù néng chūmén le.","vn":""}]},{"title":"离合词（2）- Từ ly hợp (2)","explanation_vn":"Từ ly hợp thường không thể trực tiếp mang tân ngữ. Trong câu dùng từ ly hợp, nếu có bổ ngữ thì bổ ngữ thường được đặt ở giữa hai thành phần của từ ly hợp.","examples":[{"cn":"昨天游完泳以后，我的耳朵一直有点儿疼。","pinyin":"Zuótiān yóu wán yǒng yǐhòu, wǒ de ěrduo yìzhí yǒudiǎnr téng.","vn":""},{"cn":"今年夏天只下了两次雨。","pinyin":"Jīnnián xiàtiān zhǐ xià le liǎng cì yǔ.","vn":""},{"cn":"小张下个月跟他女朋友结婚。","pinyin":"Xiǎo Zhāng xià ge yuè gēn tā nǚpéngyou jiéhūn.","vn":""}]},{"title":"时量补语（2）- Bổ ngữ thời lượng (2)","explanation_vn":"Bổ ngữ thời lượng đặt sau động từ, biểu thị độ dài thời gian mà động tác hoặc trạng thái kéo dài. Có một số động từ không thể tiếp diễn liên tục, khi đó bổ ngữ thời lượng đứng sau động từ biểu thị khoảng thời gian đã trôi qua kể từ khi động tác kết thúc đến lúc nói.","examples":[{"cn":"我上次来医院已经过去差不多两年了。","pinyin":"Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","vn":""},{"cn":"她回家两个月了。","pinyin":"Tā huí jiā liǎng ge yuè le.","vn":""},{"cn":"开学已经三个多星期了。","pinyin":"Kāixué yǐjīng sān ge duō xīngqī le.","vn":""}]},{"title":"固定格式\"……以前/以后/前/后\" - Cấu trúc cố định \"...以前/以后/前/后\"","explanation_vn":"\"Thời gian/sự kiện + 以前/前\" biểu thị thời điểm trước một thời gian hoặc sự kiện nào đó; \"thời gian/sự kiện + 以后/后\" biểu thị thời điểm sau một thời gian hoặc sự kiện nào đó.","examples":[{"cn":"这种药需要每天睡前吃一次。","pinyin":"Zhè zhǒng yào xūyào měitiān shuì qián chī yí cì.","vn":""},{"cn":"我们决定下班后一起去看个电影。","pinyin":"Wǒmen juédìng xiàbān hòu yìqǐ qù kàn ge diànyǐng.","vn":""},{"cn":"考完试以后，咱们一起去旅游吧。","pinyin":"Kǎo wán shì yǐhòu, zánmen yìqǐ qù lǚyóu ba.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"天中，最近常看见你来体育馆。","pinyin":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn."},{"speaker":"陈天中","cn":"我每天下午都来跑一个小时步。","pinyin":"Wǒ měitiān xiàwǔ dōu lái pǎo yí ge xiǎoshí bù."},{"speaker":"李文","cn":"你的运动习惯真不错。","pinyin":"Nǐ de yùndòng xíguàn zhēn búcuò."},{"speaker":"陈天中","cn":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","pinyin":"Yīnwèi wǒ jīnnián pàng le shí duō jīn, bù néng zài pàng xiàqù le, yǒudiǎnr bú jiànkāng."},{"speaker":"李文","cn":"我下课以后常去打羽毛球，你也来玩吧。","pinyin":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba."},{"speaker":"陈天中","cn":"我知道，但是你们的水平太高了，我打得不怎么样。","pinyin":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng."},{"speaker":"李文","cn":"没关系，我可以教你。","pinyin":"Méi guānxi, wǒ kěyǐ jiāo nǐ."}],"translation_vn":"Lý Văn: Thiên Trung, dạo này mình thường thấy cậu đến nhà thi đấu.\nTrần Thiên Trung: Mình ngày nào buổi chiều cũng đến chạy bộ một tiếng.\nLý Văn: Thói quen vận động của cậu thật tốt đấy.\nTrần Thiên Trung: Vì năm nay mình béo lên hơn chục cân, không thể béo thêm nữa, hơi không khỏe mạnh.\nLý Văn: Sau giờ học mình thường đi đánh cầu lông, cậu cũng đến chơi nhé.\nTrần Thiên Trung: Mình biết, nhưng trình độ của các cậu cao quá, mình đánh không được tốt lắm.\nLý Văn: Không sao, mình có thể dạy cậu.","audio_dialogue":"8-1.mp3","audio_vocab":"8-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"你怎么了？看上去有点儿不舒服。","pinyin":"Nǐ zěnme le? Kàn shàngqù yǒudiǎnr bù shūfu."},{"speaker":"陈天中","cn":"昨天游完泳以后，耳朵一直有点儿疼。","pinyin":"Zuótiān yóu wán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng."},{"speaker":"安妮","cn":"是不是感冒了？发烧吗？","pinyin":"Shì bu shì gǎnmào le? Fāshāo ma?"},{"speaker":"陈天中","cn":"好像发低烧了。","pinyin":"Hǎoxiàng fā dīshāo le."},{"speaker":"安妮","cn":"我送你去医院，让医生检查一下吧。","pinyin":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba."},{"speaker":"陈天中","cn":"我先回去睡一觉，可能休息休息就好了。","pinyin":"Wǒ xiān huíqù shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le."},{"speaker":"安妮","cn":"好吧，如果下午还发烧，就一定要去看医生。","pinyin":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng."},{"speaker":"陈天中","cn":"谢谢关心，我会注意的。","pinyin":"Xièxiè guānxīn, wǒ huì zhùyì de."}],"translation_vn":"Annie: Cậu sao vậy? Trông có vẻ hơi khó chịu.\nTrần Thiên Trung: Hôm qua bơi xong, tai mình cứ hơi đau.\nAnnie: Có phải bị cảm không? Có sốt không?\nTrần Thiên Trung: Hình như sốt nhẹ rồi.\nAnnie: Mình đưa cậu đi bệnh viện, để bác sĩ khám một chút nhé.\nTrần Thiên Trung: Mình về ngủ một giấc trước đã, có lẽ nghỉ ngơi là sẽ khỏi thôi.\nAnnie: Được rồi, nếu chiều vẫn còn sốt thì nhất định phải đi khám bác sĩ.\nTrần Thiên Trung: Cảm ơn cậu đã quan tâm, mình sẽ để ý.","audio_dialogue":"8-3.mp3","audio_vocab":"8-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"安妮","cn":"你怎么突然住院了？大家都很担心你。","pinyin":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ."},{"speaker":"陈天中","cn":"我的腿疼了几个星期了，医生说需要住院做检查。","pinyin":"Wǒ de tuǐ téng le jǐ ge xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá."},{"speaker":"安妮","cn":"你看起来一点儿也不像病人。","pinyin":"Nǐ kàn qǐlái yìdiǎnr yě bú xiàng bìngrén."},{"speaker":"陈天中","cn":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","pinyin":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le."},{"speaker":"安妮","cn":"你每天跑步，有时候还去游泳，是不是运动太多了？","pinyin":"Nǐ měitiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bu shì yùndòng tài duō le?"},{"speaker":"陈天中","cn":"医生也这么说，但是还得做完检查才能知道。","pinyin":"Yīshēng yě zhème shuō, dànshì hái děi zuò wán jiǎnchá cái néng zhīdào."},{"speaker":"安妮","cn":"别担心！听医生的话，好好休息，你的腿一定能好。","pinyin":"Bié dānxīn! Tīng yīshēng de huà, hǎohǎo xiūxi, nǐ de tuǐ yídìng néng hǎo."},{"speaker":"陈天中","cn":"谢谢。有人来看我，我就开心多了。","pinyin":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le."}],"translation_vn":"Annie: Sao cậu đột nhiên nhập viện vậy? Mọi người đều rất lo lắng cho cậu.\nTrần Thiên Trung: Chân mình đau mấy tuần rồi, bác sĩ nói cần nhập viện để kiểm tra.\nAnnie: Trông cậu chẳng giống bệnh nhân chút nào.\nTrần Thiên Trung: Đúng vậy, mình rất ít khi ốm. Lần trước mình đến bệnh viện đã gần hai năm rồi.\nAnnie: Ngày nào cậu cũng chạy bộ, thỉnh thoảng còn đi bơi nữa, có phải vận động quá nhiều không?\nTrần Thiên Trung: Bác sĩ cũng nói vậy, nhưng phải làm xong kiểm tra mới biết được.\nAnnie: Đừng lo! Nghe lời bác sĩ, nghỉ ngơi thật tốt, chân cậu chắc chắn sẽ khỏi.\nTrần Thiên Trung: Cảm ơn cậu. Có người đến thăm, mình thấy vui hơn nhiều.","audio_dialogue":"8-5.mp3","audio_vocab":"8-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天我出院了。","pinyin":"Jīntiān wǒ chūyuàn le."},{"speaker":"","cn":"出院前，医生给我开了几种药，而且告诉了我吃药的方法。","pinyin":"Chūyuàn qián, yīshēng gěi wǒ kāi le jǐ zhǒng yào, érqiě gàosu le wǒ chī yào de fāngfǎ."},{"speaker":"","cn":"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。","pinyin":"Yǒu yì zhǒng yào xūyào měitiān shuì qián chī yí cì, qítā jǐ zhǒng měitiān chī sān cì, fàn hòu chī."},{"speaker":"","cn":"除了吃药，医生还说最重要的是多休息。","pinyin":"Chúle chī yào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi."},{"speaker":"","cn":"我都记在心里了，回家以后一定会多注意。","pinyin":"Wǒ dōu jì zài xīnlǐ le, huí jiā yǐhòu yídìng huì duō zhùyì."},{"speaker":"","cn":"希望我的腿能快一点儿好。","pinyin":"Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo."}],"translation_vn":"Hôm nay tôi đã xuất viện. Trước khi xuất viện, bác sĩ đã kê cho tôi vài loại thuốc, và còn nói cho tôi biết cách uống thuốc. Có một loại thuốc cần uống mỗi ngày một lần trước khi ngủ, mấy loại khác thì mỗi ngày uống ba lần, uống sau bữa ăn. Ngoài việc uống thuốc, bác sĩ còn nói điều quan trọng nhất là nghỉ ngơi nhiều. Tôi đã ghi nhớ tất cả trong lòng, về nhà nhất định sẽ chú ý nhiều hơn. Hy vọng chân tôi sẽ sớm khỏi.","audio_dialogue":"8-7.mp3","audio_vocab":"8-8.mp3"}]},{"id":9,"title_cn":"打不好没关系","title_pinyin":"Dǎ bù hǎo méi guānxi","title_vn":"Chơi không giỏi cũng không sao","goals":["Có thể nghe hiểu và giới thiệu tên gọi, vận động viên, ảnh hưởng... của các cuộc thi đấu thể thao.","Có thể nghe hiểu và sử dụng bổ ngữ khả năng để diễn đạt khả năng xảy ra của một tình huống.","Nắm vững cách dùng cấu trúc \"越A越B\", có thể diễn đạt sự thay đổi của sự vật hoặc tình huống."],"vocab":[{"hanzi":"校园","pinyin":"xiàoyuán","pos":"dt.","vn":"khuôn viên trường"},{"hanzi":"卡","pinyin":"kǎ","pos":"dt.","vn":"thẻ"},{"hanzi":"球场","pinyin":"qiúchǎng","pos":"dt.","vn":"sân bóng"},{"hanzi":"为了","pinyin":"wèile","pos":"giới.","vn":"để, vì"},{"hanzi":"运动会","pinyin":"yùndònghuì","pos":"dt.","vn":"hội thao, đại hội thể thao"},{"hanzi":"男生","pinyin":"nánshēng","pos":"dt.","vn":"nam sinh"},{"hanzi":"练","pinyin":"liàn","pos":"dgt.","vn":"luyện tập"},{"hanzi":"参加","pinyin":"cānjiā","pos":"dgt.","vn":"tham gia"},{"hanzi":"网球","pinyin":"wǎngqiú","pos":"dt.","vn":"quần vợt, tennis"},{"hanzi":"比赛","pinyin":"bǐsài","pos":"dt./dgt.","vn":"cuộc thi đấu; thi đấu"},{"hanzi":"练习","pinyin":"liànxí","pos":"dgt./dt.","vn":"luyện tập; bài tập"},{"hanzi":"好多","pinyin":"hǎoduō","pos":"số.","vn":"rất nhiều"},{"hanzi":"几乎","pinyin":"jīhū","pos":"phó.","vn":"hầu như, gần như"},{"hanzi":"只是","pinyin":"zhǐshì","pos":"phó.","vn":"chỉ là, chỉ"},{"hanzi":"啤酒","pinyin":"píjiǔ","pos":"dt.","vn":"bia"},{"hanzi":"回","pinyin":"huí","pos":"lượng.","vn":"lần, việc (dùng cho sự việc)"},{"hanzi":"紧张","pinyin":"jǐnzhāng","pos":"tt.","vn":"căng thẳng, hồi hộp"},{"hanzi":"主要","pinyin":"zhǔyào","pos":"tt.","vn":"chủ yếu"},{"hanzi":"受到","pinyin":"shòudào","pos":"dgt.","vn":"chịu, bị (tác động)"},{"hanzi":"影响","pinyin":"yǐngxiǎng","pos":"dt./dgt.","vn":"ảnh hưởng"},{"hanzi":"得分","pinyin":"défēn","pos":"dgt./dt.","vn":"ghi điểm; điểm số"},{"hanzi":"体育","pinyin":"tǐyù","pos":"dt.","vn":"thể thao"},{"hanzi":"世界","pinyin":"shìjiè","pos":"dt.","vn":"thế giới"},{"hanzi":"运动员","pinyin":"yùndòngyuán","pos":"dt.","vn":"vận động viên"},{"hanzi":"得到","pinyin":"dédào","pos":"dgt.","vn":"nhận được, đạt được"},{"hanzi":"成绩","pinyin":"chéngjì","pos":"dt.","vn":"thành tích, kết quả"},{"hanzi":"奥运会","pinyin":"Àoyùnhuì","pos":"danh từ riêng","vn":"Thế vận hội Olympic"},{"hanzi":"刘长春","pinyin":"Liú Chángchūn","pos":"danh từ riêng","vn":"Lưu Trường Xuân (tên người)"}],"grammar":[{"title":"目的复句 \"为了……，……\" (Câu phức mục đích)","explanation_vn":"Trong câu phức mục đích \"为了……，……\", mệnh đề đứng sau \"为了\" nêu rõ mục đích, còn mệnh đề còn lại nêu hành động được thực hiện để đạt được mục đích đó.","examples":[{"cn":"听说为了准备运动会，你们几个男生每天都练球。","pinyin":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","vn":""},{"cn":"为了考上大学，她每天努力学习。","pinyin":"Wèile kǎoshàng dàxué, tā měitiān nǔlì xuéxí.","vn":""},{"cn":"为了早点儿到家，我打算坐飞机回去。","pinyin":"Wèile zǎodiǎnr dào jiā, wǒ dǎsuàn zuò fēijī huíqù.","vn":""}]},{"title":"可能补语 (Bổ ngữ khả năng)","explanation_vn":"Chèn \"得\" hoặc \"不\" vào giữa động từ và bổ ngữ kết quả hoặc bổ ngữ xu hướng để tạo thành bổ ngữ khả năng, biểu thị điều kiện có cho phép thực hiện được kết quả hoặc xu hướng đó hay không. Dạng khẳng định là \"Động từ + 得 + Bổ ngữ\", dạng phủ định là \"Động từ + 不 + Bổ ngữ\", dạng nghi vấn là \"Động từ + 得 + Bổ ngữ + Động từ + 不 + Bổ ngữ\" hoặc \"Động từ + 得 + Bổ ngữ + 吗\".","examples":[{"cn":"打不好没关系。","pinyin":"Dǎ bù hǎo méi guānxi.","vn":""},{"cn":"这本书你看得懂看不懂？","pinyin":"Zhè běn shū nǐ kàn de dǒng kàn bù dǒng?","vn":""},{"cn":"你只有一个星期的时间，学得会游泳吗？","pinyin":"Nǐ zhǐyǒu yí gè xīngqī de shíjiān, xué de huì yóuyǒng ma?","vn":""}]},{"title":"固定格式 \"越A越B\" (Cấu trúc cố định \"越A越B\")","explanation_vn":"Trong câu theo cấu trúc cố định \"越A越B\", A và B đều có thể là cụm động từ hoặc cụm tính từ, hoặc một bên là cụm động từ còn bên kia là cụm tính từ, biểu thị B thay đổi theo sự thay đổi của A.","examples":[{"cn":"今天的足球比赛我越看越着急。","pinyin":"Jīntiān de zúqiú bǐsài wǒ yuè kàn yuè zháojí.","vn":""},{"cn":"妈妈越说，他越不高兴。","pinyin":"Māma yuè shuō, tā yuè bù gāoxìng.","vn":""},{"cn":"我想认识中国朋友，越多越好。","pinyin":"Wǒ xiǎng rènshi Zhōngguó péngyou, yuè duō yuè hǎo.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，对不起，我昨天忘了还你校园卡了。","pinyin":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuánkǎ le."},{"speaker":"白家月","cn":"没关系。你怎么这么快就过来了？","pinyin":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlái le?"},{"speaker":"李文","cn":"我正在球场打球呢，接了你的电话就跑过来了。","pinyin":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiēle nǐ de diànhuà jiù pǎo guòlái le."},{"speaker":"白家月","cn":"听说为了准备运动会，你们几个男生每天都练球。","pinyin":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú."},{"speaker":"李文","cn":"是啊！你打算参加运动会吗？","pinyin":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?"},{"speaker":"白家月","cn":"我想参加网球比赛，最近一直在练习。","pinyin":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí."},{"speaker":"李文","cn":"好，到时候我去看你的比赛。","pinyin":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài."}],"translation_vn":"Lý Văn: Gia Nguyệt, xin lỗi, hôm qua mình quên trả thẻ khuôn viên trường cho bạn rồi.\nBạch Gia Nguyệt: Không sao. Sao bạn đến nhanh vậy?\nLý Văn: Mình đang đánh bóng ở sân thì nhận được điện thoại của bạn nên chạy ngay tới.\nBạch Gia Nguyệt: Nghe nói để chuẩn bị cho hội thao, mấy bạn nam các cậu ngày nào cũng luyện bóng.\nLý Văn: Đúng vậy! Bạn định tham gia hội thao à?\nBạch Gia Nguyệt: Mình muốn tham gia thi đấu quần vợt, gần đây vẫn đang luyện tập.\nLý Văn: Được, đến lúc đó mình sẽ đi xem trận đấu của bạn.","audio_dialogue":"9-1.mp3","audio_vocab":"9-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，你跟我们一起打羽毛球吧？","pinyin":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?"},{"speaker":"白家月","cn":"我好多年没打羽毛球了，几乎忘了怎么打了。","pinyin":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le."},{"speaker":"李文","cn":"不是比赛，打不好没关系。","pinyin":"Bú shì bǐsài, dǎ bù hǎo méi guānxi."},{"speaker":"白家月","cn":"这么多同学一起打，如果总是接不住球，就太不好意思了。","pinyin":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bú zhù qiú, jiù tài bù hǎoyìsi le."},{"speaker":"李文","cn":"你想得太多了！大家打球只是为了锻炼身体。","pinyin":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ."},{"speaker":"白家月","cn":"我先自己练练吧，下周再跟你们一起打。","pinyin":"Wǒ xiān zìjǐ liàn liàn ba, xiàzhōu zài gēn nǐmen yìqǐ dǎ."},{"speaker":"李文","cn":"我在教天中打羽毛球，你可以过来跟我们一起练。","pinyin":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlái gēn wǒmen yìqǐ liàn."}],"translation_vn":"Lý Văn: Gia Nguyệt, bạn chơi cầu lông cùng bọn mình nhé?\nBạch Gia Nguyệt: Mình đã nhiều năm không chơi cầu lông rồi, gần như quên mất cách chơi rồi.\nLý Văn: Không phải thi đấu đâu, chơi không giỏi cũng không sao.\nBạch Gia Nguyệt: Nhiều bạn cùng chơi với nhau như vậy, nếu mình cứ đỡ không được bóng thì ngại lắm.\nLý Văn: Bạn nghĩ nhiều quá rồi! Mọi người chơi bóng chỉ là để rèn luyện sức khỏe thôi.\nBạch Gia Nguyệt: Mình tự luyện tập một mình trước đã, tuần sau sẽ chơi cùng các bạn.\nLý Văn: Mình đang dạy Thiên Trung chơi cầu lông, bạn có thể qua luyện tập cùng chúng mình.","audio_dialogue":"9-3.mp3","audio_vocab":"9-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"陈天中","cn":"足球比赛已经开始了，快过来看吧！","pinyin":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlái kàn ba!"},{"speaker":"李文","cn":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","pinyin":"Nǐmen xiān kàn, bīngxiāng li yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià."},{"speaker":"白家月","cn":"今天怎么回事？总是踢不进去！","pinyin":"Jīntiān zěnme huí shì? Zǒngshì tī bú jìnqù!"},{"speaker":"陈天中","cn":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","pinyin":"Jǐ gè lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le."},{"speaker":"李文","cn":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","pinyin":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le."},{"speaker":"白家月","cn":"越看越着急。我不看了，你们告诉我得分吧。","pinyin":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosù wǒ défēn ba."}],"translation_vn":"Trần Thiên Trung: Trận bóng đá đã bắt đầu rồi, mau lại xem đi!\nLý Văn: Các bạn xem trước đi, trong tủ lạnh có bia và nước giải khát, mình đi lấy một chút.\nBạch Gia Nguyệt: Hôm nay là chuyện gì vậy? Cứ sút mãi không vào!\nTrần Thiên Trung: Mấy cầu thủ kỳ cựu bị ốm rồi, cầu thủ mới lần đầu tham gia trận đấu quan trọng thế này nên căng thẳng quá.\nLý Văn: Đúng vậy, cầu thủ chủ lực không tham gia thi đấu, nên mọi người cũng đều bị ảnh hưởng.\nBạch Gia Nguyệt: Càng xem càng sốt ruột. Mình không xem nữa, các bạn cứ báo điểm số cho mình nhé.","audio_dialogue":"9-5.mp3","audio_vocab":"9-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我喜欢看体育比赛，最爱看的就是奥运会。","pinyin":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiùshì Àoyùnhuì."},{"speaker":"","cn":"奥运会是世界上影响最大的体育比赛。","pinyin":"Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài."},{"speaker":"","cn":"从1896年到2024年，每次奥运会都有非常多的运动员参加。","pinyin":"Cóng yī bā jiǔ liù nián dào èr líng èr sì nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā."},{"speaker":"","cn":"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。","pinyin":"Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā yī jiǔ sān èr nián cānjiāle yìbǎi mǐ hé èrbǎi mǐ duǎnpǎo bǐsài."},{"speaker":"","cn":"虽然他没有得到好成绩，但是他让世界认识了中国。","pinyin":"Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshile Zhōngguó."}],"translation_vn":"Tôi thích xem các cuộc thi đấu thể thao, thích xem nhất là Thế vận hội Olympic. Olympic là cuộc thi đấu thể thao có ảnh hưởng lớn nhất trên thế giới. Từ năm 1896 đến năm 2024, mỗi kỳ Olympic đều có rất nhiều vận động viên tham gia. Vận động viên Trung Quốc đầu tiên tham gia Olympic là Lưu Trường Xuân, năm 1932 ông đã tham gia các nội dung chạy nước rút 100 mét và 200 mét. Tuy ông không đạt được thành tích tốt, nhưng ông đã giúp thế giới biết đến Trung Quốc.","audio_dialogue":"9-7.mp3","audio_vocab":"9-8.mp3"}]},{"id":10,"title_cn":"你明天再把书还给我","title_pinyin":"Nǐ Míngtiān Zài Bǎ Shū Huán Gěi Wǒ","title_vn":"Ngày mai bạn trả sách lại cho tôi nhé","goals":["Có thể nghe hiểu và giới thiệu về tình hình học tập và thi cử.","Có thể nghe hiểu và trao đổi về những vấn đề gặp phải trong học tập, chia sẻ phương pháp học tập.","Nắm vững cách dùng câu chữ \"把\" (1), có thể miêu tả sự thay đổi vị trí của sự vật.","Hiểu biết về hệ thống giáo dục và chế độ chuyển cấp học của Trung Quốc."],"vocab":[{"hanzi":"数学","pinyin":"shùxué","pos":"dt.","vn":"môn Toán, toán học"},{"hanzi":"认真","pinyin":"rènzhēn","pos":"tt.","vn":"nghiêm túc, cẩn thận, chăm chú"},{"hanzi":"笔记","pinyin":"bǐjì","pos":"dt.","vn":"ghi chú, vở ghi chép"},{"hanzi":"清楚","pinyin":"qīngchu","pos":"tt./dgt.","vn":"rõ ràng; hiểu rõ"},{"hanzi":"黑板","pinyin":"hēibǎn","pos":"dt.","vn":"bảng đen"},{"hanzi":"把","pinyin":"bǎ","pos":"giới.","vn":"(giới từ đưa tân ngữ lên trước động từ)"},{"hanzi":"作业","pinyin":"zuòyè","pos":"dt.","vn":"bài tập"},{"hanzi":"遍","pinyin":"biàn","pos":"lượng.","vn":"lần (chỉ một lượt hành động trọn vẹn)"},{"hanzi":"提高","pinyin":"tígāo","pos":"dgt.","vn":"nâng cao, cải thiện"},{"hanzi":"历史","pinyin":"lìshǐ","pos":"dt.","vn":"lịch sử"},{"hanzi":"难","pinyin":"nán","pos":"tt.","vn":"khó"},{"hanzi":"要求","pinyin":"yāoqiú","pos":"dt./dgt.","vn":"yêu cầu"},{"hanzi":"差","pinyin":"chà","pos":"tt./dgt.","vn":"kém; thiếu"},{"hanzi":"复习","pinyin":"fùxí","pos":"dgt.","vn":"ôn tập"},{"hanzi":"外语","pinyin":"wàiyǔ","pos":"dt.","vn":"ngoại ngữ"},{"hanzi":"当然","pinyin":"dāngrán","pos":"phó.","vn":"đương nhiên, tất nhiên"},{"hanzi":"遇到","pinyin":"yùdào","pos":"dgt.","vn":"gặp phải, gặp"},{"hanzi":"办公室","pinyin":"bàngōngshì","pos":"dt.","vn":"văn phòng"},{"hanzi":"页","pinyin":"yè","pos":"lượng.","vn":"trang"},{"hanzi":"对话","pinyin":"duìhuà","pos":"dgt.","vn":"hội thoại, đối thoại"},{"hanzi":"明白","pinyin":"míngbai","pos":"dgt./tt.","vn":"hiểu, hiểu rõ"},{"hanzi":"讲","pinyin":"jiǎng","pos":"dgt.","vn":"giảng, giải thích"},{"hanzi":"句","pinyin":"jù","pos":"lượng.","vn":"câu (lượng từ dùng cho câu nói)"},{"hanzi":"句子","pinyin":"jùzi","pos":"dt.","vn":"câu"},{"hanzi":"年级","pinyin":"niánjí","pos":"dt.","vn":"khối lớp, cấp lớp"},{"hanzi":"后年","pinyin":"hòunián","pos":"dt.","vn":"năm kia (năm sau năm sau)"},{"hanzi":"一般","pinyin":"yìbān","pos":"tt.","vn":"bình thường, thông thường"},{"hanzi":"努力","pinyin":"nǔlì","pos":"tt./dgt.","vn":"nỗ lực, cố gắng"}],"grammar":[{"title":"\"把\"字句 (1) - Câu chữ \"把\" (1)","explanation_vn":"Câu chữ \"把\" biểu thị việc thực hiện một hành động tương ứng lên một người hoặc sự vật xác định, khiến nó xảy ra sự thay đổi về vị trí. Phó từ phủ định \"不/没\" và động từ năng nguyện phải đặt trước \"把\". Cấu trúc cơ bản: Chủ ngữ + (不/没/Động từ năng nguyện) + 把 + Tân ngữ + Động từ + 在/到 + Địa điểm.","examples":[{"cn":"我会把这些题都记在本子上。","pinyin":"Wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vn":""},{"cn":"老师把作业本放到桌子上了。","pinyin":"Lǎoshī bǎ zuòyèběn fàng dào zhuōzi shang le.","vn":""},{"cn":"你不能把名字写在这里。","pinyin":"Nǐ bù néng bǎ míngzi xiě zài zhèlǐ.","vn":""}]},{"title":"固定格式 \"在……上/中/下\" - Cấu trúc cố định \"在……上/中/下\"","explanation_vn":"Giới từ \"在\" kết hợp với các phương vị từ \"上\" \"中\" \"下\" tạo thành cấu trúc \"在……上/中/下\", dùng để biểu thị phạm vi, thời gian, điều kiện, v.v. Cấu trúc \"在 + danh từ/cụm danh từ + 上\" biểu thị phạm vi, phương diện. Cấu trúc \"在……中\" biểu thị môi trường hoặc thời gian mà hành động xảy ra hay trạng thái tồn tại. Cấu trúc \"在 + động từ song âm tiết có định ngữ + 下\" biểu thị điều kiện.","examples":[{"cn":"在学习上，遇到什么问题都可以问我。","pinyin":"Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","vn":""},{"cn":"在工作上，他总是能给我很多帮助。","pinyin":"Zài gōngzuò shang, tā zǒngshì néng gěi wǒ hěn duō bāngzhù.","vn":""},{"cn":"在比赛中，他得分最高。","pinyin":"Zài bǐsài zhōng, tā défēn zuì gāo.","vn":""},{"cn":"在假期中，我认识了几个新朋友。","pinyin":"Zài jiàqī zhōng, wǒ rènshi le jǐ gè xīn péngyou.","vn":""},{"cn":"在她的影响下，我开始喜欢拍照。","pinyin":"Zài tā de yǐngxiǎng xià, wǒ kāishǐ xǐhuan pāizhào.","vn":""},{"cn":"在老师的帮助下，我的成绩提高很快。","pinyin":"Zài lǎoshī de bāngzhù xià, wǒ de chéngjì tígāo hěn kuài.","vn":""}]},{"title":"\"把\"字句 (2) - Câu chữ \"把\" (2)","explanation_vn":"Câu chữ \"把\" ở dạng này biểu thị việc thông qua hành động khiến một sự vật xác định có sự chuyển giao về mặt quan hệ (từ người này sang người khác). Cấu trúc cơ bản: Chủ ngữ + 把 + Tân ngữ 1 + Động từ + 给 + Tân ngữ 2.","examples":[{"cn":"你明天再把书还给我。","pinyin":"Nǐ míngtiān zài bǎ shū huán gěi wǒ.","vn":""},{"cn":"我把礼物送给她了。","pinyin":"Wǒ bǎ lǐwù sòng gěi tā le.","vn":""},{"cn":"请你把这本书带给老师。","pinyin":"Qǐng nǐ bǎ zhè běn shū dài gěi lǎoshī.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"同学","cn":"你的数学越来越好，能不能介绍一下学习方法？","pinyin":"Nǐ de shùxué yuè lái yuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?"},{"speaker":"刘小雪","cn":"没有什么特别的方法，认真听课，认真记笔记。","pinyin":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì."},{"speaker":"同学","cn":"我看过你的笔记，记得非常清楚。","pinyin":"Wǒ kàn guò nǐ de bǐjì, jì de fēicháng qīngchu."},{"speaker":"刘小雪","cn":"老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","pinyin":"Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang."},{"speaker":"同学","cn":"你说得对。我没有记笔记的习惯。","pinyin":"Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn."},{"speaker":"刘小雪","cn":"笔记挺重要的，我每天写作业以前，都要看一遍。","pinyin":"Bǐjì tǐng zhòngyào de, wǒ měitiān xiě zuòyè yǐqián, dōu yào kàn yí biàn."},{"speaker":"同学","cn":"这个方法真好！我以后也试试，希望能提高成绩。","pinyin":"Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì."}],"translation_vn":"Bạn học: Toán của bạn ngày càng tốt lên, bạn có thể giới thiệu một chút phương pháp học tập không?\nLưu Tiểu Tuyết: Không có phương pháp gì đặc biệt cả, chỉ là nghe giảng chăm chú, ghi chép cẩn thận.\nBạn học: Mình đã xem vở ghi chép của bạn, ghi rất rõ ràng.\nLưu Tiểu Tuyết: Những bài thầy cô viết trên bảng đều rất quan trọng, nên mình ghi hết những bài đó vào vở.\nBạn học: Bạn nói đúng. Mình không có thói quen ghi chép.\nLưu Tiểu Tuyết: Vở ghi chép khá quan trọng, trước khi làm bài tập mỗi ngày mình đều xem lại một lượt.\nBạn học: Phương pháp này hay thật! Sau này mình cũng sẽ thử, hy vọng có thể nâng cao thành tích.","audio_dialogue":"10-1.mp3","audio_vocab":"10-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"同学","cn":"小雪，昨天的考试，你考得怎么样？","pinyin":"Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?"},{"speaker":"刘小雪","cn":"我觉得历史有点儿难，你呢？","pinyin":"Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?"},{"speaker":"同学","cn":"数学考试我没看清楚要求，做错了好几个题，考得挺差的。","pinyin":"Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuò cuò le hǎo jǐ gè tí, kǎo de tǐng chà de."},{"speaker":"刘小雪","cn":"明天还有考试呢，别想那么多了，先复习外语吧。","pinyin":"Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba."},{"speaker":"同学","cn":"外语作业里有几个问题，我可以问问你吗？","pinyin":"Wàiyǔ zuòyè lǐ yǒu jǐ gè wèntí, wǒ kěyǐ wènwen nǐ ma?"},{"speaker":"刘小雪","cn":"当然可以。在学习上，遇到什么问题都可以问我。","pinyin":"Dāngrán kěyǐ. Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ."},{"speaker":"刘小雪","cn":"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","pinyin":"Bù hǎoyìsi, zhè jǐ gè tí wǒ yě bú huì. Zánmen háishi yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba."}],"translation_vn":"Bạn học: Tiểu Tuyết, bài thi hôm qua, bạn thi thế nào?\nLưu Tiểu Tuyết: Mình thấy môn Lịch sử hơi khó, còn bạn thì sao?\nBạn học: Bài thi Toán mình không đọc kỹ yêu cầu, làm sai mấy câu, thi khá tệ.\nLưu Tiểu Tuyết: Ngày mai còn có bài thi nữa đấy, đừng nghĩ nhiều quá, ôn ngoại ngữ trước đi.\nBạn học: Trong bài tập ngoại ngữ có mấy câu hỏi, mình có thể hỏi bạn không?\nLưu Tiểu Tuyết: Tất nhiên được rồi. Trong học tập, gặp vấn đề gì đều có thể hỏi mình.\n(……)\nLưu Tiểu Tuyết: Xin lỗi nhé, mấy câu này mình cũng không biết làm. Hay là chúng ta cùng đến văn phòng hỏi cô Lý vậy.","audio_dialogue":"10-3.mp3","audio_vocab":"10-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"同学","cn":"李老师，书上有几个问题，我们想问问您。","pinyin":"Lǐ lǎoshī, shū shang yǒu jǐ gè wèntí, wǒmen xiǎng wènwen nín."},{"speaker":"李老师","cn":"好，坐下说吧，哪个题不会？","pinyin":"Hǎo, zuò xià shuō ba, nǎge tí bú huì?"},{"speaker":"同学","cn":"书上第五页的这个对话我看不懂，小雪也不明白。","pinyin":"Shū shang dì-wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai."},{"speaker":"李老师","cn":"我课上讲过这几句话，再给你们讲一遍。","pinyin":"Wǒ kè shang jiǎng guò zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn."},{"speaker":"","cn":"（李老师给学生讲题。）","pinyin":"(Lǐ lǎoshī gěi xuésheng jiǎng tí.)"},{"speaker":"同学","cn":"我终于懂了。这些句子一点儿也不难。","pinyin":"Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán."},{"speaker":"刘小雪","cn":"我也明白了，谢谢您，李老师。","pinyin":"Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī."},{"speaker":"李老师","cn":"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","pinyin":"Wǒ zhè běn shū shang hái yǒu jǐ gè liànxí, nǐmen huí jiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ."}],"translation_vn":"Bạn học: Cô Lý ơi, trong sách có vài câu hỏi, chúng em muốn hỏi cô.\nCô Lý: Được, ngồi xuống nói đi, câu nào không hiểu?\nBạn học: Đoạn hội thoại ở trang 5 trong sách em không hiểu, Tiểu Tuyết cũng không hiểu.\nCô Lý: Cô đã giảng mấy câu này trên lớp rồi, cô sẽ giảng lại cho các em một lần nữa.\n(Cô Lý giảng bài cho học sinh.)\nBạn học: Cuối cùng em cũng hiểu rồi. Những câu này không khó chút nào.\nLưu Tiểu Tuyết: Em cũng hiểu rồi ạ, cảm ơn cô Lý.\nCô Lý: Quyển sách này của cô còn vài bài luyện tập nữa, các em về nhà làm thử nhé, mai lại trả sách cho cô.","audio_dialogue":"10-5.mp3","audio_vocab":"10-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"家月姐姐：","pinyin":"Jiāyuè jiějie:"},{"speaker":"","cn":"你最近怎么样？忙不忙？","pinyin":"Nǐ zuìjìn zěnmeyàng? Máng bu máng?"},{"speaker":"","cn":"我现在上初中二年级，学习越来越忙，后年就要考高中了。","pinyin":"Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuè lái yuè máng, hòunián jiù yào kǎo gāozhōng le."},{"speaker":"","cn":"中国的学校一般是小学六年，初中三年，高中三年。","pinyin":"Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián."},{"speaker":"","cn":"妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。","pinyin":"Māma shuō xiǎng kǎo shàng hǎo dàxué, jiù děi shàng yí gè hǎo gāozhōng; wèile kǎo shàng hǎo gāozhōng, chūzhōng jiù děi yǒu yí gè búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì."},{"speaker":"","cn":"家月姐姐，你知道吗？在你的影响下，我也开始喜欢拍照了。","pinyin":"Jiāyuè jiějie, nǐ zhīdào ma? Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le."},{"speaker":"","cn":"下次你再来北京，我给你看看我照的照片。","pinyin":"Xiàcì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn."}],"translation_vn":"Chị Gia Nguyệt ơi: Dạo này chị thế nào? Có bận không? Em hiện đang học lớp hai trung học cơ sở, việc học ngày càng bận rộn, hai năm nữa là em phải thi vào trung học phổ thông rồi. Trường học ở Trung Quốc thường là tiểu học 6 năm, trung học cơ sở 3 năm, trung học phổ thông 3 năm. Mẹ em nói muốn thi đỗ đại học tốt thì phải học một trường trung học phổ thông tốt; để thi đỗ được trường trung học phổ thông tốt, ở bậc trung học cơ sở phải có thành tích khá mới được, vì vậy hiện giờ em đang rất nỗ lực học tập. Chị Gia Nguyệt biết không? Dưới ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi đấy. Lần sau chị đến Bắc Kinh, em sẽ cho chị xem những bức ảnh em chụp nhé.","audio_dialogue":"10-7.mp3","audio_vocab":"10-8.mp3"}]},{"id":11,"title_cn":"看来我没办法解决这个问题","title_pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí","title_vn":"Có vẻ như tôi không có cách nào giải quyết vấn đề này","goals":["Có thể nghe hiểu và trao đổi về tình hình công việc.","Có thể nghe hiểu và bàn luận về lựa chọn nghề nghiệp và cảm nhận về công việc.","Nắm vững cách dùng \"看来\" (có vẻ như), có thể suy đoán và phân tích sự việc."],"vocab":[{"hanzi":"会议","pinyin":"huìyì","pos":"dt.","vn":"cuộc họp, hội nghị"},{"hanzi":"经理","pinyin":"jīnglǐ","pos":"dt.","vn":"giám đốc, quản lý"},{"hanzi":"开会","pinyin":"kāihuì","pos":"dgt.","vn":"họp, mở cuộc họp"},{"hanzi":"后天","pinyin":"hòutiān","pos":"dt.","vn":"ngày kia"},{"hanzi":"地点","pinyin":"dìdiǎn","pos":"dt.","vn":"địa điểm"},{"hanzi":"室","pinyin":"shì","pos":"dt.","vn":"phòng"},{"hanzi":"发","pinyin":"fā","pos":"dgt.","vn":"gửi, phát"},{"hanzi":"笔记本（电脑）","pinyin":"bǐjìběn (diànnǎo)","pos":"dt.","vn":"máy tính xách tay"},{"hanzi":"或者","pinyin":"huòzhě","pos":"liên.","vn":"hoặc, hoặc là"},{"hanzi":"声音","pinyin":"shēngyīn","pos":"dt.","vn":"âm thanh"},{"hanzi":"看来","pinyin":"kànlái","pos":"dgt.","vn":"có vẻ như, xem ra"},{"hanzi":"办法","pinyin":"bànfǎ","pos":"dt.","vn":"cách, biện pháp"},{"hanzi":"解决","pinyin":"jiějué","pos":"dgt.","vn":"giải quyết"},{"hanzi":"只能","pinyin":"zhǐ néng","pos":"","vn":"chỉ có thể"},{"hanzi":"别人","pinyin":"biérén","pos":"đt.","vn":"người khác"},{"hanzi":"请假","pinyin":"qǐngjià","pos":"dgt.","vn":"xin nghỉ phép"},{"hanzi":"同事","pinyin":"tóngshì","pos":"dt.","vn":"đồng nghiệp"},{"hanzi":"休假","pinyin":"xiūjià","pos":"dgt.","vn":"nghỉ phép, nghỉ mát"},{"hanzi":"怕","pinyin":"pà","pos":"dgt.","vn":"sợ, e ngại"},{"hanzi":"邮箱","pinyin":"yóuxiāng","pos":"dt.","vn":"hộp thư điện tử, email"},{"hanzi":"老张","pinyin":"Lǎo Zhāng","pos":"danh từ riêng","vn":"Lão Trương (tên người)"},{"hanzi":"愿意","pinyin":"yuànyì","pos":"đtnn.","vn":"sẵn lòng, đồng ý"},{"hanzi":"城市","pinyin":"chéngshì","pos":"dt.","vn":"thành phố"},{"hanzi":"离开","pinyin":"líkāi","pos":"dgt.","vn":"rời khỏi, rời xa"},{"hanzi":"机会","pinyin":"jīhuì","pos":"dt.","vn":"cơ hội"},{"hanzi":"生活","pinyin":"shēnghuó","pos":"dt./dgt.","vn":"cuộc sống; sống"},{"hanzi":"为","pinyin":"wèi","pos":"giới.","vn":"vì, cho"},{"hanzi":"或","pinyin":"huò","pos":"liên.","vn":"hoặc"}],"grammar":[{"title":"\"还是\" và \"或者\" (So sánh cách dùng \"还是\" và \"或者\")","explanation_vn":"\"还是\" thường dùng trong câu nghi vấn, đưa ra hai hoặc nhiều lựa chọn, yêu cầu người nghe chọn một trong số đó. \"或者\" chủ yếu dùng trong câu trần thuật, không dùng trong câu nghi vấn.","examples":[{"cn":"我们用会议室的电脑还是自己的笔记本电脑？","pinyin":"Wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vn":""},{"cn":"我们今天去、明天去还是后天去？","pinyin":"Wǒmen jīntiān qù, míngtiān qù háishi hòutiān qù?","vn":""},{"cn":"会议室的电脑或者自己的电脑都可以。","pinyin":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","vn":""},{"cn":"你可以坐地铁或者打车去学校。","pinyin":"Nǐ kěyǐ zuò dìtiě huòzhě dǎchē qù xuéxiào.","vn":""}]},{"title":"Cụm từ cố định \"看来\"","explanation_vn":"Cụm từ cố định \"看来\" đứng trước một kết luận, biểu thị người nói đưa ra phân tích hoặc suy đoán về tình huống hiện tại thông qua quan sát, suy nghĩ.","examples":[{"cn":"看来我没办法解决这个问题。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí.","vn":""},{"cn":"这么晚了，看来他今天不会来了。","pinyin":"Zhème wǎn le, kànlái tā jīntiān bú huì lái le.","vn":""},{"cn":"电梯坏了，看来咱们只能走下去了。","pinyin":"Diàntī huài le, kànlái zánmen zhǐ néng zǒu xiàqù le.","vn":""}]},{"title":"Câu chữ \"把\" (3)","explanation_vn":"Câu chữ \"把\" biểu thị một hành động tác động lên người hoặc vật xác định, tạo ra một kết quả nào đó. Cấu trúc cơ bản: \"Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ kết quả\".","examples":[{"cn":"我跟您一起把这些工作做完。","pinyin":"Wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuò wán.","vn":""},{"cn":"妈妈把衣服洗干净了。","pinyin":"Māma bǎ yīfu xǐ gānjìng le.","vn":""},{"cn":"他还没把笔记本电脑接好呢。","pinyin":"Tā hái méi bǎ bǐjìběn diànnǎo jiē hǎo ne.","vn":""}]},{"title":"Cấu trúc cố định \"对……来说\"","explanation_vn":"Cấu trúc cố định \"对……来说\" (đối với... mà nói) chỉ rõ đối tượng mà quan điểm, cảm nhận hoặc tình huống được nêu ra hướng tới.","examples":[{"cn":"对我来说，生活也很重要，我不愿意为工作或学习离开家人。","pinyin":"Duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vn":""},{"cn":"对她来说，学习汉语很有意思。","pinyin":"Duì tā lái shuō, xuéxí Hànyǔ hěn yǒuyìsi.","vn":""},{"cn":"对孩子来说，玩也是一种学习。","pinyin":"Duì háizi lái shuō, wán yě shì yì zhǒng xuéxí.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"会议下午几点开始？","pinyin":"Huìyì xiàwǔ jǐ diǎn kāishǐ?"},{"speaker":"杨同乐","cn":"今天下午经理不在，不开会了。","pinyin":"Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le."},{"speaker":"王一雪","cn":"那什么时候开会？","pinyin":"Nà shénme shíhou kāihuì?"},{"speaker":"杨同乐","cn":"后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","pinyin":"Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàn dào dì yī huìyìshì. Wǒ zhèng yào gěi dàjiā fā yóujiàn."},{"speaker":"王一雪","cn":"开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","pinyin":"Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?"},{"speaker":"杨同乐","cn":"会议室的电脑或者自己的电脑都可以。","pinyin":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ."},{"speaker":"王一雪","cn":"那到时候咱们早点儿过去，你帮我把电脑接好吧。","pinyin":"Nà dào shíhou zánmen zǎo diǎnr guòqù, nǐ bāng wǒ bǎ diànnǎo jiē hǎo ba."}],"translation_vn":"Vương Nhất Tuyết: Mấy giờ chiều nay bắt đầu họp?\nDương Đồng Nhạc: Chiều nay giám đốc không có mặt, nên không họp nữa.\nVương Nhất Tuyết: Vậy bao giờ thì họp?\nDương Đồng Nhạc: Mười giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số 1. Tôi đang định gửi email cho mọi người.\nVương Nhất Tuyết: Lúc họp, chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?\nDương Đồng Nhạc: Dùng máy tính của phòng họp hay máy tính của mình đều được.\nVương Nhất Tuyết: Vậy lúc đó chúng ta đến sớm một chút, anh giúp tôi cài đặt máy tính nhé.","audio_dialogue":"11-1.mp3","audio_vocab":"11-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"电脑接好了吗？","pinyin":"Diànnǎo jiē hǎo le ma?"},{"speaker":"杨同乐","cn":"已经接好了，您开机看看有没有问题。","pinyin":"Yǐjīng jiē hǎo le, nín kāijī kànkan yǒu méiyǒu wèntí."},{"speaker":"王一雪","cn":"现在什么都看不见。","pinyin":"Xiànzài shénme dōu kàn bu jiàn."},{"speaker":"杨同乐","cn":"我检查一下哪里出问题了……您再试一下。","pinyin":"Wǒ jiǎnchá yíxià nǎlǐ chū wèntí le... nín zài shì yíxià."},{"speaker":"王一雪","cn":"看见了，但是听不见声音。","pinyin":"Kànjiàn le, dànshì tīng bu jiàn shēngyīn."},{"speaker":"杨同乐","cn":"现在呢？","pinyin":"Xiànzài ne?"},{"speaker":"王一雪","cn":"听得见声音，但是声音有点儿小，听不清楚。","pinyin":"Tīng de jiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīng bu qīngchu."},{"speaker":"杨同乐","cn":"看来我没办法解决这个问题，只能找别人来帮帮忙了。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐ néng zhǎo biérén lái bāngbangmáng le."}],"translation_vn":"Vương Nhất Tuyết: Máy tính đã kết nối xong chưa?\nDương Đồng Nhạc: Kết nối xong rồi, chị mở máy xem có vấn đề gì không.\nVương Nhất Tuyết: Bây giờ không nhìn thấy gì cả.\nDương Đồng Nhạc: Để tôi kiểm tra xem chỗ nào bị lỗi... chị thử lại lần nữa xem.\nVương Nhất Tuyết: Nhìn thấy rồi, nhưng không nghe thấy âm thanh.\nDương Đồng Nhạc: Bây giờ thì sao?\nVương Nhất Tuyết: Nghe thấy âm thanh rồi, nhưng âm thanh hơi nhỏ, nghe không rõ.\nDương Đồng Nhạc: Có vẻ như tôi không có cách nào giải quyết vấn đề này, chỉ có thể tìm người khác đến giúp thôi.","audio_dialogue":"11-3.mp3","audio_vocab":"11-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"同乐，你看见老张了吗？","pinyin":"Tóng Lè, nǐ kànjiàn Lǎo Zhāng le ma?"},{"speaker":"杨同乐","cn":"老张没来。他说家里有点儿事，所以请假了。","pinyin":"Lǎo Zhāng méi lái. Tā shuō jiālǐ yǒudiǎnr shì, suǒyǐ qǐngjià le."},{"speaker":"王一雪","cn":"好几个同事都休假了，开会前这么多工作我怕干不完。","pinyin":"Hǎo jǐ gè tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gàn bu wán."},{"speaker":"杨同乐","cn":"十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","pinyin":"Shí'èr diǎn duō le, zánmen xiān qù chīfàn ba. Chī wán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuò wán."},{"speaker":"王一雪","cn":"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","pinyin":"Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fā dào gōngsī de yóuxiāng lǐ."},{"speaker":"杨同乐","cn":"您没看到邮件吗？经理还没回来呢，下周才能开会。","pinyin":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xiàzhōu cái néng kāihuì."},{"speaker":"王一雪","cn":"那不着急了。走，吃饭去。","pinyin":"Nà bù zháojí le. Zǒu, chīfàn qù."}],"translation_vn":"Vương Nhất Tuyết: Đồng Nhạc, anh có thấy Lão Trương không?\nDương Đồng Nhạc: Lão Trương không đến. Anh ấy nói nhà có chút việc nên xin nghỉ phép rồi.\nVương Nhất Tuyết: Mấy đồng nghiệp đều nghỉ phép cả, nhiều việc thế này trước khi họp tôi sợ làm không xong.\nDương Đồng Nhạc: Hơn mười hai giờ rồi, chúng ta đi ăn cơm trước đã. Ăn xong, tôi sẽ cùng chị làm nốt chỗ việc này.\nVương Nhất Tuyết: Anh đi ăn trước đi, tôi muốn làm thêm một lát nữa. Trước khi họp ngày mai phải gửi vào hộp thư của công ty.\nDương Đồng Nhạc: Chị không xem email à? Giám đốc vẫn chưa về, tuần sau mới có thể họp được.\nVương Nhất Tuyết: Vậy thì không vội nữa. Đi nào, đi ăn cơm thôi.","audio_dialogue":"11-5.mp3","audio_vocab":"11-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"前几天，上海的同事来北京了。","pinyin":"Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le."},{"speaker":"","cn":"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。","pinyin":"Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi."},{"speaker":"","cn":"我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。","pinyin":"Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎoxuě hé Xiǎomíng yě hái xiǎo, wǒ qù bié de chéngshì gōngzuò jiù yào líkāi tāmen."},{"speaker":"","cn":"虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","pinyin":"Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ lái shuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén."}],"translation_vn":"Mấy ngày trước, đồng nghiệp ở Thượng Hải đến Bắc Kinh. Khi cùng ăn cơm, họ nói với tôi rằng gần đây có không ít đồng nghiệp đã đi Thượng Hải làm việc, và hỏi tôi có sẵn lòng cũng đến Thượng Hải hay không. Tôi đã nghĩ như thế này: hiện tại chồng và các con đều ở Bắc Kinh, công việc của Lưu Minh rất bận, Tiểu Tuyết và Tiểu Minh cũng còn nhỏ, nếu tôi đi làm việc ở thành phố khác thì sẽ phải rời xa họ. Tuy đi Thượng Hải có thể sẽ có cơ hội tốt hơn, nhưng đối với tôi mà nói, cuộc sống gia đình cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa người thân.","audio_dialogue":"11-7.mp3","audio_vocab":"11-8.mp3"}]},{"id":12,"title_cn":"这个季节天气变化很快","title_pinyin":"Zhège jìjié tiānqì biànhuà hěn kuài","title_vn":"Mùa này thời tiết thay đổi rất nhanh","goals":["Có thể nghe hiểu và nói chuyện về sự thay đổi của thời tiết.","Có thể nghe hiểu và giới thiệu tình hình khí hậu của một nơi cũng như sở thích của bản thân về các mùa.","Nắm được cách dùng của \"就\", có thể nhấn mạnh số lượng ít hoặc trường hợp ngoại lệ.","Hiểu được đặc điểm bốn mùa ở Bắc Kinh."],"vocab":[{"hanzi":"街","pinyin":"jiē","pos":"dt.","vn":"đường phố, phố"},{"hanzi":"开花","pinyin":"kāihuā","pos":"dgt.","vn":"nở hoa"},{"hanzi":"公园","pinyin":"gōngyuán","pos":"dt.","vn":"công viên"},{"hanzi":"船","pinyin":"chuán","pos":"dt.","vn":"thuyền, tàu"},{"hanzi":"工作日","pinyin":"gōngzuòrì","pos":"dt.","vn":"ngày làm việc"},{"hanzi":"地方","pinyin":"dìfang","pos":"dt.","vn":"nơi, địa điểm"},{"hanzi":"刚才","pinyin":"gāngcái","pos":"dt.","vn":"vừa nãy, lúc nãy"},{"hanzi":"刮","pinyin":"guā","pos":"dgt.","vn":"thổi (gió)"},{"hanzi":"风","pinyin":"fēng","pos":"dt.","vn":"gió"},{"hanzi":"新闻","pinyin":"xīnwén","pos":"dt.","vn":"tin tức, bản tin thời sự"},{"hanzi":"伞","pinyin":"sǎn","pos":"dt.","vn":"cái ô, cái dù"},{"hanzi":"借","pinyin":"jiè","pos":"dgt.","vn":"mượn, cho mượn"},{"hanzi":"把","pinyin":"bǎ","pos":"lượng.","vn":"cái (lượng từ dùng cho vật có cán cầm)"},{"hanzi":"雨衣","pinyin":"yǔyī","pos":"dt.","vn":"áo mưa"},{"hanzi":"变","pinyin":"biàn","pos":"dgt.","vn":"biến đổi, thay đổi"},{"hanzi":"季节","pinyin":"jìjié","pos":"dt.","vn":"mùa, mùa trong năm"},{"hanzi":"变化","pinyin":"biànhuà","pos":"dgt./dt.","vn":"thay đổi, biến hóa; sự thay đổi"},{"hanzi":"冬天","pinyin":"dōngtiān","pos":"dt.","vn":"mùa đông"},{"hanzi":"常常","pinyin":"chángcháng","pos":"phó.","vn":"thường, thường xuyên"},{"hanzi":"关注","pinyin":"guānzhù","pos":"dgt.","vn":"quan tâm, chú ý theo dõi"},{"hanzi":"四季","pinyin":"sìjì","pos":"dt.","vn":"bốn mùa"},{"hanzi":"春天","pinyin":"chūntiān","pos":"dt.","vn":"mùa xuân"},{"hanzi":"夏天","pinyin":"xiàtiān","pos":"dt.","vn":"mùa hè"},{"hanzi":"凉快","pinyin":"liángkuai","pos":"tt.","vn":"mát mẻ, dễ chịu"},{"hanzi":"秋天","pinyin":"qiūtiān","pos":"dt.","vn":"mùa thu"},{"hanzi":"叶子","pinyin":"yèzi","pos":"dt.","vn":"lá cây"},{"hanzi":"变成","pinyin":"biànchéng","pos":"dgt.","vn":"biến thành, trở thành"}],"grammar":[{"title":"选择复句\"或者……，或者……\" (Câu phức lựa chọn \"或者……，或者……\")","explanation_vn":"Câu phức lựa chọn \"或者……，或者……\" biểu thị việc chọn một trong hai hoặc nhiều khả năng có thể, thường dùng trong khẩu ngữ.","examples":[{"cn":"或者明天去，或者后天去，我给你打电话。","pinyin":"Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vn":""},{"cn":"我们或者今天去电影院看电影，或者明天在家看电影。","pinyin":"Wǒmen huòzhě jīntiān qù diànyǐngyuàn kàn diànyǐng, huòzhě míngtiān zài jiā kàn diànyǐng.","vn":""},{"cn":"晚饭你自己选，或者吃中国菜，或者吃日本菜，或者吃泰国菜。","pinyin":"Wǎnfàn nǐ zìjǐ xuǎn, huòzhě chī Zhōngguó cài, huòzhě chī Rìběn cài, huòzhě chī Tàiguó cài.","vn":""}]},{"title":"趋向补语的引申用法（2）\"起来\" (Cách dùng mở rộng của bổ ngữ xu hướng \"起来\")","explanation_vn":"Bổ ngữ xu hướng \"起来\" dùng sau động từ hoặc tính từ, biểu thị động tác bắt đầu diễn ra hoặc bước vào một trạng thái mới. Nếu động từ có tân ngữ thì tân ngữ phải đặt giữa \"起\" và \"来\".","examples":[{"cn":"雨已经下起来了。","pinyin":"Yǔ yǐjīng xià qǐlái le.","vn":""},{"cn":"最近天气热起来了。","pinyin":"Zuìjìn tiānqì rè qǐlái le.","vn":""},{"cn":"怎么突然刮起风来了？","pinyin":"Zěnme tūrán guā qǐ fēng lái le?","vn":""}]},{"title":"范围副词\"就\" (Phó từ phạm vi \"就\")","explanation_vn":"Phó từ phạm vi \"就\" dùng trước động từ đi kèm số từ - lượng từ, biểu thị người nói cho rằng số lượng ít, mức độ nhẹ, thời gian ngắn. \"就\" cũng được dùng trước danh từ hoặc chủ ngữ danh từ để biểu thị trường hợp ngoại lệ.","examples":[{"cn":"北京常常下雪，但听说今年就下了一次。","pinyin":"Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vn":""},{"cn":"他昨天就看了十分钟书。","pinyin":"Tā zuótiān jiù kànle shí fēnzhōng shū.","vn":""},{"cn":"我每天书包里都放着雨伞，就今天没带。","pinyin":"Wǒ měitiān shūbāo lǐ dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","vn":""},{"cn":"你们点的菜都挺好吃的，就我点的这个菜不太好吃。","pinyin":"Nǐmen diǎn de cài dōu tǐng hǎochī de, jiù wǒ diǎn de zhège cài bú tài hǎochī.","vn":""}]},{"title":"趋向补语的引申用法（3）\"下来\" (Cách dùng mở rộng của bổ ngữ xu hướng \"下来\")","explanation_vn":"Bổ ngữ xu hướng \"下来\" dùng sau động từ, biểu thị việc hoàn thành một hành động tốn thời gian, công sức, cần phải vượt qua khó khăn nhất định.","examples":[{"cn":"这一年多住下来，我还是更喜欢北京的四季。","pinyin":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","vn":""},{"cn":"这半年练下来，他画画的水平提高了不少。","pinyin":"Zhè bànnián liàn xiàlái, tā huàhuà de shuǐpíng tígāole bù shǎo.","vn":""},{"cn":"5000米的长跑比赛，没想到我跑下来了。","pinyin":"Wǔqiān mǐ de chángpǎo bǐsài, méi xiǎngdào wǒ pǎo xiàláile.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"王老师，您看，这条街上的树都开花了。","pinyin":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shàng de shù dōu kāihuā le."},{"speaker":"王一飞","cn":"上周我去公园坐船了，公园里的花也开了。","pinyin":"Shàng zhōu wǒ qù gōngyuán zuò chuán le, gōngyuán lǐ de huā yě kāi le."},{"speaker":"白家月","cn":"天气这么好，下午我也想去公园坐船。","pinyin":"Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuò chuán."},{"speaker":"王一飞","cn":"去吧！今天是工作日，人应该不多。","pinyin":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō."},{"speaker":"白家月","cn":"您有时间吗？我想跟您一起去。","pinyin":"Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù."},{"speaker":"王一飞","cn":"我今天下午有课，不能去太远的地方。","pinyin":"Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang."},{"speaker":"白家月","cn":"那咱们换一天去？","pinyin":"Nà zánmen huàn yì tiān qù?"},{"speaker":"王一飞","cn":"行。或者明天去，或者后天去，我给你打电话。","pinyin":"Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà."}],"translation_vn":"Bạch Gia Nguyệt: Thầy Vương ơi, thầy xem, cây trên con phố này đều nở hoa rồi.\nVương Nhất Phi: Tuần trước tôi đi công viên chèo thuyền, hoa trong công viên cũng nở rồi.\nBạch Gia Nguyệt: Thời tiết đẹp thế này, chiều nay em cũng muốn đi công viên chèo thuyền.\nVương Nhất Phi: Đi đi! Hôm nay là ngày làm việc, chắc không đông người đâu.\nBạch Gia Nguyệt: Thầy có thời gian không ạ? Em muốn đi cùng thầy.\nVương Nhất Phi: Chiều nay tôi có tiết dạy, không thể đi xa được.\nBạch Gia Nguyệt: Vậy chúng ta đổi sang ngày khác đi ạ?\nVương Nhất Phi: Được. Hoặc mai đi, hoặc ngày kia đi, tôi sẽ gọi điện cho em.","audio_dialogue":"12-1.mp3","audio_vocab":"12-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"刚才还是大晴天呢，怎么突然就刮起风来了？","pinyin":"Gāngcái hái shì dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lái le?"},{"speaker":"王一飞","cn":"好像新闻里说今天有雨。","pinyin":"Hǎoxiàng xīnwén lǐ shuō jīntiān yǒu yǔ."},{"speaker":"白家月","cn":"啊？我每天书包里都放着雨伞，就今天没带。","pinyin":"Á? Wǒ měitiān shūbāo lǐ dōu fàngzhe yǔsǎn, jiù jīntiān méi dài."},{"speaker":"王一飞","cn":"我可以借给你，我车里有一把伞和一件雨衣。","pinyin":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē lǐ yǒu yì bǎ sǎn hé yí jiàn yǔyī."},{"speaker":"白家月","cn":"谢谢，希望下午天气能变好。","pinyin":"Xièxie, xīwàng xiàwǔ tiānqì néng biàn hǎo."},{"speaker":"王一飞","cn":"这个季节天气变化很快。","pinyin":"Zhège jìjié tiānqì biànhuà hěn kuài."},{"speaker":"白家月","cn":"雨已经下起来了，咱们快点儿走吧。","pinyin":"Yǔ yǐjīng xià qǐlái le, zánmen kuài diǎnr zǒu ba."}],"translation_vn":"Bạch Gia Nguyệt: Vừa nãy còn nắng to thế mà, sao đột nhiên lại nổi gió lên rồi?\nVương Nhất Phi: Hình như bản tin thời sự nói hôm nay có mưa.\nBạch Gia Nguyệt: Hả? Ngày nào em cũng để sẵn ô trong cặp sách, vậy mà hôm nay lại không mang.\nVương Nhất Phi: Thầy có thể cho em mượn, trong xe thầy có một cái ô và một cái áo mưa.\nBạch Gia Nguyệt: Cảm ơn thầy, em hy vọng chiều nay thời tiết sẽ tốt hơn.\nVương Nhất Phi: Mùa này thời tiết thay đổi rất nhanh.\nBạch Gia Nguyệt: Mưa đã bắt đầu rơi rồi, chúng ta đi nhanh lên thôi.","audio_dialogue":"12-3.mp3","audio_vocab":"12-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"您来这里已经一年多了，习惯了吧？","pinyin":"Nín lái zhèlǐ yǐjīng yì nián duō le, xíguàn le ba?"},{"speaker":"王一飞","cn":"别的早就习惯了，就是天气我还不太习惯。","pinyin":"Biéde zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn."},{"speaker":"白家月","cn":"为什么？您不喜欢这里的天气吗？","pinyin":"Wèishénme? Nín bù xǐhuan zhèlǐ de tiānqì ma?"},{"speaker":"王一飞","cn":"我觉得冬天太冷了。","pinyin":"Wǒ juéde dōngtiān tài lěng le."},{"speaker":"白家月","cn":"冬天虽然冷，但是下雪的时候特别漂亮。","pinyin":"Dōngtiān suīrán lěng, dànshì xià xuě de shíhou tèbié piàoliang."},{"speaker":"王一飞","cn":"我也喜欢雪。北京常常下雪，但听说今年就下了一次。","pinyin":"Wǒ yě xǐhuan xuě. Běijīng chángcháng xià xuě, dàn tīngshuō jīnnián jiù xiàle yí cì."},{"speaker":"白家月","cn":"我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","pinyin":"Wǒ méi guānzhùguò Běijīng de tiānqì, dànshì xīnwén lǐ shuōguò, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le."}],"translation_vn":"Bạch Gia Nguyệt: Thầy đến đây đã hơn một năm rồi, chắc đã quen rồi nhỉ?\nVương Nhất Phi: Những thứ khác thì quen lâu rồi, chỉ có thời tiết là tôi vẫn chưa quen lắm.\nBạch Gia Nguyệt: Tại sao ạ? Thầy không thích thời tiết ở đây sao?\nVương Nhất Phi: Tôi thấy mùa đông ở đây quá lạnh.\nBạch Gia Nguyệt: Mùa đông tuy lạnh nhưng lúc có tuyết rơi thì đẹp lắm.\nVương Nhất Phi: Tôi cũng thích tuyết. Bắc Kinh thường hay có tuyết, nhưng nghe nói năm nay chỉ có tuyết một lần thôi.\nBạch Gia Nguyệt: Em chưa từng để ý đến thời tiết ở Bắc Kinh, nhưng nghe bản tin thời sự nói, mùa đông năm nay tuyết ở nhiều nơi đều rơi ít đi.","audio_dialogue":"12-5.mp3","audio_vocab":"12-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我离开北京到这里工作一年多了。","pinyin":"Wǒ líkāi Běijīng dào zhèlǐ gōngzuò yì nián duō le."},{"speaker":"","cn":"这一年多住下来，我还是更喜欢北京的四季。","pinyin":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì."},{"speaker":"","cn":"北京的春天最舒服，天气不冷不热。","pinyin":"Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bú rè."},{"speaker":"","cn":"夏天白天很热，但是晚上比较凉快。","pinyin":"Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai."},{"speaker":"","cn":"秋天树上的叶子都变成了红色、黄色，非常漂亮。","pinyin":"Qiūtiān shùshàng de yèzi dōu biànchéngle hóngsè, huángsè, fēicháng piàoliang."},{"speaker":"","cn":"冬天不但冷，而且风很大，我最不喜欢冬天。","pinyin":"Dōngtiān búdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān."},{"speaker":"","cn":"每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","pinyin":"Měi gè rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎge jìjié ne?"}],"translation_vn":"Tôi đã rời Bắc Kinh đến đây làm việc được hơn một năm rồi. Sống ở đây hơn một năm, tôi vẫn thích bốn mùa của Bắc Kinh hơn. Mùa xuân ở Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng. Mùa hè ban ngày rất nóng, nhưng buổi tối lại khá mát mẻ. Mùa thu, lá trên cây đều chuyển sang màu đỏ, màu vàng, rất đẹp. Mùa đông không chỉ lạnh mà gió còn rất to, tôi ghét mùa đông nhất. Mỗi người đều có mùa mình yêu thích nhất, bạn thích mùa nào nhất?","audio_dialogue":"12-7.mp3","audio_vocab":"12-8.mp3"}]},{"id":13,"title_cn":"我的新邻居来自英国","title_pinyin":"Wǒ de xīn línjū láizì Yīngguó","title_vn":"Người hàng xóm mới của tôi đến từ Anh","goals":["Có thể nghe hiểu và thảo luận về sự khác biệt trong thói quen sinh hoạt giữa các vùng miền khác nhau.","Có thể nghe hiểu và sử dụng các cách nói lịch sự như cảm ơn, chúc phúc và khen ngợi.","Nắm vững cách dùng \"一边……, 一边……\" để miêu tả các hành động diễn ra đồng thời."],"vocab":[{"hanzi":"请客","pinyin":"qǐngkè","pos":"dgt.","vn":"mời khách, đãi khách"},{"hanzi":"南方","pinyin":"nánfāng","pos":"dt.","vn":"miền Nam"},{"hanzi":"北方","pinyin":"běifāng","pos":"dt.","vn":"miền Bắc"},{"hanzi":"做法","pinyin":"zuòfǎ","pos":"dt.","vn":"cách làm, cách chế biến"},{"hanzi":"不同","pinyin":"bùtóng","pos":"tt.","vn":"khác nhau, không giống"},{"hanzi":"加","pinyin":"jiā","pos":"dgt.","vn":"thêm"},{"hanzi":"的话","pinyin":"dehuà","pos":"trợ.","vn":"nếu... thì (dùng cuối mệnh đề giả thiết)"},{"hanzi":"做客","pinyin":"zuòkè","pos":"dgt.","vn":"làm khách, đến thăm nhà"},{"hanzi":"邻居","pinyin":"línjū","pos":"dt.","vn":"hàng xóm"},{"hanzi":"放心","pinyin":"fàngxīn","pos":"dgt.","vn":"yên tâm"},{"hanzi":"酒","pinyin":"jiǔ","pos":"dt.","vn":"rượu"},{"hanzi":"放","pinyin":"fàng","pos":"dgt.","vn":"đặt, để"},{"hanzi":"客人","pinyin":"kèrén","pos":"dt.","vn":"khách"},{"hanzi":"晚会","pinyin":"wǎnhuì","pos":"dt.","vn":"buổi dạ hội, tiệc tối"},{"hanzi":"礼物","pinyin":"lǐwù","pos":"dt.","vn":"quà tặng"},{"hanzi":"画家","pinyin":"huàjiā","pos":"dt.","vn":"họa sĩ"},{"hanzi":"盘子","pinyin":"pánzi","pos":"dt.","vn":"cái đĩa"},{"hanzi":"一边","pinyin":"yìbiān","pos":"phó.","vn":"vừa... vừa (đồng thời)"},{"hanzi":"聊天儿","pinyin":"liáotiānr","pos":"dgt.","vn":"trò chuyện, tán gẫu"},{"hanzi":"来自","pinyin":"láizì","pos":"dgt.","vn":"đến từ"},{"hanzi":"夫妻","pinyin":"fūqī","pos":"dt.","vn":"vợ chồng"},{"hanzi":"直到","pinyin":"zhídào","pos":"dgt.","vn":"cho đến khi"},{"hanzi":"地图","pinyin":"dìtú","pos":"dt.","vn":"bản đồ"},{"hanzi":"点","pinyin":"diǎn","pos":"dt.","vn":"chấm, điểm"},{"hanzi":"感到","pinyin":"gǎndào","pos":"dgt.","vn":"cảm thấy"},{"hanzi":"东方","pinyin":"dōngfāng","pos":"dt.","vn":"phương Đông"},{"hanzi":"文化","pinyin":"wénhuà","pos":"dt.","vn":"văn hóa"},{"hanzi":"英国","pinyin":"Yīngguó","pos":"danh từ riêng","vn":"nước Anh"}],"grammar":[{"title":"假设复句\"……的话，就……\" - Câu phức giả thiết \"……的话，就……\"","explanation_vn":"Trong câu phức giả thiết \"……的话，就……\", mệnh đề trước nêu ra tình huống giả định, mệnh đề sau nêu kết quả hoặc kết luận được rút ra; cấu trúc này chủ yếu dùng trong khẩu ngữ.","examples":[{"cn":"你们有时间的话，就来我家做客。","pinyin":"Nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè.","vn":""},{"cn":"你觉得满意的话，咱们就买。","pinyin":"Nǐ juéde mǎnyì dehuà, zánmen jiù mǎi.","vn":""},{"cn":"明天天气好的话，我就去爬山。","pinyin":"Míngtiān tiānqì hǎo dehuà, wǒ jiù qù pá shān.","vn":""}]},{"title":"\"把\"字句（4） - Câu chữ \"把\" (4)","explanation_vn":"Trong câu chữ \"把\", sau động từ sử dụng bổ ngữ xu hướng hoặc bổ ngữ trạng thái, biểu thị động tác làm cho người hoặc sự vật xác định có sự thay đổi về vị trí hoặc trạng thái. Cấu trúc cơ bản: Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ xu hướng/trạng thái.","examples":[{"cn":"你把声音开得太大了。","pinyin":"Nǐ bǎ shēngyīn kāi de tài dà le.","vn":""},{"cn":"他把球踢进去了吗？","pinyin":"Tā bǎ qiú tī jìnqù le ma?","vn":""},{"cn":"你把字写得太小了，我看不清楚。","pinyin":"Nǐ bǎ zì xiě de tài xiǎo le, wǒ kàn bù qīngchǔ.","vn":""}]},{"title":"并列复句\"一边……，一边……\" - Câu phức song song \"一边……，一边……\"","explanation_vn":"Câu phức song song \"一边……，一边……\" biểu thị hai hành động diễn ra đồng thời, có thể rút gọn thành \"边……边……\".","examples":[{"cn":"咱们一边吃蛋糕，一边聊天儿吧。","pinyin":"Zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vn":""},{"cn":"我喜欢一边跑步，一边听音乐。","pinyin":"Wǒ xǐhuan yìbiān pǎobù, yìbiān tīng yīnyuè.","vn":""},{"cn":"你不应该边开车边打电话。","pinyin":"Nǐ bù yīnggāi biān kāichē biān dǎ diànhuà.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"今天我请客，你们想吃什么就点什么！","pinyin":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!"},{"speaker":"王一雪","cn":"那我就不客气了。听说这家饭馆的鱼做得很特别？","pinyin":"Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?"},{"speaker":"杨同乐","cn":"对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","pinyin":"Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bùtóng. Chúle yú, nǐmen hái xiǎng chī shénme?"},{"speaker":"同事","cn":"我不常吃南方菜，还是你决定吧。","pinyin":"Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba."},{"speaker":"杨同乐","cn":"好，那再加一个鸡肉，一个……","pinyin":"Hǎo, nà zài jiā yí gè jīròu, yí gè……"},{"speaker":"王一雪","cn":"咱们就三个人，别点那么多。","pinyin":"Zánmen jiù sān gè rén, bié diǎn nàme duō."},{"speaker":"杨同乐","cn":"好，那先来这几个菜。","pinyin":"Hǎo, nà xiān lái zhè jǐ gè cài."},{"speaker":"王一雪","cn":"对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","pinyin":"Duìle, xiàzhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài."}],"translation_vn":"Dương Đồng Nhạc: Hôm nay tôi mời khách, các bạn muốn ăn gì thì cứ gọi!\nVương Nhất Tuyết: Vậy thì tôi không khách sáo nữa. Nghe nói món cá ở nhà hàng này làm rất đặc biệt?\nDương Đồng Nhạc: Đúng vậy, món ăn miền Nam có cách chế biến khác với món ăn miền Bắc của các bạn. Ngoài cá ra, các bạn còn muốn ăn gì nữa?\nĐồng nghiệp: Tôi không thường ăn món miền Nam, cứ để anh quyết định đi.\nDương Đồng Nhạc: Được, vậy gọi thêm một món thịt gà, một...\nVương Nhất Tuyết: Chúng ta chỉ có ba người thôi, đừng gọi nhiều quá.\nDương Đồng Nhạc: Được, vậy trước tiên cứ mang mấy món này lên.\nVương Nhất Tuyết: Đúng rồi, tuần sau con trai tôi sinh nhật, nếu các bạn có thời gian thì đến nhà tôi chơi, tôi sẽ làm món Bắc Kinh cho các bạn.","audio_dialogue":"13-1.mp3","audio_vocab":"13-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"第一次请新邻居来做客，总是担心有什么没准备好。","pinyin":"Dì yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo."},{"speaker":"刘明","cn":"放心吧，我帮你看了，都已经准备好了。","pinyin":"Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le."},{"speaker":"王一雪","cn":"我记得刚才已经把饮料拿出来了，怎么不见了？","pinyin":"Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlái le, zěnme bú jiàn le?"},{"speaker":"刘明","cn":"我把饮料和酒都放进冰箱里了，客人来了再拿出来。","pinyin":"Wǒ bǎ yǐnliào hé jiǔ dōu fàng jìn bīngxiāng lǐ le, kèrén lái le zài ná chūlái."},{"speaker":"王一雪","cn":"音乐的声音合适吗？","pinyin":"Yīnyuè de shēngyīn héshì ma?"},{"speaker":"刘明","cn":"你把声音开得太大了，我去关小一点儿。","pinyin":"Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr."},{"speaker":"王一雪","cn":"好，那我们就等客人来吧。","pinyin":"Hǎo, nà wǒmen jiù děng kèrén lái ba."}],"translation_vn":"Vương Nhất Tuyết: Lần đầu tiên mời hàng xóm mới đến chơi, cứ lo lắng không biết có chuẩn bị thiếu gì không.\nLưu Minh: Yên tâm đi, anh đã kiểm tra giúp em rồi, mọi thứ đều đã chuẩn bị xong cả rồi.\nVương Nhất Tuyết: Em nhớ là vừa nãy đã lấy đồ uống ra rồi, sao giờ không thấy nữa?\nLưu Minh: Anh đã cất đồ uống và rượu vào tủ lạnh rồi, đợi khách đến thì lấy ra sau.\nVương Nhất Tuyết: Âm lượng nhạc như vậy có phù hợp không?\nLưu Minh: Em mở to quá rồi, để anh đi vặn nhỏ lại một chút.\nVương Nhất Tuyết: Được rồi, vậy chúng ta cứ đợi khách đến thôi.","audio_dialogue":"13-3.mp3","audio_vocab":"13-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","pinyin":"Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn."},{"speaker":"杨同乐","cn":"小明，生日快乐！我准备了一个小礼物，希望你喜欢！","pinyin":"Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèi le yí gè xiǎo lǐwù, xīwàng nǐ xǐhuan!"},{"speaker":"刘小明","cn":"谢谢您，我可以打开吗？","pinyin":"Xièxie nín, wǒ kěyǐ dǎkāi ma?"},{"speaker":"杨同乐","cn":"当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","pinyin":"Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huàhuà, duì ma?"},{"speaker":"刘小明","cn":"对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","pinyin":"Duì, wǒ xiǎng zuò yì míng huàjiā. À! Huàbǎn hé huàbǐ, zhè zhèng shì wǒ xūyào de. Wǒ tài xǐhuan le."},{"speaker":"王一雪","cn":"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","pinyin":"Wǒ qù bǎ pánzi ná guòlái, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba."}],"translation_vn":"Vương Nhất Tuyết: Cảm ơn mọi người đã đến dự tiệc sinh nhật của con trai tôi, mong mọi người tối nay chơi vui vẻ.\nDương Đồng Nhạc: Tiểu Minh, chúc mừng sinh nhật! Chú đã chuẩn bị một món quà nhỏ, mong cháu thích nhé!\nLưu Tiểu Minh: Cháu cảm ơn chú, cháu mở ra được không ạ?\nDương Đồng Nhạc: Đương nhiên được, mẹ cháu nói cháu giống chị gái, đều thích vẽ tranh, đúng không?\nLưu Tiểu Minh: Đúng ạ, cháu muốn trở thành một họa sĩ. A! Bảng vẽ và bút vẽ, đây đúng là thứ cháu cần. Cháu thích quá.\nVương Nhất Tuyết: Mẹ đi lấy đĩa đây, chúng ta vừa ăn bánh vừa trò chuyện nhé.","audio_dialogue":"13-5.mp3","audio_vocab":"13-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我的新邻居是来自英国的夫妻。","pinyin":"Wǒ de xīn línjū shì láizì Yīngguó de fūqī."},{"speaker":"","cn":"上周我去他们家做客了。","pinyin":"Shàng zhōu wǒ qù tāmen jiā zuòkè le."},{"speaker":"","cn":"他们做了很多好吃的，还准备了英国的红茶。","pinyin":"Tāmen zuò le hěn duō hǎochī de, hái zhǔnbèi le Yīngguó de hóngchá."},{"speaker":"","cn":"那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。","pinyin":"Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí'èr diǎn duō cái huí jiā."},{"speaker":"","cn":"他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。","pinyin":"Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmiàn měi yí gè hóngdiǎn dōu shì tāmen qù guò de dìfāng."},{"speaker":"","cn":"后来，他们感到东方的文化很特别，就开始学习中文。","pinyin":"Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén."},{"speaker":"","cn":"今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","pinyin":"Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguórén de jiā, yě chángchang Zhōngguó cài."}],"translation_vn":"Hàng xóm mới của tôi là một cặp vợ chồng đến từ nước Anh. Tuần trước tôi đã đến nhà họ chơi. Họ đã làm rất nhiều món ngon, còn chuẩn bị cả trà đen của Anh. Hôm đó tôi vừa uống trà đen với họ vừa trò chuyện, mãi đến hơn mười hai giờ mới về nhà. Lúc còn trẻ họ rất thích đi du lịch, nhà họ có một tấm bản đồ thế giới, trên đó mỗi một chấm đỏ đều là nơi họ đã từng đến. Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt, nên bắt đầu học tiếng Trung. Hôm nay là sinh nhật của Tiểu Minh, tôi mời họ đến nhà tôi chơi, để xem nhà của người Trung Quốc như thế nào, và cũng để nếm thử món ăn Trung Quốc.","audio_dialogue":"13-7.mp3","audio_vocab":"13-8.mp3"}]},{"id":14,"title_cn":"这本书被别人借走了","title_pinyin":"Zhè běn shū bèi biérén jiè zǒu le","title_vn":"Cuốn sách này đã bị người khác mượn mất rồi","goals":["Có thể nghe hiểu và giới thiệu về các hoạt động trong khuôn viên trường học.","Có thể nghe hiểu và bày tỏ sự động viên, khích lệ đối với người khác.","Nắm vững cách dùng câu bị động (1) để biểu đạt ý nghĩa bị động."],"vocab":[{"hanzi":"词典","pinyin":"cídiǎn","pos":"dt.","vn":"từ điển"},{"hanzi":"最好","pinyin":"zuìhǎo","pos":"phó.","vn":"tốt nhất nên"},{"hanzi":"节","pinyin":"jié","pos":"lượng.","vn":"tiết (buổi học)"},{"hanzi":"图书馆","pinyin":"túshūguǎn","pos":"dt.","vn":"thư viện"},{"hanzi":"被","pinyin":"bèi","pos":"giới.","vn":"bị (dùng biểu thị ý bị động)"},{"hanzi":"名人","pinyin":"míngrén","pos":"dt.","vn":"người nổi tiếng"},{"hanzi":"故事","pinyin":"gùshi","pos":"dt.","vn":"câu chuyện"},{"hanzi":"然后","pinyin":"ránhòu","pos":"liên.","vn":"sau đó"},{"hanzi":"报纸","pinyin":"bàozhǐ","pos":"dt.","vn":"báo"},{"hanzi":"忘记","pinyin":"wàngjì","pos":"dgt.","vn":"quên"},{"hanzi":"电子书","pinyin":"diànzǐshū","pos":"dt.","vn":"sách điện tử"},{"hanzi":"女生","pinyin":"nǚshēng","pos":"dt.","vn":"nữ sinh"},{"hanzi":"表演","pinyin":"biǎoyǎn","pos":"dgt.","vn":"biểu diễn"},{"hanzi":"节目","pinyin":"jiémù","pos":"dt.","vn":"tiết mục"},{"hanzi":"怎么办","pinyin":"zěnme bàn","pos":"","vn":"phải làm sao, làm thế nào"},{"hanzi":"校长","pinyin":"xiàozhǎng","pos":"dt.","vn":"hiệu trưởng"},{"hanzi":"面前","pinyin":"miànqián","pos":"dt.","vn":"trước mặt"},{"hanzi":"有些","pinyin":"yǒuxiē","pos":"phó.","vn":"hơi, có chút"},{"hanzi":"相信","pinyin":"xiāngxìn","pos":"dgt.","vn":"tin tưởng"},{"hanzi":"新年","pinyin":"xīnnián","pos":"dt.","vn":"năm mới"},{"hanzi":"班级","pinyin":"bānjí","pos":"dt.","vn":"lớp học (các lớp)"},{"hanzi":"跳","pinyin":"tiào","pos":"dgt.","vn":"nhảy"},{"hanzi":"留学生","pinyin":"liúxuéshēng","pos":"dt.","vn":"du học sinh"},{"hanzi":"最后","pinyin":"zuìhòu","pos":"dt.","vn":"cuối cùng"},{"hanzi":"一块儿","pinyin":"yíkuàir","pos":"phó.","vn":"cùng nhau"},{"hanzi":"网站","pinyin":"wǎngzhàn","pos":"dt.","vn":"trang web"},{"hanzi":"视频","pinyin":"shìpín","pos":"dt.","vn":"video"}],"grammar":[{"title":"被动句（1） - Câu bị động (1)","explanation_vn":"Trong tiếng Hán, câu có chữ \"被\" biểu đạt ý nghĩa bị động, nhấn mạnh chủ ngữ chịu ảnh hưởng của một động tác nào đó, thường mang sắc thái bị động, bất đắc dĩ hoặc tiêu cực. Phó từ và động từ năng nguyện đặt trước chữ \"被\", tân ngữ sau chữ \"被\" có thể lược bỏ. Cấu trúc cơ bản: Chủ ngữ + 被 + Tân ngữ + Động từ + Thành phần khác.","examples":[{"cn":"这本书被别人借走了。","pinyin":"Zhè běn shū bèi biérén jiè zǒu le.","vn":""},{"cn":"水果可能被弟弟吃了。","pinyin":"Shuǐguǒ kěnéng bèi dìdi chī le.","vn":""},{"cn":"我们俩经常被叫错名字。","pinyin":"Wǒmen liǎ jīngcháng bèi jiào cuò míngzi.","vn":""}]},{"title":"承接复句\"先……，再/然后……\" - Câu phức tiếp nối \"先……，再/然后……\"","explanation_vn":"Trong câu phức tiếp nối \"先……，再/然后……\", hai mệnh đề biểu thị trình tự trước sau của các hành động.","examples":[{"cn":"我要先去图书馆借书，然后去游泳。","pinyin":"Wǒ yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vn":""},{"cn":"你先去买门票，再来这里找我。","pinyin":"Nǐ xiān qù mǎi ménpiào, zài lái zhèlǐ zhǎo wǒ.","vn":""},{"cn":"你们先回房间休息一会儿，然后再出来吃晚饭。","pinyin":"Nǐmen xiān huí fángjiān xiūxi yíhuìr, ránhòu zài chūlái chī wǎnfàn.","vn":""}]},{"title":"固定格式\"×什么（啊）\" - Cấu trúc cố định \"×什么（啊）\"","explanation_vn":"Cấu trúc cố định \"×什么（啊）\" thường dùng để phủ nhận sự lo lắng, nghi ngờ của đối phương hoặc nhấn mạnh một sự thật, mang giọng điệu phản bác hoặc an ủi.","examples":[{"cn":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","vn":""},{"cn":"胖什么啊，你看起来不胖也不瘦。","pinyin":"Pàng shénme a, nǐ kànqǐlái bú pàng yě bú shòu.","vn":""},{"cn":"急什么啊，马上就到了。","pinyin":"Jí shénme a, mǎshàng jiù dào le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"我借的这本词典最好今天还，但是我没时间去。","pinyin":"Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù."},{"speaker":"白家月","cn":"下午我只有两节课，可以帮你去图书馆还书。","pinyin":"Xiàwǔ wǒ zhǐyǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū."},{"speaker":"李文","cn":"那太谢谢了。你能再帮我借本书吗？","pinyin":"Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?"},{"speaker":"白家月","cn":"行，你告诉我书名。","pinyin":"Xíng, nǐ gàosu wǒ shūmíng."},{"speaker":"李文","cn":"我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","pinyin":"Wǒ bǎ míngzi xiě zài zhǐ shàng ba. Wǒ qù le hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jiè zǒu le."},{"speaker":"白家月","cn":"《名人的故事》？我有这本书。明天我借给你吧。","pinyin":"《Míngrén de Gùshi》? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba."}],"translation_vn":"Lý Văn: Cuốn từ điển mình mượn tốt nhất nên trả hôm nay, nhưng mình không có thời gian đi.\nBạch Gia Nguyệt: Chiều nay mình chỉ có hai tiết học, có thể giúp bạn đi trả sách ở thư viện.\nLý Văn: Vậy cảm ơn bạn nhiều lắm. Bạn có thể giúp mình mượn thêm một cuốn sách nữa được không?\nBạch Gia Nguyệt: Được, bạn cho mình biết tên sách đi.\nLý Văn: Để mình viết tên sách ra giấy nhé. Mình đã đến thư viện mấy lần rồi, cuốn sách này đều đã bị người khác mượn mất.\nBạch Gia Nguyệt: \"Câu chuyện về những người nổi tiếng\"? Mình có cuốn này. Ngày mai mình cho bạn mượn nhé.","audio_dialogue":"14-1.mp3","audio_vocab":"14-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"今天下课早，你一会儿做什么？","pinyin":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?"},{"speaker":"白家月","cn":"我今天忙得很，要先去图书馆借书，然后去游泳。","pinyin":"Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng."},{"speaker":"安妮","cn":"咱们一起走吧，我想去图书馆看看中文报纸。","pinyin":"Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ."},{"speaker":"白家月","cn":"等等，我的校园卡不见了，没有卡进不去图书馆。","pinyin":"Děngděng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn."},{"speaker":"安妮","cn":"你想想上一次用是什么时候？","pinyin":"Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?"},{"speaker":"白家月","cn":"我忘记了，可能被我放在家里了。","pinyin":"Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiā lǐ le."},{"speaker":"安妮","cn":"进不去图书馆也没关系，上网看看有没有电子书。","pinyin":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū."},{"speaker":"白家月","cn":"不行，我必须去，我还得帮李文还书呢。","pinyin":"Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne."}],"translation_vn":"Annie: Hôm nay tan học sớm, lát nữa bạn làm gì?\nBạch Gia Nguyệt: Hôm nay mình bận lắm, phải đi thư viện mượn sách trước, sau đó đi bơi.\nAnnie: Chúng ta cùng đi nhé, mình muốn đến thư viện xem báo tiếng Trung.\nBạch Gia Nguyệt: Khoan đã, thẻ sinh viên của mình không thấy đâu rồi, không có thẻ thì không vào thư viện được.\nAnnie: Bạn thử nghĩ xem lần trước dùng là khi nào?\nBạch Gia Nguyệt: Mình quên mất rồi, có thể đã bị mình để quên ở nhà.\nAnnie: Không vào được thư viện cũng không sao, lên mạng xem có sách điện tử không.\nBạch Gia Nguyệt: Không được, mình nhất định phải đi, mình còn phải giúp Lý Văn trả sách nữa.","audio_dialogue":"14-3.mp3","audio_vocab":"14-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"李文","cn":"下周学校有晚会，你知道吗？","pinyin":"Xiàzhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?"},{"speaker":"白家月","cn":"知道，我和几个女生要表演一个节目。你也参加吗？","pinyin":"Zhīdào, wǒ hé jǐ gè nǚshēng yào biǎoyǎn yí gè jiémù. Nǐ yě cānjiā ma?"},{"speaker":"李文","cn":"我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","pinyin":"Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn."},{"speaker":"白家月","cn":"找不到人，你就一个人唱吧。","pinyin":"Zhǎo bu dào rén, nǐ jiù yí gè rén chàng ba."},{"speaker":"李文","cn":"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","pinyin":"Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng."},{"speaker":"白家月","cn":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ."}],"translation_vn":"Lý Văn: Tuần sau trường có tổ chức dạ hội, bạn biết chưa?\nBạch Gia Nguyệt: Biết rồi, mình và vài bạn nữ sẽ biểu diễn một tiết mục. Bạn cũng tham gia à?\nLý Văn: Mình muốn hát một bài tiếng Trung, nhưng vẫn chưa tìm được người biểu diễn cùng, không biết phải làm sao.\nBạch Gia Nguyệt: Không tìm được người thì bạn cứ hát một mình đi.\nLý Văn: Hễ nghĩ đến việc phải biểu diễn trước mặt hiệu trưởng, thầy cô và bao nhiêu bạn học là mình lại thấy hơi hồi hộp.\nBạch Gia Nguyệt: Hồi hộp gì chứ, chúng mình đều thích nghe bạn hát, bạn phải tin vào bản thân mình.","audio_dialogue":"14-5.mp3","audio_vocab":"14-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"昨天是我们学校的新年晚会，每个班级的同学都表演节目了。","pinyin":"Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi gè bānjí de tóngxué dōu biǎoyǎn jiémù le."},{"speaker":"","cn":"晚会是八点开始的，差不多十二点才结束。","pinyin":"Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí'èr diǎn cái jiéshù."},{"speaker":"","cn":"我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。","pinyin":"Wǒ yí gè wǎnshàng gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jí le, yě lèi huài le."},{"speaker":"","cn":"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。","pinyin":"Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlái yíkuàir tiào, tèbié yǒu yìsi."},{"speaker":"","cn":"过几天学校的网站上会有晚会的视频，我打算再看一遍。","pinyin":"Guò jǐ tiān xuéxiào de wǎngzhàn shàng huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn."}],"translation_vn":"Hôm qua là buổi dạ hội mừng năm mới của trường chúng tôi, các bạn học sinh mỗi lớp đều biểu diễn tiết mục. Buổi dạ hội bắt đầu lúc tám giờ, gần mười hai giờ mới kết thúc. Cả buổi tối tôi cùng mọi người vừa hát vừa nhảy, vui vô cùng, cũng mệt lử luôn. Tiết mục tôi thích nhất là các du học sinh nhảy múa, cuối cùng thầy cô và hiệu trưởng cũng bị gọi lên nhảy cùng, thật là thú vị. Vài hôm nữa trên trang web của trường sẽ có video buổi dạ hội, tôi định xem lại một lần nữa.","audio_dialogue":"14-7.mp3","audio_vocab":"14-8.mp3"}]},{"id":15,"title_cn":"我是半个南京人","title_pinyin":"Wǒ shì bàn gè Nánjīngrén","title_vn":"Tôi coi như nửa người Nam Kinh","goals":["Có thể nghe hiểu và miêu tả vị trí cũng như thông tin môi trường xung quanh của một địa điểm.","Có thể nghe hiểu và giới thiệu về cảnh quan thiên nhiên hoặc lịch sử văn hóa của một địa điểm.","Nắm vững cụm từ \"在……看来\" để biểu đạt quan điểm của cá nhân hoặc một nhóm người.","Tìm hiểu những thông tin cơ bản về Nam Kinh và sông Hoàng Hà."],"vocab":[{"hanzi":"蓝","pinyin":"lán","pos":"tt.","vn":"xanh lam"},{"hanzi":"段","pinyin":"duàn","pos":"lượng.","vn":"đoạn (quãng thời gian hoặc quãng đường)"},{"hanzi":"附近","pinyin":"fùjìn","pos":"dt.","vn":"gần đó, lân cận"},{"hanzi":"马路","pinyin":"mǎlù","pos":"dt.","vn":"đường phố, đường cái"},{"hanzi":"平时","pinyin":"píngshí","pos":"dt.","vn":"lúc bình thường"},{"hanzi":"放学","pinyin":"fàngxué","pos":"dgt.","vn":"tan học"},{"hanzi":"游戏","pinyin":"yóuxì","pos":"dt.","vn":"trò chơi"},{"hanzi":"老人","pinyin":"lǎorén","pos":"dt.","vn":"người già"},{"hanzi":"根据","pinyin":"gēnjù","pos":"giới.","vn":"căn cứ vào, dựa vào"},{"hanzi":"了解","pinyin":"liǎojiě","pos":"dgt.","vn":"hiểu, tìm hiểu"},{"hanzi":"可是","pinyin":"kěshì","pos":"liên.","vn":"nhưng, tuy nhiên"},{"hanzi":"以上","pinyin":"yǐshàng","pos":"dt.","vn":"trở lên"},{"hanzi":"有名","pinyin":"yǒumíng","pos":"tt.","vn":"nổi tiếng"},{"hanzi":"景点","pinyin":"jǐngdiǎn","pos":"dt.","vn":"điểm tham quan, thắng cảnh"},{"hanzi":"游客","pinyin":"yóukè","pos":"dt.","vn":"du khách"},{"hanzi":"外地","pinyin":"wàidì","pos":"dt.","vn":"nơi khác, tỉnh ngoài"},{"hanzi":"聊","pinyin":"liáo","pos":"dgt.","vn":"trò chuyện"},{"hanzi":"南京","pinyin":"Nánjīng","pos":"danh từ riêng","vn":"Nam Kinh"},{"hanzi":"河","pinyin":"hé","pos":"dt.","vn":"sông"},{"hanzi":"关系","pinyin":"guānxì","pos":"dt.","vn":"quan hệ, liên quan"},{"hanzi":"养","pinyin":"yǎng","pos":"dgt.","vn":"nuôi"},{"hanzi":"黄河","pinyin":"Huáng Hé","pos":"danh từ riêng","vn":"sông Hoàng Hà"},{"hanzi":"西北","pinyin":"xīběi","pos":"dt.","vn":"tây bắc"},{"hanzi":"经过","pinyin":"jīngguò","pos":"dgt.","vn":"đi qua, trải qua"},{"hanzi":"草地","pinyin":"cǎodì","pos":"dt.","vn":"bãi cỏ"},{"hanzi":"遇见","pinyin":"yùjiàn","pos":"dgt.","vn":"gặp gỡ, gặp"}],"grammar":[{"title":"介词\"根据\" - Giới từ \"根据\"","explanation_vn":"Giới từ \"根据\" dùng trong câu để đưa ra căn cứ hoặc lý do của sự việc.","examples":[{"cn":"这几年小区根据他们的需要，有了很多变化。","pinyin":"Zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà.","vn":""},{"cn":"根据要求，我们必须参加明天的会议。","pinyin":"Gēnjù yāoqiú, wǒmen bìxū cānjiā míngtiān de huìyì.","vn":""},{"cn":"老师根据每个学生的兴趣，选择了不一样的书。","pinyin":"Lǎoshī gēnjù měi gè xuéshēng de xìngqù, xuǎnzé le bù yíyàng de shū.","vn":""}]},{"title":"数量重叠\"数词+量词+数词+量词\" - Dạng láy số lượng từ \"Số từ + Lượng từ + Số từ + Lượng từ\"","explanation_vn":"Cụm số lượng từ có thể láy lại, sau khi láy có thể làm trạng ngữ, thường biểu thị phương thức của động tác, có tác dụng miêu tả sinh động. Cấu trúc cơ bản: Số từ+Lượng từ+Số từ+Lượng từ+(地)+Động từ.","examples":[{"cn":"我得一点儿一点儿给您讲。","pinyin":"Wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vn":""},{"cn":"学生们的汉语水平一天一天地提高了。","pinyin":"Xuéshēngmen de Hànyǔ shuǐpíng yì tiān yì tiān de tígāo le.","vn":""},{"cn":"他们两个两个地走进去了。","pinyin":"Tāmen liǎng gè liǎng gè de zǒu jìnqù le.","vn":""}]},{"title":"固定短语\"在……看来\" - Cụm cố định \"在……看来\"","explanation_vn":"Cụm cố định \"在……看来\" dùng để biểu đạt quan điểm của một cá nhân hoặc một nhóm người.","examples":[{"cn":"在我们中国人看来，黄河像妈妈一样，养了我们几千年。","pinyin":"Zài wǒmen Zhōngguórén kàn lái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián.","vn":""},{"cn":"在同事们看来，她工作非常认真。","pinyin":"Zài tóngshìmen kàn lái, tā gōngzuò fēicháng rènzhēn.","vn":""},{"cn":"在我看来，每天读书是一种很好的习惯。","pinyin":"Zài wǒ kàn lái, měitiān dúshū shì yì zhǒng hěn hǎo de xíguàn.","vn":""}]},{"title":"固定短语\"不一会儿\" - Cụm cố định \"不一会儿\"","explanation_vn":"Cụm cố định \"不一会儿\" biểu thị khoảng thời gian rất ngắn, trong câu làm trạng ngữ, thường dùng trong khẩu ngữ.","examples":[{"cn":"难过的事情不一会儿就忘了。","pinyin":"Nánguò de shìqing bù yíhuìr jiù wàng le.","vn":""},{"cn":"不一会儿，张校长就来了。","pinyin":"Bù yíhuìr, Zhāng xiàozhǎng jiù lái le.","vn":""},{"cn":"两个小时看起来长，但是不一会儿就过去了。","pinyin":"Liǎng ge xiǎoshí kànqǐlái cháng, dànshì bù yíhuìr jiù guòqù le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"您搬到蓝天小区一段时间了，觉得怎么样？","pinyin":"Nín bān dào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?"},{"speaker":"王一雪","cn":"小区环境挺好的，附近买东西也很方便，过马路就是超市。","pinyin":"Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiù shì chāoshì."},{"speaker":"杨同乐","cn":"平时孩子们在哪儿玩？","pinyin":"Píngshí háizimen zài nǎr wán?"},{"speaker":"王一雪","cn":"小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","pinyin":"Xiǎoqū lǐ yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?"},{"speaker":"杨同乐","cn":"是。我想买一个大房子，让我爸妈过来跟我一起住。","pinyin":"Shì. Wǒ xiǎng mǎi yí gè dà fángzi, ràng wǒ bàmā guòlái gēn wǒ yìqǐ zhù."},{"speaker":"王一雪","cn":"蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","pinyin":"Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà."},{"speaker":"杨同乐","cn":"真不错！过几天我去蓝天小区看看。","pinyin":"Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan."}],"translation_vn":"Dương Đồng Nhạc: Chị chuyển đến khu Lam Thiên được một thời gian rồi, chị thấy thế nào?\nVương Nhất Tuyết: Môi trường khu này khá tốt, gần đó mua đồ cũng rất tiện, qua đường là đến siêu thị luôn.\nDương Đồng Nhạc: Bình thường bọn trẻ chơi ở đâu?\nVương Nhất Tuyết: Trong khu có rất nhiều cây, sau khi tan học bọn trẻ liền chơi trò chơi dưới gốc cây. Anh muốn mua nhà à?\nDương Đồng Nhạc: Đúng vậy. Tôi muốn mua một căn nhà lớn, để bố mẹ tôi chuyển đến ở cùng tôi.\nVương Nhất Tuyết: Khu Lam Thiên có khá nhiều người già, mấy năm nay khu này đã căn cứ vào nhu cầu của họ mà có nhiều thay đổi.\nDương Đồng Nhạc: Thật tốt quá! Vài hôm nữa tôi sẽ đến khu Lam Thiên xem thử.","audio_dialogue":"15-1.mp3","audio_vocab":"15-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"假期我想去南京旅游，但是我不太了解那里。","pinyin":"Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàlǐ."},{"speaker":"杨同乐","cn":"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","pinyin":"Wǒ suīrán bú shì Nánjīngrén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn gè Nánjīngrén."},{"speaker":"王一雪","cn":"太好了！你快给我介绍一下南京吧。","pinyin":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba."},{"speaker":"杨同乐","cn":"南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","pinyin":"Nánjīng yǒu liǎng qiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měi nián qù lǚyóu de yóukè tèbié duō."},{"speaker":"王一雪","cn":"除了这些以外，你再告诉我一些外地人不知道的地方。","pinyin":"Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidìrén bù zhīdào de dìfāng."},{"speaker":"杨同乐","cn":"那太多了，我得一点儿一点儿给您讲。","pinyin":"Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng."},{"speaker":"王一雪","cn":"行，下班后我请你吃晚饭，咱们边吃边聊。","pinyin":"Xíng, xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo."}],"translation_vn":"Vương Nhất Tuyết: Kỳ nghỉ này tôi muốn đi Nam Kinh du lịch, nhưng tôi không hiểu rõ về nơi đó lắm.\nDương Đồng Nhạc: Tôi tuy không phải người Nam Kinh, nhưng tôi học đại học ở Nam Kinh, có thể nói là coi như nửa người Nam Kinh rồi.\nVương Nhất Tuyết: Tuyệt quá! Anh mau giới thiệu cho tôi về Nam Kinh đi.\nDương Đồng Nhạc: Nam Kinh có lịch sử hơn hai nghìn năm, có thành cổ, phố cổ, còn có rất nhiều điểm tham quan nổi tiếng, mỗi năm du khách đến du lịch rất đông.\nVương Nhất Tuyết: Ngoài những điều đó ra, anh nói cho tôi biết thêm vài nơi mà người ở tỉnh khác không biết đến.\nDương Đồng Nhạc: Vậy thì nhiều lắm, tôi phải kể cho chị từ từ từng chút một.\nVương Nhất Tuyết: Được, tan làm tôi mời anh ăn tối, chúng ta vừa ăn vừa nói chuyện.","audio_dialogue":"15-3.mp3","audio_vocab":"15-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","pinyin":"Xiǎomíng, Zhōngguó yǒu yì tiáo dà hé, tā de míngzi gēn yánsè yǒu guānxì, nǐ zhīdào shì shénme hé ma?"},{"speaker":"刘小明","cn":"我知道，是黄河！","pinyin":"Wǒ zhīdào, shì Huáng Hé!"},{"speaker":"王一雪","cn":"你说对了。我再问问你，你知道它为什么叫黄河吗？","pinyin":"Nǐ shuō duì le. Wǒ zài wènwèn nǐ, nǐ zhīdào tā wèishénme jiào Huáng Hé ma?"},{"speaker":"刘小明","cn":"因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","pinyin":"Yīnwèi héshuǐ kànqǐlái shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?"},{"speaker":"王一雪","cn":"不是。黄河虽然不是最长的，可是在历史上很重要。","pinyin":"Bú shì. Huáng Hé suīrán bú shì zuì cháng de, kěshì zài lìshǐ shàng hěn zhòngyào."},{"speaker":"刘小明","cn":"这个我知道。很久以前，很多中国人都住在黄河边上。","pinyin":"Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguórén dōu zhù zài Huáng Hé biān shàng."},{"speaker":"王一雪","cn":"对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","pinyin":"Duì. Zài wǒmen Zhōngguórén kàn lái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián."}],"translation_vn":"Vương Nhất Tuyết: Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó có liên quan đến màu sắc, con có biết đó là sông gì không?\nLưu Tiểu Minh: Con biết, là sông Hoàng Hà!\nVương Nhất Tuyết: Con nói đúng rồi. Mẹ hỏi thêm con nhé, con có biết tại sao nó lại gọi là Hoàng Hà không?\nLưu Tiểu Minh: Vì nhìn nước sông có màu vàng, nên mới gọi tên như vậy. Hoàng Hà có phải là con sông dài nhất Trung Quốc không ạ?\nVương Nhất Tuyết: Không phải. Hoàng Hà tuy không phải là con sông dài nhất, nhưng rất quan trọng trong lịch sử.\nLưu Tiểu Minh: Cái này con biết. Rất lâu trước đây, rất nhiều người Trung Quốc đều sống ở ven sông Hoàng Hà.\nVương Nhất Tuyết: Đúng vậy. Trong mắt người Trung Quốc chúng ta, sông Hoàng Hà giống như người mẹ, đã nuôi dưỡng chúng ta mấy nghìn năm nay.","audio_dialogue":"15-5.mp3","audio_vocab":"15-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我小时候住在北京的西北边，有一条非常有名的河经过那里。","pinyin":"Wǒ xiǎoshíhou zhù zài Běijīng de xīběi biān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàlǐ."},{"speaker":"","cn":"我家就住在河边。","pinyin":"Wǒ jiā jiù zhù zài hébiān."},{"speaker":"","cn":"那里有高高的大树和绿绿的草地。","pinyin":"Nàlǐ yǒu gāogāo de dàshù hé lǜlǜ de cǎodì."},{"speaker":"","cn":"春天，河边的花都开了，看起来特别漂亮。","pinyin":"Chūntiān, hébiān de huā dōu kāi le, kànqǐlái tèbié piàoliang."},{"speaker":"","cn":"还记得小时候，一到夏天我就去河里游泳。","pinyin":"Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé lǐ yóuyǒng."},{"speaker":"","cn":"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。","pinyin":"Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hébiān de shù xià zuò zhe, tīngting niǎojiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáoliao tiānr, nánguò de shìqing bù yíhuìr jiù wàng le."},{"speaker":"","cn":"那是我最喜欢的地方。","pinyin":"Nà shì wǒ zuì xǐhuan de dìfāng."}],"translation_vn":"Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua nơi đó. Nhà tôi ở ngay bên bờ sông. Nơi đó có những cây cổ thụ cao vút và những bãi cỏ xanh mướt. Mùa xuân, hoa bên bờ sông nở rộ, trông đặc biệt đẹp. Vẫn còn nhớ hồi nhỏ, cứ đến mùa hè là tôi lại xuống sông bơi. Lớn lên rồi, mỗi khi gặp chuyện gì không vui, tôi lại ra ngồi dưới gốc cây bên bờ sông, nghe tiếng chim hót, ngắm dòng nước, trò chuyện cùng những người bạn gặp được, những chuyện buồn chẳng mấy chốc là quên hết. Đó là nơi tôi yêu thích nhất.","audio_dialogue":"15-7.mp3","audio_vocab":"15-8.mp3"}]},{"id":16,"title_cn":"我听说有的熊猫出国了","title_pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le","title_vn":"Tôi nghe nói có con gấu trúc đã ra nước ngoài","goals":["Có thể nghe hiểu và miêu tả đặc điểm, tập tính và môi trường sống của động vật.","Có thể nghe hiểu và bày tỏ quan điểm cá nhân về động vật.","Nắm vững cách dùng câu so sánh (11), có thể diễn đạt sự khác biệt về số lượng hoặc thời gian giữa các sự vật.","Tìm hiểu những thông tin cơ bản về gấu trúc lớn."],"vocab":[{"hanzi":"脏","pinyin":"zāng","pos":"tt.","vn":"bẩn, dơ"},{"hanzi":"可爱","pinyin":"kě'ài","pos":"tt.","vn":"dễ thương, đáng yêu"},{"hanzi":"一会儿","pinyin":"yíhuìr","pos":"phó.","vn":"lúc...lúc... (chỉ sự thay đổi liên tục)"},{"hanzi":"脚","pinyin":"jiǎo","pos":"dt.","vn":"chân"},{"hanzi":"照顾","pinyin":"zhàogù","pos":"dgt.","vn":"chăm sóc"},{"hanzi":"好像","pinyin":"hǎoxiàng","pos":"dgt.","vn":"dường như, giống như"},{"hanzi":"认得","pinyin":"rènde","pos":"dgt.","vn":"nhận ra, quen biết"},{"hanzi":"周末","pinyin":"zhōumò","pos":"dt.","vn":"cuối tuần"},{"hanzi":"动物园","pinyin":"dòngwùyuán","pos":"dt.","vn":"vườn thú, sở thú"},{"hanzi":"动物","pinyin":"dòngwù","pos":"dt.","vn":"động vật"},{"hanzi":"大熊猫","pinyin":"dàxióngmāo","pos":"dt.","vn":"gấu trúc lớn"},{"hanzi":"奇怪","pinyin":"qíguài","pos":"tt.","vn":"kỳ lạ"},{"hanzi":"其实","pinyin":"qíshí","pos":"phó.","vn":"thực ra"},{"hanzi":"竹子","pinyin":"zhúzi","pos":"dt.","vn":"tre"},{"hanzi":"国宝","pinyin":"guóbǎo","pos":"dt.","vn":"quốc bảo"},{"hanzi":"全","pinyin":"quán","pos":"tt.","vn":"toàn bộ, cả"},{"hanzi":"野生","pinyin":"yěshēng","pos":"tt.","vn":"hoang dã"},{"hanzi":"关于","pinyin":"guānyú","pos":"giới.","vn":"về, liên quan đến"},{"hanzi":"饱","pinyin":"bǎo","pos":"tt.","vn":"no"},{"hanzi":"张","pinyin":"zhāng","pos":"dgt.","vn":"mở, há (miệng)"},{"hanzi":"嘴","pinyin":"zuǐ","pos":"dt.","vn":"miệng"},{"hanzi":"身边","pinyin":"shēnbiān","pos":"dt.","vn":"bên cạnh, bên người"},{"hanzi":"半天","pinyin":"bàntiān","pos":"sl.","vn":"nửa ngày, hồi lâu"},{"hanzi":"脸","pinyin":"liǎn","pos":"dt.","vn":"mặt"},{"hanzi":"大人","pinyin":"dàren","pos":"dt.","vn":"người lớn"},{"hanzi":"喜爱","pinyin":"xǐ'ài","pos":"dgt.","vn":"yêu thích"}],"grammar":[{"title":"并列复句\"一会儿……，一会儿……\" - Câu phức song song \"一会儿……，一会儿……\"","explanation_vn":"Câu phức song song \"一会儿……，一会儿……\" diễn tả những hành động khác nhau xảy ra trong một khoảng thời gian ngắn, hoặc một tình huống đối lập, luân phiên.","examples":[{"cn":"它一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Tā yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","vn":""},{"cn":"他一会儿进来，一会儿出去，忙得很。","pinyin":"Tā yíhuìr jìnlái, yíhuìr chūqù, máng de hěn.","vn":""},{"cn":"最近天气变化很快，一会儿冷，一会儿热。","pinyin":"Zuìjìn tiānqì biànhuà hěn kuài, yíhuìr lěng, yíhuìr rè.","vn":""}]},{"title":"介词\"关于\" - Giới từ \"关于\"","explanation_vn":"Giới từ \"关于\" đi kèm theo sau là danh từ, dùng để nêu ra đối tượng hoặc chủ đề có liên quan.","examples":[{"cn":"关于这个问题，我得慢慢给你讲。","pinyin":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vn":""},{"cn":"关于他的要求，我们还要开会以后再决定。","pinyin":"Guānyú tā de yāoqiú, wǒmen hái yào kāihuì yǐhòu zài juédìng.","vn":""},{"cn":"关于比赛的时间，我明天一定告诉大家。","pinyin":"Guānyú bǐsài de shíjiān, wǒ míngtiān yídìng gàosu dàjiā.","vn":""}]},{"title":"固定短语\"一般来说\" - Cụm cố định \"一般来说\"","explanation_vn":"\"一般来说\" là cụm từ cố định, nghĩa là \"nói chung\", \"trong đa số trường hợp là như vậy\", thường dùng ở đầu câu.","examples":[{"cn":"一般来说，熊猫每天要睡很多次觉。","pinyin":"Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","vn":""},{"cn":"一般来说，这种树每年开一次花。","pinyin":"Yìbān lái shuō, zhè zhǒng shù měi nián kāi yí cì huā.","vn":""},{"cn":"一般来说，学习外语需要多练习。","pinyin":"Yìbān lái shuō, xuéxí wàiyǔ xūyào duō liànxí.","vn":""}]},{"title":"比较句（11） - Câu so sánh (11)","explanation_vn":"Trong câu so sánh dùng \"比\", khi vị ngữ là động từ thường, có thể thêm \"多/少/早/晚\" trước động từ để diễn đạt sự khác biệt về số lượng hoặc thời gian giữa hai đối tượng. Cấu trúc cơ bản: A比B+多/少/早/晚+Động từ+Cụm số lượng.","examples":[{"cn":"冬天比夏天早关门一个小时。","pinyin":"Dōngtiān bǐ xiàtiān zǎo guānmén yí ge xiǎoshí.","vn":""},{"cn":"哥哥比弟弟多吃了三个饺子。","pinyin":"Gēge bǐ dìdi duō chīle sān ge jiǎozi.","vn":""},{"cn":"我比他晚到了十分钟。","pinyin":"Wǒ bǐ tā wǎn dàole shí fēnzhōng.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小雪","cn":"这只小猫你们养了多久了？","pinyin":"Zhè zhī xiǎo māo nǐmen yǎngle duōjiǔ le?"},{"speaker":"服务员","cn":"已经一年多了。第一天看见它的时候，它又脏又乱。","pinyin":"Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu luàn."},{"speaker":"刘小雪","cn":"现在它变得又干净又漂亮。","pinyin":"Xiànzài tā biàn de yòu gānjìng yòu piàoliang."},{"speaker":"服务员","cn":"是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá."},{"speaker":"刘小雪","cn":"你们把它照顾得真好。","pinyin":"Nǐmen bǎ tā zhàogù de zhēn hǎo."},{"speaker":"服务员","cn":"它就好像我们的孩子，我们照顾它，它也认得我们了。","pinyin":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le."},{"speaker":"刘小雪","cn":"妈妈，我们家也养一只小猫吧。","pinyin":"Māma, wǒmen jiā yě yǎng yì zhī xiǎo māo ba."},{"speaker":"王一雪","cn":"咱们没时间照顾，还是别养了，我周末带你去北京动物园看动物吧。","pinyin":"Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐ qù Běijīng Dòngwùyuán kàn dòngwù ba."}],"translation_vn":"Lưu Tiểu Tuyết: Con mèo con này nhà anh/chị nuôi được bao lâu rồi?\nNhân viên phục vụ: Đã hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa lộn xộn.\nLưu Tiểu Tuyết: Bây giờ nó trở nên vừa sạch sẽ vừa xinh đẹp.\nNhân viên phục vụ: Đúng vậy. Nó còn đặc biệt đáng yêu, lúc thì ngủ bên chân bạn, lúc thì leo trèo trên người bạn.\nLưu Tiểu Tuyết: Các anh chị chăm sóc nó thật tốt.\nNhân viên phục vụ: Nó giống như con của chúng tôi vậy, chúng tôi chăm sóc nó, nó cũng nhận ra chúng tôi rồi.\nLưu Tiểu Tuyết: Mẹ ơi, nhà mình cũng nuôi một con mèo con đi.\nVương Nhất Tuyết: Nhà mình không có thời gian chăm sóc đâu, thôi đừng nuôi nữa, cuối tuần mẹ đưa con đi vườn thú Bắc Kinh xem động vật nhé.","audio_dialogue":"16-1.mp3","audio_vocab":"16-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘小明","cn":"妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","pinyin":"Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?"},{"speaker":"王一雪","cn":"这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","pinyin":"Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dàmāoxióng."},{"speaker":"刘小明","cn":"大熊猫为什么只吃竹子不吃肉？","pinyin":"Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?"},{"speaker":"王一雪","cn":"它们跟人一样，也可以吃肉，但是对肉不感兴趣。","pinyin":"Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù."},{"speaker":"刘小明","cn":"大熊猫为什么是中国的国宝？","pinyin":"Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?"},{"speaker":"王一雪","cn":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","pinyin":"Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā."},{"speaker":"刘小明","cn":"我听说有的熊猫出国了，他们去哪儿了？","pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?"},{"speaker":"王一雪","cn":"关于这个问题，我得慢慢给你讲。","pinyin":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng."},{"speaker":"刘小雪","cn":"弟弟，你真是\"十万个为什么\"。","pinyin":"Dìdi, nǐ zhēn shì \"shíwàn gè wèishénme\"."}],"translation_vn":"Lưu Tiểu Minh: Mẹ ơi, tên gọi gấu trúc lớn này nghe lạ quá, chúng có quan hệ gì với mèo không?\nVương Nhất Tuyết: Câu hỏi này hay đấy, chúng không có quan hệ gì với mèo cả, thực ra nên gọi là gấu mèo lớn mới đúng.\nLưu Tiểu Minh: Tại sao gấu trúc lớn chỉ ăn tre mà không ăn thịt?\nVương Nhất Tuyết: Chúng cũng giống như con người, cũng có thể ăn thịt, nhưng không hứng thú với thịt.\nLưu Tiểu Minh: Tại sao gấu trúc lớn là quốc bảo của Trung Quốc?\nVương Nhất Tuyết: Trên toàn thế giới chỉ có Trung Quốc mới có gấu trúc lớn hoang dã, Trung Quốc là quê nhà của gấu trúc lớn.\nLưu Tiểu Minh: Con nghe nói có con gấu trúc đã ra nước ngoài, chúng đã đi đâu vậy?\nVương Nhất Tuyết: Về vấn đề này thì mẹ phải từ từ kể cho con nghe.\nLưu Tiểu Tuyết: Em trai à, em đúng là \"trăm nghìn câu hỏi vì sao\" mà.","audio_dialogue":"16-3.mp3","audio_vocab":"16-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘小雪","cn":"这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","pinyin":"Zhè zhī dàxióngmāo yíhuìr pá shàngqù, yíhuìr tiào xiàlái, kě'ài jíle!"},{"speaker":"王一雪","cn":"它好像还没吃饱，站起来张着嘴找吃的呢。","pinyin":"Tā hǎoxiàng hái méi chībǎo, zhàn qǐlái zhāngzhe zuǐ zhǎo chī de ne."},{"speaker":"刘小雪","cn":"它身边那只熊猫半天没动，是不是在睡觉呢？","pinyin":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bú shì zài shuìjiào ne?"},{"speaker":"王一雪","cn":"我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","pinyin":"Wǒ kàn bu jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào."},{"speaker":"刘小雪","cn":"对，除了睡觉以外，很多时间都在吃东西。","pinyin":"Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi."},{"speaker":"刘小明","cn":"大熊猫的生活真舒服啊！","pinyin":"Dàxióngmāo de shēnghuó zhēn shūfu a!"},{"speaker":"刘小雪","cn":"妈妈，您帮我和这两只大熊猫照一张照片吧。","pinyin":"Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba."}],"translation_vn":"Lưu Tiểu Tuyết: Con gấu trúc này lúc thì leo lên, lúc thì nhảy xuống, đáng yêu quá đi mất!\nVương Nhất Tuyết: Nó có vẻ như vẫn chưa ăn no, đứng dậy há miệng tìm đồ ăn kìa.\nLưu Tiểu Tuyết: Con gấu trúc bên cạnh nó nửa ngày rồi không động đậy, có phải đang ngủ không nhỉ?\nVương Nhất Tuyết: Mẹ không nhìn thấy mặt nó, có thể là vậy. Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần.\nLưu Tiểu Tuyết: Đúng vậy, ngoài ngủ ra, phần lớn thời gian đều dùng để ăn.\nLưu Tiểu Minh: Cuộc sống của gấu trúc thật thoải mái!\nLưu Tiểu Tuyết: Mẹ ơi, mẹ giúp con chụp một tấm ảnh với hai con gấu trúc này đi.","audio_dialogue":"16-5.mp3","audio_vocab":"16-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天我带小雪和小明去动物园玩了。北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","pinyin":"Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le. Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmiàn yǒu fēicháng duō de dòngwù, dāngrán, dàren hé háizi zuì xǐ'ài de háishi dàxióngmāo. Měitiān yǒu hěn duō yóukè qù xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě'ài de dàxióngmāo pāizhào. Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí ge xiǎoshí. Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì ge búcuò de xuǎnzé."}],"translation_vn":"Hôm nay tôi đã đưa Tiểu Tuyết và Tiểu Minh đi chơi sở thú. Vườn thú Bắc Kinh là vườn thú rất nổi tiếng của Trung Quốc, bên trong có rất nhiều động vật, tất nhiên, thứ mà người lớn và trẻ em yêu thích nhất vẫn là gấu trúc lớn. Mỗi ngày có rất nhiều du khách đến nhà gấu trúc, họ mang theo máy ảnh để chụp hình cho những chú gấu trúc đáng yêu. Vườn thú mở cửa lúc bảy giờ rưỡi sáng, đóng cửa lúc bảy giờ tối, mùa đông du khách ít hơn mùa hè, nên cũng đóng cửa sớm hơn bình thường một tiếng. Nếu lần đầu đến Bắc Kinh du lịch, cùng người nhà đi vườn thú Bắc Kinh là một lựa chọn không tồi.","audio_dialogue":"16-7.mp3","audio_vocab":"16-8.mp3"}]},{"id":17,"title_cn":"我要多向认真的人学习","title_pinyin":"Wǒ yào duō xiàng rènzhēn de rén xuéxí","title_vn":"Tôi phải học hỏi nhiều hơn từ những người làm việc nghiêm túc","goals":["Có thể nghe hiểu và bày tỏ các cảm xúc như buồn bã, bối rối, không hài lòng trong lòng.","Có thể nghe hiểu và sử dụng câu hỏi phản vấn \"不是……吗？\" để biểu đạt tình cảm và ngữ khí.","Nắm vững cách dùng \"只有\", có thể diễn đạt điều kiện duy nhất và kết quả."],"vocab":[{"hanzi":"向","pinyin":"xiàng","pos":"giới.","vn":"hướng về, về phía"},{"hanzi":"楼梯","pinyin":"lóutī","pos":"dt.","vn":"cầu thang"},{"hanzi":"害怕","pinyin":"hàipà","pos":"dgt.","vn":"sợ hãi"},{"hanzi":"生气","pinyin":"shēngqì","pos":"dgt.","vn":"tức giận, nổi giận"},{"hanzi":"常见","pinyin":"chángjiàn","pos":"tt.","vn":"thường gặp, phổ biến"},{"hanzi":"聪明","pinyin":"cōngmíng","pos":"tt.","vn":"thông minh"},{"hanzi":"错","pinyin":"cuò","pos":"dt.","vn":"lỗi, sai lầm"},{"hanzi":"认为","pinyin":"rènwéi","pos":"dgt.","vn":"cho rằng"},{"hanzi":"到处","pinyin":"dàochù","pos":"phó.","vn":"khắp nơi"},{"hanzi":"继续","pinyin":"jìxù","pos":"dgt.","vn":"tiếp tục"},{"hanzi":"同意","pinyin":"tóngyì","pos":"dgt.","vn":"đồng ý"},{"hanzi":"可","pinyin":"kě","pos":"liên.","vn":"nhưng"},{"hanzi":"屋子","pinyin":"wūzi","pos":"dt.","vn":"phòng"},{"hanzi":"有关","pinyin":"yǒuguān","pos":"dgt.","vn":"có liên quan đến"},{"hanzi":"关机","pinyin":"guānjī","pos":"dgt.","vn":"tắt máy (điện thoại)"},{"hanzi":"前天","pinyin":"qiántiān","pos":"dt.","vn":"hôm kia"},{"hanzi":"留学","pinyin":"liúxué","pos":"dgt.","vn":"du học"},{"hanzi":"国家","pinyin":"guójiā","pos":"dt.","vn":"quốc gia, đất nước"},{"hanzi":"比如","pinyin":"bǐrú","pos":"dgt.","vn":"ví dụ như"},{"hanzi":"查","pinyin":"chá","pos":"dgt.","vn":"tra cứu"},{"hanzi":"有用","pinyin":"yǒuyòng","pos":"tt.","vn":"hữu ích, có ích"},{"hanzi":"容易","pinyin":"róngyì","pos":"tt.","vn":"dễ dàng"},{"hanzi":"回答","pinyin":"huídá","pos":"dgt.","vn":"trả lời"},{"hanzi":"方向","pinyin":"fāngxiàng","pos":"dt.","vn":"phương hướng"},{"hanzi":"只有","pinyin":"zhǐyǒu","pos":"liên.","vn":"chỉ có"},{"hanzi":"真正","pinyin":"zhēnzhèng","pos":"phó.","vn":"thực sự, thật sự"},{"hanzi":"难题","pinyin":"nántí","pos":"dt.","vn":"vấn đề khó, bài toán khó"}],"grammar":[{"title":"介词\"向\" - Giới từ \"向\"","explanation_vn":"Giới từ \"向\" đi kèm theo sau là đại từ, danh từ hoặc cụm danh từ, biểu thị phương hướng hoặc đối tượng của hành động.","examples":[{"cn":"别再向前走了。","pinyin":"Bié zài xiàng qián zǒu le.","vn":""},{"cn":"以后我要多向认真的人学习。","pinyin":"Yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","vn":""},{"cn":"孩子一看见妈妈，就向她跑过去了。","pinyin":"Háizi yí kànjiàn māma, jiù xiàng tā pǎo guòqù le.","vn":""}]},{"title":"反问句\"不是……吗？\" - Câu hỏi phản vấn \"不是……吗？\"","explanation_vn":"Câu hỏi phản vấn \"不是……吗？\" thường dùng để biểu đạt sự không hiểu hoặc không hài lòng của người nói, đôi khi cũng dùng để nhắc nhở hoặc xác nhận. Hình thức là phủ định nhưng ý nghĩa lại là khẳng định.","examples":[{"cn":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vn":""},{"cn":"你不是说今天有事吗？为什么来了？","pinyin":"Nǐ bú shì shuō jīntiān yǒushì ma? Wèishénme lái le?","vn":""},{"cn":"考试不是下个月吗？你怎么今天就开始复习？","pinyin":"Kǎoshì bú shì xià ge yuè ma? Nǐ zěnme jīntiān jiù kāishǐ fùxí?","vn":""}]},{"title":"递进复句\"……，更……\" - Câu phức tăng tiến \"……，更……\"","explanation_vn":"Trong câu phức tăng tiến \"……，更……\", vế thứ hai biểu thị mức độ sâu hơn so với vế thứ nhất.","examples":[{"cn":"我还没想好学什么，更没想好去哪个国家。","pinyin":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vn":""},{"cn":"想提高中文水平要多听多看，更要多说多练。","pinyin":"Xiǎng tígāo Zhōngwén shuǐpíng yào duō tīng duō kàn, gèng yào duō shuō duō liàn.","vn":""},{"cn":"来中国学习，我学会了中文，更了解了中国文化。","pinyin":"Lái Zhōngguó xuéxí, wǒ xuéhuìle Zhōngwén, gèng liǎojiěle Zhōngguó wénhuà.","vn":""}]},{"title":"条件复句\"只有……，才……\" - Câu phức điều kiện \"只有……，才……\"","explanation_vn":"Trong câu phức điều kiện \"只有……，才……\", vế đi sau \"只有\" là điều kiện duy nhất để đạt được kết quả; nếu không có điều kiện này thì sẽ không có kết quả nêu sau \"才\".","examples":[{"cn":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","pinyin":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","vn":""},{"cn":"只有每天锻炼身体，才会越来越健康。","pinyin":"Zhǐyǒu měitiān duànliàn shēntǐ, cái huì yuè lái yuè jiànkāng.","vn":""},{"cn":"只有多听、多说、多看，你的中文水平才能提高。","pinyin":"Zhǐyǒu duō tīng, duō shuō, duō kàn, nǐ de Zhōngwén shuǐpíng cái néng tígāo.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小雪","cn":"别再向前走了，李老师的办公室已经到了。","pinyin":"Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le."},{"speaker":"同学","cn":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","pinyin":"Nǐ jìnqù ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī."},{"speaker":"刘小雪","cn":"怎么回事？","pinyin":"Zěnme huí shì?"},{"speaker":"同学","cn":"最近我做错了好几件事，我怕李老师生气。","pinyin":"Zuìjìn wǒ zuòcuòle hǎo jǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì."},{"speaker":"刘小雪","cn":"你想多了，做错事情是很常见的。","pinyin":"Nǐ xiǎngduō le, zuòcuò shìqing shì hěn chángjiàn de."},{"speaker":"同学","cn":"我把简单的事情做错了，李老师一定觉得我不认真。","pinyin":"Wǒ bǎ jiǎndān de shìqing zuòcuò le, Lǐ lǎoshī yídìng juéde wǒ bú rènzhēn."},{"speaker":"刘小雪","cn":"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","pinyin":"Yǒude rén suīrán hěn cōngmíng, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le."},{"speaker":"同学","cn":"你说的就是我，以后我要多向认真的人学习。","pinyin":"Nǐ shuō de jiù shì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí."}],"translation_vn":"Lưu Tiểu Tuyết: Đừng đi về phía trước nữa, văn phòng thầy Lý đến rồi.\nBạn học: Cậu vào đi, mình đợi cậu ở chỗ cầu thang. Mình sợ gặp thầy Lý.\nLưu Tiểu Tuyết: Chuyện gì vậy?\nBạn học: Gần đây mình đã làm sai mấy việc, mình sợ thầy Lý nổi giận.\nLưu Tiểu Tuyết: Cậu nghĩ nhiều rồi, làm sai việc là chuyện rất thường gặp mà.\nBạn học: Mình đã làm sai những việc đơn giản, thầy Lý chắc chắn sẽ nghĩ mình không nghiêm túc.\nLưu Tiểu Tuyết: Có những người tuy rất thông minh, nhưng lại hay mắc lỗi trong những việc đơn giản, vì họ cho rằng việc đơn giản nên sẽ không làm một cách nghiêm túc nữa.\nBạn học: Cậu nói đúng là mình đấy, sau này mình phải học hỏi nhiều hơn từ những người làm việc nghiêm túc.","audio_dialogue":"17-1 @xitoytili_luoluodafang.mp3","audio_vocab":"17-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"太阳从西边出来了？这几天怎么总是在图书馆看见你？","pinyin":"Tàiyáng cóng xībian chūlái le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?"},{"speaker":"陈天中","cn":"这有什么奇怪的？我是来学习的。","pinyin":"Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de."},{"speaker":"白家月","cn":"你怎么还来图书馆学习？同学们都在到处找工作呢。","pinyin":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne."},{"speaker":"陈天中","cn":"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","pinyin":"Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bàmā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan."},{"speaker":"白家月","cn":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū."},{"speaker":"陈天中","cn":"你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","pinyin":"Nǐ shuō de duì, wǒ jìde nàge wūzi lǐ yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao."}],"translation_vn":"Bạch Gia Nguyệt: Mặt trời mọc từ hướng tây rồi à? Sao mấy ngày nay lúc nào cũng thấy cậu ở thư viện vậy?\nTrần Thiên Trung: Có gì lạ đâu? Mình đến để học mà.\nBạch Gia Nguyệt: Sao cậu còn đến thư viện học nữa? Các bạn cùng lớp đều đang đi khắp nơi tìm việc làm kìa.\nTrần Thiên Trung: Mình không muốn đi làm ngay bây giờ, vẫn muốn tiếp tục học, bố mẹ mình cũng đồng ý. Nhưng mình vẫn chưa nghĩ ra nên học gì, nên đến thư viện xem thử.\nBạch Gia Nguyệt: Cậu không phải thích chơi máy tính sao? Cậu có thể đi xem những sách liên quan đến máy tính.\nTrần Thiên Trung: Cậu nói đúng đấy, mình nhớ trong căn phòng đó có một số sách liên quan đến máy tính, mình đi tìm thử xem.","audio_dialogue":"17-3 @xitoytili_luoluodafang.mp3","audio_vocab":"17-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"李文","cn":"天中，你的手机怎么关机了？","pinyin":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?"},{"speaker":"陈天中","cn":"我的手机没电了。你找我有事吗？","pinyin":"Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒushì ma?"},{"speaker":"李文","cn":"前天我看见家月了，她告诉我你打算继续留学？","pinyin":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuan jìxù liúxué?"},{"speaker":"陈天中","cn":"是，可是我还没想好学什么，更没想好去哪个国家。","pinyin":"Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā."},{"speaker":"李文","cn":"你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","pinyin":"Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàlǐ yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng."},{"speaker":"陈天中","cn":"好，那我上网查一查。","pinyin":"Hǎo, nà wǒ shàngwǎng chá yi chá."},{"speaker":"李文","cn":"我给你介绍几个有用的网站。","pinyin":"Wǒ gěi nǐ jièshào jǐ ge yǒuyòng de wǎngzhàn."}],"translation_vn":"Lý Văn: Thiên Trung, sao điện thoại của cậu lại tắt máy vậy?\nTrần Thiên Trung: Điện thoại mình hết pin rồi. Cậu tìm mình có việc gì à?\nLý Văn: Hôm kia mình gặp Gia Nguyệt, cô ấy nói với mình là cậu định tiếp tục đi du học?\nTrần Thiên Trung: Đúng vậy, nhưng mình vẫn chưa nghĩ ra nên học gì, càng chưa nghĩ ra nên đi nước nào nữa.\nLý Văn: Cậu có thể sang Trung Quốc học tiếng Trung mà. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải, ở đó có rất nhiều trường đại học tốt, cũng có rất nhiều du học sinh.\nTrần Thiên Trung: Được, vậy mình lên mạng tra thử xem.\nLý Văn: Mình giới thiệu cho cậu vài trang web hữu ích nhé.","audio_dialogue":"17-5 @xitoytili_luoluodafang.mp3","audio_vocab":"17-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"大学生活马上就要结束了，我最近经常被问到一个问题——\"你以后想做什么\"，这个问题真不容易回答。我也问了几个同学，大家选择的方向都不同。有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。对我来说，想清楚\"真正喜欢什么\"是个难题。","pinyin":"Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèndào yí ge wèntí — \"nǐ yǐhòu xiǎng zuò shénme\", zhège wèntí zhēn bù róngyì huídá. Wǒ yě wènle jǐ ge tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng. Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuan chūguó liúxué, hái yǒude juédìng xiān zhǎo gōngzuò. Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé. Duì wǒ lái shuō, xiǎng qīngchu \"zhēnzhèng xǐhuan shénme\" shì ge nántí."}],"translation_vn":"Cuộc sống đại học sắp kết thúc rồi, gần đây tôi thường xuyên bị hỏi một câu hỏi — \"Sau này bạn muốn làm gì\", câu hỏi này thật không dễ trả lời. Tôi cũng đã hỏi vài người bạn học, hướng lựa chọn của mọi người đều khác nhau. Có người muốn tiếp tục học ở trường, có người định đi du học nước ngoài, lại có người quyết định tìm việc làm trước. Tôi cho rằng chỉ khi nghĩ rõ bản thân thực sự thích gì, mới có thể đưa ra lựa chọn phù hợp nhất. Đối với tôi, việc nghĩ rõ \"thực sự thích gì\" là một bài toán khó.","audio_dialogue":"17-7 @xitoytili_luoluodafang.mp3","audio_vocab":"17-8 @xitoytili_luoluodafang.mp3"}]},{"id":18,"title_cn":"我学会了包饺子","title_pinyin":"Wǒ xuéhuìle bāo jiǎozi","title_vn":"Tôi đã học được cách gói sủi cảo","goals":["Có thể nghe hiểu và miêu tả những thay đổi trong cuộc sống và trải nghiệm trưởng thành.","Có thể nghe hiểu và sử dụng số ước lượng để diễn đạt số lượng không chắc chắn.","Nắm vững cách dùng \"只要\", có thể diễn đạt điều kiện đủ và kết quả.","Tìm hiểu phong tục của ngày lễ truyền thống Trung Quốc \"Xuân Tiết\" (Tết Nguyên Đán)."],"vocab":[{"hanzi":"怎样","pinyin":"zěnyàng","pos":"đt.","vn":"như thế nào"},{"hanzi":"过节","pinyin":"guòjié","pos":"dgt.","vn":"ăn mừng lễ, đón lễ"},{"hanzi":"节","pinyin":"jié","pos":"dt.","vn":"lễ, tết"},{"hanzi":"节日","pinyin":"jiérì","pos":"dt.","vn":"ngày lễ"},{"hanzi":"联欢","pinyin":"liánhuān","pos":"dgt.","vn":"liên hoan, họp mặt vui vẻ"},{"hanzi":"大概","pinyin":"dàgài","pos":"phó.","vn":"khoảng, đại khái"},{"hanzi":"春节","pinyin":"Chūnjié","pos":"danh từ riêng","vn":"Tết Nguyên Đán (Xuân Tiết)"},{"hanzi":"阿姨","pinyin":"āyí","pos":"dt.","vn":"dì, cô"},{"hanzi":"叔叔","pinyin":"shūshu","pos":"dt.","vn":"chú, bác"},{"hanzi":"收","pinyin":"shōu","pos":"dgt.","vn":"nhận"},{"hanzi":"总","pinyin":"zǒng","pos":"phó.","vn":"luôn luôn"},{"hanzi":"起","pinyin":"qǐ","pos":"dgt.","vn":"lên (bổ ngữ chỉ sự đề cập/bắt đầu, đi sau động từ)"},{"hanzi":"见面","pinyin":"jiànmiàn","pos":"dgt.","vn":"gặp mặt"},{"hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","pos":"dt.","vn":"nước khoáng"},{"hanzi":"刚刚","pinyin":"gānggāng","pos":"phó.","vn":"vừa mới"},{"hanzi":"出发","pinyin":"chūfā","pos":"dgt.","vn":"xuất phát, khởi hành"},{"hanzi":"不久","pinyin":"bùjiǔ","pos":"tt.","vn":"chẳng bao lâu, không lâu sau"},{"hanzi":"发生","pinyin":"fāshēng","pos":"dgt.","vn":"xảy ra, phát sinh"},{"hanzi":"刚","pinyin":"gāng","pos":"phó.","vn":"vừa, vừa mới (cách đây không lâu)"},{"hanzi":"只要","pinyin":"zhǐyào","pos":"liên.","vn":"chỉ cần"},{"hanzi":"学期","pinyin":"xuéqī","pos":"dt.","vn":"học kỳ"},{"hanzi":"毕业","pinyin":"bìyè","pos":"dgt.","vn":"tốt nghiệp"},{"hanzi":"出生","pinyin":"chūshēng","pos":"dgt.","vn":"sinh ra, ra đời"},{"hanzi":"过去","pinyin":"guòqù","pos":"dt.","vn":"quá khứ"},{"hanzi":"懂得","pinyin":"dǒngde","pos":"dgt.","vn":"hiểu được"},{"hanzi":"坚持","pinyin":"jiānchí","pos":"dgt.","vn":"kiên trì"},{"hanzi":"完成","pinyin":"wánchéng","pos":"dgt.","vn":"hoàn thành"},{"hanzi":"目标","pinyin":"mùbiāo","pos":"dt.","vn":"mục tiêu"},{"hanzi":"发展","pinyin":"fāzhǎn","pos":"dgt.","vn":"phát triển"}],"grammar":[{"title":"概数表达法 - Cách diễn đạt số ước lượng","explanation_vn":"Trong tiếng Hán, hai con số liền kề nhau dùng chung với nhau để biểu thị một số lượng không chắc chắn, ước chừng.","examples":[{"cn":"春节大概放七八天假。","pinyin":"Chūnjié dàgài fàng qī-bā tiān jià.","vn":""},{"cn":"教室里来了五六个学生。","pinyin":"Jiàoshì lǐ láile wǔ-liù ge xuésheng.","vn":""},{"cn":"这些照片是三四年前照的吧？","pinyin":"Zhèxiē zhàopiàn shì sān-sì nián qián zhào de ba?","vn":""}]},{"title":"\"刚才\"和\"刚刚\" - So sánh \"刚才\" và \"刚刚\"","explanation_vn":"\"刚才\" là danh từ chỉ thời gian, biểu thị một khoảng thời gian rất ngắn trước đó, thường là vài phút trước; có thể đặt ở đầu câu hoặc sau chủ ngữ, trước động từ. \"刚刚\" là phó từ chỉ thời gian, biểu thị khoảng thời gian không dài đối với người nói, có thể là vài phút, vài ngày thậm chí vài tháng; \"刚刚\" nên đặt sau chủ ngữ, trước động từ.","examples":[{"cn":"刚才的电话是我妈妈打来的。","pinyin":"Gāngcái de diànhuà shì wǒ māma dǎlái de.","vn":""},{"cn":"我刚才看过一遍，不想再看了。","pinyin":"Wǒ gāngcái kànguo yí biàn, bù xiǎng zài kàn le.","vn":""},{"cn":"我刚刚看视频学会了包饺子。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi.","vn":""},{"cn":"他刚刚来北京两个月。","pinyin":"Tā gānggāng lái Běijīng liǎng ge yuè.","vn":""}]},{"title":"条件复句\"只要……，就……\" - Câu phức điều kiện \"只要……，就……\"","explanation_vn":"Trong câu phức điều kiện \"只要……，就……\", vế đi sau \"只要\" là điều kiện đủ cần thiết, chỉ cần có điều kiện này là có thể tạo ra kết quả nêu sau \"就\". Chủ ngữ có thể đặt trước hoặc sau \"只要\". Nếu câu có hai chủ ngữ, chủ ngữ thứ hai phải đặt trước \"就\".","examples":[{"cn":"我只要几天不跟他视频，就很想他。","pinyin":"Wǒ zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vn":""},{"cn":"只要你同意，我们就这么决定了。","pinyin":"Zhǐyào nǐ tóngyì, wǒmen jiù zhème juédìng le.","vn":""},{"cn":"只要你坚持每天早睡，身体就一定会好起来。","pinyin":"Zhǐyào nǐ jiānchí měitiān zǎo shuì, shēntǐ jiù yídìng huì hǎo qǐlái.","vn":""}]},{"title":"固定格式\"从……起\" - Cấu trúc cố định \"从……起\"","explanation_vn":"Cấu trúc cố định \"从……起\" có nghĩa là \"从……开始\" (bắt đầu từ...), phần lớn dùng để biểu thị thời gian, thường đặt ở đầu câu làm trạng ngữ.","examples":[{"cn":"他从那时起就努力学习。","pinyin":"Tā cóng nàshí qǐ jiù nǔlì xuéxí.","vn":""},{"cn":"从那天起，我们就变成了好朋友。","pinyin":"Cóng nà tiān qǐ, wǒmen jiù biànchéngle hǎo péngyou.","vn":""},{"cn":"从那次旅游起，我对中国文化更有兴趣了。","pinyin":"Cóng nà cì lǚyóu qǐ, wǒ duì Zhōngguó wénhuà gèng yǒu xìngqù le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"我要在中国过年，真开心。","pinyin":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn."},{"speaker":"李文","cn":"第一次请外国朋友来家里过春节，我也很高兴。","pinyin":"Dì-yī cì qǐng wàiguó péngyou lái jiā lǐ guò Chūnjié, wǒ yě hěn gāoxìng."},{"speaker":"白家月","cn":"你们怎样过节？","pinyin":"Nǐmen zěnyàng guòjié?"},{"speaker":"李文","cn":"春节是中国最重要的节日，我们一般会回家，跟家人一起过。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huíjiā, gēn jiārén yìqǐ guò."},{"speaker":"白家月","cn":"那你跟家人会一起做什么？","pinyin":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?"},{"speaker":"李文","cn":"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","pinyin":"Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào."},{"speaker":"白家月","cn":"听起来很有意思。春节放几天假？","pinyin":"Tīng qǐlái hěn yǒu yìsi. Chūnjié fàng jǐ tiān jià?"},{"speaker":"李文","cn":"大概七八天。","pinyin":"Dàgài qī-bā tiān."}],"translation_vn":"Bạch Gia Nguyệt: Mình sắp được đón Tết ở Trung Quốc, thật vui quá.\nLý Văn: Lần đầu tiên mời bạn nước ngoài đến nhà ăn Tết, mình cũng rất vui.\nBạch Gia Nguyệt: Các bạn đón Tết như thế nào?\nLý Văn: Tết Nguyên Đán là ngày lễ quan trọng nhất của Trung Quốc, chúng mình thường sẽ về nhà, đón Tết cùng người thân.\nBạch Gia Nguyệt: Vậy cậu sẽ cùng gia đình làm những gì?\nLý Văn: Nhà mình sẽ vừa gói sủi cảo, vừa xem Chương trình Liên hoan Xuân Tiết, mãi đến sau mười hai giờ mới đi ngủ.\nBạch Gia Nguyệt: Nghe có vẻ rất thú vị. Tết được nghỉ mấy ngày vậy?\nLý Văn: Khoảng bảy tám ngày.","audio_dialogue":"18-1 @xitoytili_luoluodafang.mp3","audio_vocab":"18-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","pinyin":"Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià."},{"speaker":"李叔叔","cn":"谢谢家月，你太客气了！","pinyin":"Xièxie Jiāyuè, nǐ tài kèqi le!"},{"speaker":"张阿姨","cn":"总听小文说起你，今天终于有机会见面了。","pinyin":"Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le."},{"speaker":"白家月","cn":"谢谢您和叔叔请我来家里做客。","pinyin":"Xièxie nín hé shūshu qǐng wǒ lái jiā lǐ zuòkè."},{"speaker":"李叔叔","cn":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","pinyin":"Zhuōzi shàng yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná."},{"speaker":"张阿姨","cn":"你先坐着看会儿电视，饺子很快就包好了。","pinyin":"Nǐ xiān zuòzhe kàn huìr diànshì, jiǎozi hěn kuài jiù bāohǎo le."},{"speaker":"白家月","cn":"我刚刚看视频学会了包饺子，我跟你们一起包吧。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba."}],"translation_vn":"Bạch Gia Nguyệt: Dì Trương, chú Lý, chúc mừng năm mới! Đây là món quà con chuẩn bị, mời dì chú nhận cho.\nChú Lý: Cảm ơn Gia Nguyệt, con khách sáo quá!\nDì Trương: Dì vẫn luôn nghe Tiểu Văn nhắc đến con, hôm nay cuối cùng cũng có dịp gặp mặt rồi.\nBạch Gia Nguyệt: Cảm ơn dì và chú đã mời con đến nhà chơi.\nChú Lý: Trên bàn có nước giải khát, còn có nước khoáng nữa, con muốn uống gì thì tự lấy nhé.\nDì Trương: Con cứ ngồi xem ti vi một lát, sủi cảo sắp gói xong rồi.\nBạch Gia Nguyệt: Con vừa mới xem video học được cách gói sủi cảo, con gói cùng mọi người nhé.","audio_dialogue":"18-3 @xitoytili_luoluodafang.mp3","audio_vocab":"18-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月","cn":"这张照片是李文出国前照的吗？","pinyin":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?"},{"speaker":"张阿姨","cn":"对，这是他从北京出发时，我们全家在机场照的。","pinyin":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quánjiā zài jīchǎng zhào de."},{"speaker":"白家月","cn":"那是三四年前吧？","pinyin":"Nà shì sān-sì nián qián ba?"},{"speaker":"张阿姨","cn":"是啊，时间过得真快，好像是不久前发生的一样。","pinyin":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng."},{"speaker":"白家月","cn":"您一定特别想李文吧？","pinyin":"Nín yídìng tèbié xiǎng Lǐ Wén ba?"},{"speaker":"张阿姨","cn":"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","pinyin":"Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā."},{"speaker":"白家月","cn":"还有最后一个学期就要毕业了，他很快就会回来了。","pinyin":"Hái yǒu zuìhòu yí ge xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílái le."}],"translation_vn":"Bạch Gia Nguyệt: Tấm ảnh này là chụp trước khi Lý Văn ra nước ngoài ạ?\nDì Trương: Đúng rồi, đây là lúc nó xuất phát từ Bắc Kinh, cả nhà dì chụp ở sân bay.\nBạch Gia Nguyệt: Lúc đó là khoảng ba bốn năm trước ạ?\nDì Trương: Đúng vậy, thời gian trôi nhanh thật, cứ như mới xảy ra gần đây vậy.\nBạch Gia Nguyệt: Chắc dì nhớ Lý Văn lắm phải không ạ?\nDì Trương: Lúc nó vừa rời nhà, dì rất không quen, chỉ cần vài ngày không gọi video với nó là dì nhớ nó lắm.\nBạch Gia Nguyệt: Còn một học kỳ cuối nữa là anh ấy sẽ tốt nghiệp rồi, anh ấy sẽ sớm trở về thôi ạ.","audio_dialogue":"18-5 @xitoytili_luoluodafang.mp3","audio_vocab":"18-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这次来中国，我最高兴的是认识了李文的父母。他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。李文高中的时候想学医，从那时起就努力学习。高三的时候，因为成绩特别好，他得到了出国留学的机会。在他身上，我懂得了，只要一直坚持，就能完成自己的目标。我相信，他以后一定会发展得更好。","pinyin":"Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshile Lǐ Wén de fùmǔ. Tāmen gěi wǒ kànle Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎngle hěn duō tā guòqù de gùshi. Lǐ Wén gāozhōng de shíhou xiǎng xué yī, cóng nàshí qǐ jiù nǔlì xuéxí. Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédàole chūguó liúxué de jīhuì. Zài tā shēnshang, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo. Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo."}],"translation_vn":"Lần này đến Trung Quốc, điều khiến tôi vui nhất là được quen biết bố mẹ của Lý Văn. Họ cho tôi xem những tấm ảnh lúc Lý Văn mới sinh ra, còn kể cho tôi nghe rất nhiều câu chuyện trong quá khứ của anh ấy. Khi học trung học phổ thông, Lý Văn muốn học y, từ đó anh đã nỗ lực học tập. Năm lớp mười hai, vì thành tích đặc biệt tốt, anh đã có được cơ hội đi du học nước ngoài. Qua anh ấy, tôi đã hiểu ra rằng, chỉ cần luôn kiên trì, thì sẽ có thể hoàn thành mục tiêu của bản thân. Tôi tin rằng, sau này anh ấy chắc chắn sẽ phát triển tốt hơn nữa.","audio_dialogue":"18-7 @xitoytili_luoluodafang.mp3","audio_vocab":"18-8 @xitoytili_luoluodafang.mp3"}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};